local config = {
  ui_story_5045_50450101_1_dialog_content = "<color=#737378>Waktu: 17:00</color>",
  ui_story_5045_50450101_2_dialog_content = "<color=#737378>Lokasi: Balai Kehakiman Lumo</color>",
  ui_story_5045_50450101_3_dialog_content = "<color=#737378>Bum!</color>",
  ui_story_5045_50450101_4_dialog_content = "Ahem... Harap diam, semuanya.",
  ui_story_5045_50450101_5_dialog_content = "Pencurian tercela dari jenis terburuk telah terjadi di dalam Hall of Justice hari ini.",
  ui_story_5045_50450101_6_dialog_content = "Saya akan memimpin sebagai hakim atas kasus keji ini.",
  ui_story_5045_50450101_7_dialog_content = "Saya bersumpah untuk menghormati atasan saya dengan menegakkan hukum, dan memberikan penilaian yang adil dan tidak memihak dengan kemampuan terbaik saya!",
  ui_story_5045_50450101_8_dialog_content = "<size=45>Malam Putih di atas. Pengadilan sekarang dalam sesi!</size>",
  ui_story_5045_50450101_9_dialog_content = "Memulai...",
  ui_story_5045_50450101_10_dialog_content = "<size=32>Siapa yang harus menjadi yang pertama berbicara? Aku sangat gugup barusan sampai pikiranku benar-benar kosong...</size>",
  ui_story_5045_50450101_11_dialog_content = "(Wow, mereka sudah membuatnya Angel seorang hakim penuh!)",
  ui_story_5045_50450101_12_dialog_content = "(Uh... Kenapa dia menatap ke arahku?)",
  ui_story_5045_50450101_13_dialog_content = "(Kurasa itu tidak masalah. Sebagai temannya, aku harus melakukan apa saja untuk menyemangatinya!)",
  ui_story_5045_50450101_14_option_content = "Lambaikan tangan padanya!",
  ui_story_5045_50450101_15_option_content = "Tersenyumlah padanya!",
  ui_story_5045_50450101_16_dialog_content = "PlayerName...?",
  ui_story_5045_50450101_17_dialog_content = "Oh, ya!",
  ui_story_5045_50450101_18_dialog_content = "Mari kita mulai dengan mengundang PlayerName, itu <color=#1875ad>mengira</color> dalam hal ini, untuk berdiri di depan pengadilan!",
  ui_story_5045_50450101_19_dialog_content = "Hah? K-Kapan aku menjadi tersangka?!",
  ui_story_5045_50450101_20_dialog_content = "Saya hanya datang ke Lumo Hall of Justice karena saya diundang ke sini...",
  ui_story_5045_50450101_21_dialog_content = "<color=#737378>Dor, dor, dor!</color>",
  ui_story_5045_50450101_22_dialog_content = "Kesunyian!",
  ui_story_5045_50450101_23_dialog_content = "Harap patuhi aturan pengadilan, dan jawab pertanyaan saya dengan jujur dan sepengetahuan Anda.",
  ui_story_5045_50450101_24_dialog_content = "(Angel terlihat begitu serius, duduk di tengah bangku hakim. Sayap putihnya berpadu sempurna dengan latar belakang yang tampak suci itu.)",
  ui_story_5045_50450101_25_dialog_content = "(Sudah cukup buruk aku didorong ke kursi saksi, tapi tatapan yang dia berikan padaku... Dia benar-benar mengira aku tersangka!)",
  ui_story_5045_50450101_26_dialog_content = "(Aku harus mengatakan sesuatu padanya! Aku ingin berteriak dari lubuk hatiku—)",
  ui_story_5045_50450101_27_option_content = "Itu semua adalah pengaturan!",
  ui_story_5045_50450101_28_dialog_content = "Oh?",
  ui_story_5045_50450101_29_dialog_content = "Mencoba membuat alasan untuk kejahatanmu bahkan sebelum interogasi dimulai, mengerti?",
  ui_story_5045_50450101_30_option_content = "Keberatan!",
  ui_story_5045_50450101_31_dialog_content = "Ditolak!",
  ui_story_5045_50450101_32_dialog_content = "Keberatan Anda ditolak dengan alasan saya bahkan belum mulai menanyai Anda!",
  ui_story_5045_50450101_33_dialog_content = "Apa yang sedang terjadi di sini?",
  ui_story_5045_50450101_34_dialog_content = "Ya ampun... Rakyat jelata rendahan lainnya yang ingin menjadi hakim?",
  ui_story_5045_50450101_35_dialog_content = "Cukup menghina proses peradilan, bukan begitu?",
  ui_story_5045_50450101_36_dialog_content = "Tetap tenang, Matthieu.",
  ui_story_5045_50450101_37_dialog_content = "Kami tidak seharusnya membuat komentar apa pun sekarang. Jangan tidak menghormati Balai Kehakiman seperti itu.",
  ui_story_5045_50450101_38_dialog_content = "Zzz...",
  ui_story_5045_50450101_39_dialog_content = "Tidakkah menurutmu dia jauh lebih tidak sopan terhadap Aula sekarang?!",
  ui_story_5045_50450101_40_dialog_content = "Tina, bangun!",
  ui_story_5045_50450101_41_dialog_content = "Yaawn... Hah? Kenapa PlayerName mengambil sikap? Dia tersangka, bukan?",
  ui_story_5045_50450101_42_dialog_content = "Ah! Oh sial, sial!",
  ui_story_5045_50450101_43_dialog_content = "Jangan bilang aku melewatkan pernyataan pembukaan untuk persidangan?!",
  ui_story_5045_50450101_44_dialog_content = "Ssst!!!",
  ui_story_5045_50450101_45_dialog_content = "Er, ehem... Kami hanya mengkonfirmasi itu PlayerName hadir hari ini.",
  ui_story_5045_50450101_46_dialog_content = "Tersangka dapat kembali ke tempat duduk mereka sekarang.",
  ui_story_5045_50450101_47_dialog_content = "(Apakah ini berarti saya harus terus mengikuti ini?)",
  ui_story_5045_50450101_48_dialog_content = "Dan sekarang, kami meminta penggugat, Hakim Irridon, membuat pernyataan pembukaannya.",
  ui_story_5045_50450101_49_dialog_content = "Baiklah.",
  ui_story_5045_50450101_50_dialog_content = "Pada pukul dua siang ini, saya menerima pemberitahuan dari Tuan Kota untuk menghadiri pertemuan menit-menit terakhir.",
  ui_story_5045_50450101_51_dialog_content = "Setelah menerima pemberitahuan ini, saya mengunci pintu kantor saya dan pergi.",
  ui_story_5045_50450101_52_dialog_content = "Tetapi ketika saya kembali ke kantor saya pada pukul empat, saya melihat bahwa sejumlah besar Nightium telah hilang.",
  ui_story_5045_50450101_53_dialog_content = "Apakah Anda melihat sesuatu yang tidak biasa di TKP?",
  ui_story_5045_50450101_54_dialog_content = "Pintu dan jendela kantor saya tidak menunjukkan tanda-tanda masuk paksa, dan pintunya masih terkunci ketika saya kembali.",
  ui_story_5045_50450101_55_dialog_content = "Selain sidik jari saya sendiri, gagang pintu tidak memiliki jejak lain yang tersisa.",
  ui_story_5045_50450101_55X1_dialog_content = "(Saya tidak benar-benar mengerti apa yang terjadi di sini, tapi Irridon tampaknya berbicara tentang sesuatu yang penting.)",
  ui_story_5045_50450101_55X2_dialog_content = "(Sebaiknya saya menuliskan detail ini, untuk berjaga-jaga!)",
  ui_story_5045_50450101_56_dialog_content = "Ini tampaknya merupakan pencurian yang cukup misterius!",
  ui_story_5045_50450101_57_dialog_content = "Bisakah Anda memberi tahu pengadilan mengapa Anda mencurigainya PlayerName mencuri Nightium?",
  ui_story_5045_50450101_58_dialog_content = "Karena saya menemukan surat di kantor saya, sebuah undangan yang saya kirimkan secara pribadi PlayerName.",
  ui_story_5045_50450101_59_dialog_content = "Undangan itu seharusnya sudah masuk PlayerNamemilik...",
  ui_story_5045_50450101_60_dialog_content = "Jadi apa yang dilakukannya di dalam kantor saya yang terkunci?",
  ui_story_5045_50450101_61_dialog_content = "Apa?!",
  ui_story_5045_50450101_62_dialog_content = "Tidak hanya itu... Seseorang membuktikan melihat PlayerName di sekitar kantor saya saat itu.",
  ui_story_5045_50450101_63_dialog_content = "Itu karena—",
  ui_story_5045_50450101_64_dialog_content = "<color=#737378>Dor, dor, dor!</color>",
  ui_story_5045_50450101_65_dialog_content = "<size=45>Kesunyian! Pesan di pengadilan!</size>",
  ui_story_5045_50450101_66_dialog_content = "Hmm, sekarang apa yang datang lagi? Ah iya! Sekarang kita akan mendengar kesaksian dari saksi, Pak. Pittman!",
  ui_story_5045_50450101_67_dialog_content = "Pukul dua siang ini, saya pergi menemui Hakim Irridon untuk mengajukan sejumlah pertanyaan terkait pekerjaan...",
  ui_story_5045_50450101_68_dialog_content = "Tetapi dia segera memberi tahu saya bahwa dia harus pergi untuk pertemuan yang mendesak, dan meminta saya untuk kembali nanti.",
  ui_story_5045_50450101_69_dialog_content = "Sekitar pukul tiga, saya berjalan kembali ke kantornya untuk melihat apakah dia telah kembali.",
  ui_story_5045_50450101_70_dialog_content = "Tetapi ketika saya mendekati pintunya, saya melihat bayangan sekilas dari sosok yang meninggalkan tempat yang sama.",
  ui_story_5045_50450101_71_dialog_content = "Jadi saya berpikir sendiri, itu pasti PlayerName.",
  ui_story_5045_50450101_72_dialog_content = "Bagus sekali! Dan sekarang saatnya untuk menghakimi saksi... Apakah Anda siap, PlayerName?",
  ui_story_5045_50450101_73_dialog_content = "T-Tunggu, Yang Mulia! Beri aku kesempatan untuk menjelaskan!",
  ui_story_5045_50450101_74_dialog_content = "Ya ampun, tidak lagi. Aku lupa aku seharusnya mendengar bantahannya terlebih dahulu...",
  ui_story_5045_50450101_75_dialog_content = "A-Ahem, baiklah kalau begitu! Anda dapat menawarkan bantahan Anda sekarang.",
  ui_story_5045_50450101_76_dialog_content = "Tapi pertama-tama, tolong perkenalkan diri Anda ke pengadilan.",
  ui_story_5045_50450101_77_dialog_content = "Nama saya adalah PlayerName. Saya seorang Caelestite.",
  ui_story_5045_50450101_78_dialog_content = "Tolong perkenalkan kepada kami milik Anda <color=#1875ad>pekerjaan</color> demikian juga.",
  ui_story_5045_50450101_79_dialog_content = "aku, eh...",
  ui_story_5045_50450101_80_option_content = "Saya adalah maskot Astra yang paling dicintai.",
  ui_story_5045_50450101_81_option_content = "Aku Pemancing Gelombang Naga.",
  ui_story_5045_50450101_82_option_content = "Saya seorang pemanjat menara profesional.",
  ui_story_5045_50450101_83_dialog_content = "Saya pilot yang ditunjuk Soroz.",
  ui_story_5045_50450101_84_dialog_content = "Bisakah Anda jelaskan lebih lanjut?",
  ui_story_5045_50450101_85_dialog_content = "Dengan kata lain, pekerjaanku adalah—",
  ui_story_5045_50450101_86_option_content = "Untuk menggulingkan Lumopolis dan tiraninya!",
  ui_story_5045_50450101_87_dialog_content = "A-Apa?! Lumopolis berkembang pesat di bawah pemerintahan Penguasa Kota yang adil dan adil! Beraninya Anda mengungkapkan ambisi teror Anda kepada kami!!!",
  ui_story_5045_50450101_88_dialog_content = "Saya beri tahu Anda bahwa mereka yang mengancam kedamaian Lumopolis atau rakyatnya... akan menghabiskan sisa hidup mereka di penjara!",
  ui_story_5045_50450101_89_dialog_content = "(Aku hanya bercanda, tapi dia terlihat sangat serius untuk menghukumku...)",
  ui_story_5045_50450101_90_dialog_content = "O-Oh, ayolah! Kau tahu aku selalu mengatakan hal-hal gila seperti itu!",
  ui_story_5045_50450101_91_option_content = "Untuk menyebarkan pesan perdamaian dan cinta!",
  ui_story_5045_50450101_92_option_content = "Untuk menyelamatkan dunia!",
  ui_story_5045_50450101_93_dialog_content = "Dipahami. Biarkan catatan menunjukkan bahwa tersangka tidak hanya menganggur tetapi juga memiliki delusi remaja.",
  ui_story_5045_50450101_94_dialog_content = "Beritahu kami dengan jujur—di mana Anda antara jam dua dan jam empat sore ini?",
  ui_story_5045_50450101_95_dialog_content = "Aku sudah berada di Hall of Justice selama ini.",
  ui_story_5045_50450101_96_dialog_content = "Sebagai Caelestite, mengapa Anda datang ke Lumopolis Hall of Justice?",
  ui_story_5045_50450101_96X1_dialog_content = "(Eh, k-kenapa aku datang ke Hall of Justice lagi?)",
  ui_story_5045_50450101_96X2_dialog_content = "(Sebenarnya berdiri di sini sekarang, pikiranku benar-benar kosong!)",
  ui_story_5045_50450101_96X3_dialog_content = "(Untungnya, saya baru saja menulis beberapa catatan. Mungkin saya dapat mengingat sesuatu dari mereka...)",
  ui_story_5045_50450101_97_dialog_content = "Malam Putih di atas, berhentilah mencoba menggagalkan proses!",
  ui_story_5045_50450101_98_dialog_content = "M-Saya buruk ...",
  ui_story_5045_50450101_99_dialog_content = "Bagus, sekarang izinkan saya bertanya sekali lagi.",
  ui_story_5045_50450101_100_dialog_content = "Saya menerima sebuah <color=#1875ad>undangan</color> dari Irridon.",
  ui_story_5045_50450101_101_dialog_content = "Dia meminta saya untuk datang ke Hall of Justice dan mengunjunginya di kantornya.",
  ui_story_5045_50450101_102_dialog_content = "Dia berkata dia ingin menunjukkan kepada saya seperti apa percobaan yang tepat itu, dan bahwa dia memiliki pekerjaan untuk saya.",
  ui_story_5045_50450101_103_dialog_content = "Saya tiba di sini pada pukul dua, tetapi tidak ada orang yang menunjukkan jalan ke kantornya.",
  ui_story_5045_50450101_104_dialog_content = "Setelah berkeliling hingga sekitar pukul tiga, akhirnya saya menemukan kantornya. Hanya... dia tidak ada di sana saat itu.",
  ui_story_5045_50450101_105_dialog_content = "Saat itulah saya memutuskan untuk pergi.",
  ui_story_5045_50450101_106_dialog_content = "Setelah itu, saya menghabiskan sisa sore hari menikmati sinar matahari di tangga Hall of Justice. Begitulah, sampai seseorang membawa saya ke ruang sidang kecil ini.",
  ui_story_5045_50450101_107_dialog_content = "Oh? Jadi apakah ini berarti Anda mengaku membobol kantor Hakim Irridon?",
  ui_story_5045_50450101_108_dialog_content = "Aku tidak masuk ke kantornya! Pintunya tidak terkunci, jadi aku masuk!",
  ui_story_5045_50450101_109_dialog_content = "Mustahil. Hakim Irridon sendiri mengatakan bahwa dia hanya pergi setelah mengunci pintu kantornya.",
  ui_story_5045_50450101_110_dialog_content = "Bantahan Anda benar-benar mengecewakan, PlayerName.",
  ui_story_5045_50450101_111_dialog_content = "Kurangnya pekerjaan membuat Anda sangat membutuhkan uang cepat, jadi Anda memutuskan untuk memanfaatkan kepercayaan Hakim Irridon.",
  ui_story_5045_50450101_112_dialog_content = "Sayangnya, Anda lupa satu hal penting ...",
  ui_story_5045_50450101_113_dialog_content = "Ini adalah Balai Kehakiman Lumopolis, di mana tidak ada penjahat yang tidak dihukum!",
  ui_story_5045_50450101_114_dialog_content = "Sebagai hakim, dengan ini saya menyatakan—",
  ui_story_5045_50450101_115_dialog_content = "<size=45>Itu PlayerName adalah <color=#1875ad>bersalah</color>!</size>",
  ui_story_5045_50450201_1_dialog_content = "<size=45>Itu PlayerName adalah <color=#1875ad>bersalah</color>!</size>",
  ui_story_5045_50450201_2_dialog_content = "T-Tunggu, aku bersumpah aku tidak...",
  ui_story_5045_50450201_3_dialog_content = "Hah? PlayerName bersalah?",
  ui_story_5045_50450201_4_dialog_content = "Bangun tepat pada waktunya untuk bagian yang terbaik, begitu? Astaga, betapa nyamannya.",
  ui_story_5045_50450201_5_dialog_content = "Ini bukan tingkat kinerja Angel yang biasa. Dia pasti sangat gugup hari ini.",
  ui_story_5045_50450201_6_dialog_content = "Seperti yang saya katakan, rakyat jelata tidak punya urusan menjadi hakim di Lumopolis. Beban itu terlalu berat untuk mereka tanggung.",
  ui_story_5045_50450201_7_dialog_content = "Hakim Irridon, saya gagal saya <color=#1875ad>sidang pura-pura</color> sekali lagi, bukankah aku...",
  ui_story_5045_50450201_8_dialog_content = "Tunggu, ini adalah <color=#1875ad>sidang pura-pura</color> selama ini?!",
  ui_story_5045_50450201_9_dialog_content = "Anda hakim sekarang, Angel.",
  ui_story_5045_50450201_10_dialog_content = "Jangan lupa, Anda masih belum memanggil pengadilan untuk mengakhiri.",
  ui_story_5045_50450201_11_dialog_content = "Jangan terlalu gugup, Angel!",
  ui_story_5045_50450201_12_dialog_content = "Mengapa Anda tidak pergi ke ruang istirahat dan meluangkan waktu untuk menjernihkan pikiran?",
  ui_story_5045_50450201_13_dialog_content = "Saya tidak setuju. Anda harus mengambil beberapa menit untuk mengumpulkan pemikiran Anda dan melihat apakah ada kontradiksi dalam pernyataan yang baru saja diberikan.",
  ui_story_5045_50450201_14_option_content = "Tina benar.",
  ui_story_5045_50450201_15_dialog_content = "Benar-benar? Anda sebenarnya setuju dengan saya, PlayerName?",
  ui_story_5045_50450201_16_dialog_content = "Ya! Pergi istirahat, Angel!",
  ui_story_5045_50450201_17_dialog_content = "Aku juga bisa menggunakannya, karena kalian membuatku takut...",
  ui_story_5045_50450201_18_dialog_content = "Terima kasih atas saran baik Anda, semuanya.",
  ui_story_5045_50450201_19_option_content = "Leyn benar.",
  ui_story_5045_50450201_20_dialog_content = "Kamu juga berpikir begitu, ya? Terima kasih, PlayerName.",
  ui_story_5045_50450201_21_dialog_content = "Ya! Tetap tenang dan kumpulkan pikiran Anda, Angel!",
  ui_story_5045_50450201_22_dialog_content = "Dan meskipun ini hanya percobaan pura-pura, saya tetap ingin semua orang tahu bahwa saya BUKAN pencuri! Oke?",
  ui_story_5045_50450201_23_dialog_content = "Terima kasih atas saran baik Anda, semuanya.",
  ui_story_5045_50450201_24_option_content = "Mari kita lanjutkan.",
  ui_story_5045_50450201_25_dialog_content = "Tidakkah menurutmu kalian seharusnya memberitahuku tentang hari ini?",
  ui_story_5045_50450201_26_dialog_content = "Aku tidak tahu apa yang terjadi, dan kamu langsung menganggapku bersalah... Itu agak kacau, tahu?",
  ui_story_5045_50450201_27_dialog_content = "Mengapa kita tidak melupakannya saja kali ini, Angel? Saya berjanji akan melakukan tindakan yang jauh lebih baik lain kali!",
  ui_story_5045_50450201_28_dialog_content = "Tidak, itu tidak akan berhasil sama sekali!",
  ui_story_5045_50450201_29_dialog_content = "(Whoa. Saya rasa saya belum pernah melihat Angel jadi bekerja keras sebelumnya.)",
  ui_story_5045_50450201_30_dialog_content = "(Kurasa aku harus menghindarinya...)",
  ui_story_5045_50450201_31_dialog_content = "Ahem... Aku merasa jauh lebih tenang sekarang.",
  ui_story_5045_50450201_32_dialog_content = "Saya sangat khawatir akan lulus ujian tiruan sehingga saya mempermalukan diri sendiri di depan semua orang.",
  ui_story_5045_50450201_33_dialog_content = "Bagi seorang hakim di Balai Kehakiman, nilai bagus tidak akan pernah sepenting mengungkap kebenaran dalam sebuah kasus.",
  ui_story_5045_50450201_34_dialog_content = "Tetapi meskipun itu hanya percobaan pura-pura, kita berhutang pada diri kita sendiri untuk memercayai keputusan kita dan tidak pernah menyerah!",
  ui_story_5045_50450201_35_dialog_content = "Ya!",
  ui_story_5045_50450201_36_dialog_content = "<color=#737378>Bum!</color>",
  ui_story_5045_50450201_37_dialog_content = "Sekarang kita akan masuk ke <color=#1875ad>fase diskusi</color> persidangan!",
  ui_story_5045_50450201_38_dialog_content = "Diskusi terbuka bagi siapa saja yang ingin bertanya, berbagi pemikiran, atau memberikan alasan tentang kasus tersebut.",
  ui_story_5045_50450201_39_dialog_content = "Aku bukan pencuri!",
  ui_story_5045_50450201_40_dialog_content = "Tapi undangan ini membuktikan bahwa Anda berada di kantor saya di beberapa titik hari ini.",
  ui_story_5045_50450201_41_dialog_content = "Lebih penting lagi, Anda adalah orang yang mengakui hal ini.",
  ui_story_5045_50450201_42_dialog_content = "Memang benar saya pergi ke kantor Anda, tetapi saya tidak membawa apa pun ketika saya pergi! Belum lagi pintunya tidak terkunci ketika saya sampai di sana!",
  ui_story_5045_50450201_43_dialog_content = "Saya benar-benar yakin bahwa saya mengunci pintu sebelum saya pergi.",
  ui_story_5045_50450201_44_dialog_content = "Dugaan saya adalah Anda menggunakan kemampuan psikis Anda untuk membuka kunci pintu, lalu menguncinya sekali lagi sebelum Anda pergi.",
  ui_story_5045_50450201_45_dialog_content = "Itu bukan sesuatu yang bisa kulakukan dengan kekuatanku!",
  ui_story_5045_50450201_46_dialog_content = "Tak satu pun dari kami adalah Caelestites, jadi kami tidak dapat memastikan apakah Anda berbohong atau tidak.",
  ui_story_5045_50450201_47_dialog_content = "Anda mencoba untuk menjebak saya, bukan?!",
  ui_story_5045_50450201_48_dialog_content = "Keberatan! Yang mulia, PlayerName tidak diperbolehkan untuk melakukan serangan pribadi terhadap penggugat.",
  ui_story_5045_50450201_49_dialog_content = "Ini tidak adil... Kalian bekerja sama melawanku!",
  ui_story_5045_50450201_50_dialog_content = "PlayerName, Anda berhak menjelaskan atau mempertanyakan detail atau bukti apa pun yang terlibat dalam kasus ini.",
  ui_story_5045_50450201_51_dialog_content = "Tapi pilih kata-kata Anda dengan hati-hati... Kejujuran dan integritas adalah landasan Balai Kehakiman.",
  ui_story_5045_50450201_52_dialog_content = "...",
  ui_story_5045_50450201_53_dialog_content = "Apakah ada orang lain di pengadilan yang memiliki sesuatu untuk didiskusikan?",
  ui_story_5045_50450201_54_dialog_content = "Situasi saat ini sama sekali tidak menguntungkan Anda, PlayerName. Apakah Anda memiliki hal lain untuk dikatakan?",
  ui_story_5045_50450201_55_dialog_content = "(Ada yang tidak beres.)",
  ui_story_5045_50450201_56_dialog_content = "(Memang benar aku pergi ke kantornya, tapi selain surat undangan itu...)",
  ui_story_5045_50450201_57_dialog_content = "(Saya seharusnya meninggalkan yang lain <color=#1875ad>jejak</color> di belakang!)",
  ui_story_5045_50450201_58_dialog_content = "Dan apa sebenarnya masalah dengan ini?",
  ui_story_5045_50450201_59_dialog_content = "Hah? Saya kira itu adalah hal yang salah untuk disebutkan.",
  ui_story_5045_50450201_60_dialog_content = "(Ayo, pikirkan! Selain surat undangan itu...)",
  ui_story_5045_50450201_61_dialog_content = "Irridon mengatakan bahwa hanya sidik jarinya yang ditemukan di gagang pintu, tapi itu tidak benar.",
  ui_story_5045_50450201_62_dialog_content = "Karena saya pasti memutarnya untuk masuk ke kamar!",
  ui_story_5045_50450201_63_dialog_content = "Yang berarti sidik jariku juga harus ada di sana!",
  ui_story_5045_50450201_64_dialog_content = "Kau benar!",
  ui_story_5045_50450201_65_dialog_content = "Saya pikir pencuri yang sebenarnya pasti menghapus sidik jari mereka sendiri untuk menutupi jejak mereka.",
  ui_story_5045_50450201_66_dialog_content = "Tetapi mereka tidak menyadari bahwa mereka juga menghapus sidik jari saya!",
  ui_story_5045_50450201_67_dialog_content = "Masuk akal...",
  ui_story_5045_50450201_68_dialog_content = "Bagaimana kami bisa yakin bahwa bukan Anda yang menyeka kenop pintu sampai bersih?",
  ui_story_5045_50450201_69_dialog_content = "(Huh... Sepertinya satu-satunya cara untuk membersihkan namaku adalah menemukan pencuri yang sebenarnya.)",
  ui_story_5045_50450201_70_dialog_content = "(Tunggu!)",
  ui_story_5045_50450201_71_dialog_content = "(Aku bukan pencurinya, itu sudah pasti... Tapi <color=#1875ad>kesaksian orang itu</color> mungkin memberi kita petunjuk!)",
  ui_story_5045_50450201_72_dialog_content = "Dan apa sebenarnya masalah dengan ini?",
  ui_story_5045_50450201_73_dialog_content = "M-maaf, tadi aku salah bicara...",
  ui_story_5045_50450201_74_dialog_content = "(Tenang saja dan pikirkan baik-baik...)",
  ui_story_5045_50450201_75_dialog_content = "Kapan tepatnya Anda melihat saya \"menyelinap\", Pittman?",
  ui_story_5045_50450201_76_dialog_content = "Sekitar pukul tiga.",
  ui_story_5045_50450201_77_dialog_content = "Bisakah Anda lebih spesifik tentang waktu?",
  ui_story_5045_50450201_78_dialog_content = "Saya pikir... Mungkin sudah lewat sepuluh menit atau lebih.",
  ui_story_5045_50450201_79_dialog_content = "Aneh, mengingat saya meninggalkan kantor sesaat sebelum jam menunjukkan pukul tiga—jadi bagaimana tepatnya Anda melihat saya di sana?",
  ui_story_5045_50450201_80_dialog_content = "Saya harus menyebutkan bahwa jam berdentang tiga tepat setelah saya keluar dari Hall of Justice.",
  ui_story_5045_50450201_81_dialog_content = "Para penjaga yang ditempatkan di luar dapat membuktikan hal ini.",
  ui_story_5045_50450201_82_dialog_content = "I-Ini...",
  ui_story_5045_50450201_83_dialog_content = "Saya tidak yakin, tapi mungkin saja sosok yang saya lihat adalah pencuri yang sebenarnya.",
  ui_story_5045_50450201_84_dialog_content = "Yang berarti itu orang lain dan bukan aku! Benar, Pittman?",
  ui_story_5045_50450201_85_dialog_content = "Sepertinya memang begitu, ya.",
  ui_story_5045_50450201_86_dialog_content = "Jadi Anda lihat, Yang Mulia, Pittman tidak memiliki cara untuk memastikan bahwa sosok yang dia lihat menyelinap sebenarnya adalah aku.",
  ui_story_5045_50450201_87_dialog_content = "Karena itu, tuduhannya harus diabaikan!",
  ui_story_5045_50450201_88_dialog_content = "Memang terlihat seperti ini...",
  ui_story_5045_50450201_89_dialog_content = "Tetapi itu tidak berarti Anda telah membersihkan diri dari kecurigaan.",
  ui_story_5045_50450201_90_dialog_content = "Mengapa kita tidak mencoba melihat hal-hal sedikit berbeda? Anggap saja saya bukan pencurinya; dengan melakukan itu, Anda dapat dengan jelas melihat banyak masalah pada kasing ini.",
  ui_story_5045_50450201_91_dialog_content = "Pertama-tama, bagaimana pencuri bisa membuka pintu? Mungkinkah mereka memiliki kunci tambahan?",
  ui_story_5045_50450201_92_dialog_content = "...",
  ui_story_5045_50450201_93_dialog_content = "Kedua, mengapa si pencuri bersusah payah menghapus sidik jari mereka?",
  ui_story_5045_50450201_94_dialog_content = "Masuk akal jika itu adalah seseorang yang terkait dengan Hall of Justice, karena yang diperlukan untuk mengungkap mereka hanyalah penyelidikan cepat.",
  ui_story_5045_50450201_95_dialog_content = "...",
  ui_story_5045_50450201_96_dialog_content = "Beritahu kami, Pittman, apa mungkin kamu pencurinya?",
  ui_story_5045_50450201_97_dialog_content = "B-Bagaimana itu bisa terjadi?",
  ui_story_5045_50450201_98_dialog_content = "Bagaimanapun, Anda adalah bawahan Irridon yang paling tepercaya. Jika ada yang tahu tentang dia meninggalkan Nightium di kantornya, itu kamu.",
  ui_story_5045_50450201_99_dialog_content = "Bukan hanya itu, tetapi Anda juga melihat Irridon meninggalkan kantornya, yang akan menjadi waktu yang tepat untuk mengeluarkan kunci cadangan dan masuk ke dalam.",
  ui_story_5045_50450201_100_dialog_content = "Tapi itu hanya setelah Anda pergi dengan Nightium yang Anda sadari. Sidik jari Anda masih menempel di gagang pintu!",
  ui_story_5045_50450201_101_dialog_content = "Saat itulah Anda bergegas kembali untuk mengelapnya dan mengunci pintunya lagi, membuatnya seolah-olah uangnya hilang begitu saja.",
  ui_story_5045_50450201_102_dialog_content = "Apa yang tidak Anda ketahui, adalah bahwa Anda juga menyeret saya ke dalam kejahatan Anda!",
  ui_story_5045_50450201_103_dialog_content = "Jadi ketika Anda melihat itu Irridon mencurigai saya mencuri Nightiumnya, Anda mengambil inisiatif dan mencoba membuat saya mengambil risiko untuk Anda!",
  ui_story_5045_50450201_104_dialog_content = "Ini semua hanya spekulasi liar, tidak lebih! Apa kau punya bukti?!",
  ui_story_5045_50450201_105_dialog_content = "Memang benar bahwa saya mengasumsikan banyak hal di sini. Tapi izinkan saya menanyakan sesuatu! Ketika saya menyentuh semua poin itu ...",
  ui_story_5045_50450201_106_dialog_content = "Mengapa Anda tiba-tiba mulai berkeringat begitu banyak? Juga, mengapa Anda terus meraih milik Anda <color=#1875ad>saku</color> setiap beberapa detik?",
  ui_story_5045_50450201_107_dialog_content = "Mungkinkah Anda benar-benar memiliki kunci cadangan ke kantor Irridon di sana?",
  ui_story_5045_50450201_108_dialog_content = "Tn. Pittman, tolong tunjukkan kepada pengadilan apa yang Anda miliki di saku Anda.",
  ui_story_5045_50450201_109_dialog_content = "...",
  ui_story_5045_50450201_110_dialog_content = "Saya kira saya tidak punya pilihan.",
  ui_story_5045_50450201_111_dialog_content = "Kunci ini adalah salinan persis dari kunci kantor saya!",
  ui_story_5045_50450201_112_dialog_content = "Tn. Pittman, Anda dituduh mencuri Nightium Hakim Irridon. Apakah Anda memiliki sesuatu untuk dikatakan untuk diri sendiri?",
  ui_story_5045_50450201_113_dialog_content = "Aku... aku tidak. Saya tidak punya apa-apa untuk dikatakan.",
  ui_story_5045_50450201_114_dialog_content = "Jika itu masalahnya, maka dengan ini saya menyatakan—",
  ui_story_5045_50450201_115_dialog_content = "<size=45>Pittman adalah <color=#1875ad>bersalah</color> kejahatan ini!</size>",
  ui_story_5045_50450201_116_dialog_content = "Wah... Senangnya sudah berakhir.",
  ui_story_5045_50450201_117_dialog_content = "Aku hanya tahu aku akan gagal dalam percobaan pura-puraku...",
  ui_story_5045_50450201_118_dialog_content = "Tidak perlu merasa putus asa, Angel. Akan ada lebih banyak peluang di masa depan.",
  ui_story_5045_50450201_119_dialog_content = "Senior Anda di sini tidak berbeda. Mereka hanya menjadi hakim setelah menjalani uji coba dan penilaian tiruan yang tak terhitung jumlahnya.",
  ui_story_5045_50450201_120_dialog_content = "Itu benar. Nyatanya, saya lebih banyak gagal dalam percobaan pura-pura daripada siapa pun dalam sejarah Balai Kehakiman!",
  ui_story_5045_50450201_121_dialog_content = "Jangan biarkan kegembiraan Leyn membodohi Anda, Angel. Itu sebenarnya bukan sesuatu yang bisa dibanggakan.",
  ui_story_5045_50450201_122_dialog_content = "Maafkan saya, Hakim Irridon, tapi saya mohon berbeda. Jika Anda ingat dengan benar, saya lulus penilaian saya pada percobaan pertama saya!",
  ui_story_5045_50450201_123_dialog_content = "Ya, sepertinya saya ingat sekarang. Sementara kita berada di subjek, Matthieu...",
  ui_story_5045_50450201_124_dialog_content = "Sejak Loewe cuti baru-baru ini, Angel akan bekerja di bawah Anda sebagai asisten Anda selama beberapa hari ke depan. Saya pikir dia bisa belajar banyak dari Anda.",
  ui_story_5045_50450201_125_dialog_content = "Dengan kecerdasan dan bakatku, sepertinya aku tidak membutuhkan asisten, Hakim Irridon!",
  ui_story_5045_50450201_126_dialog_content = "Tidakkah menurut Anda hakim terbaik kita memiliki tanggung jawab untuk melatih generasi penerus kita agar sama-sama menjadi teladan?",
  ui_story_5045_50450201_127_dialog_content = "Aku mengerti, sekarang...",
  ui_story_5045_50450201_128_dialog_content = "Anda sangat benar, Hakim Irridon!",
  ui_story_5045_50450201_129_dialog_content = "Sebagai salah satu juri terhebat yang pernah menghiasi Hall of Justice, saya bersumpah untuk memenuhi harapan Anda dan meneruskan semua pengetahuan saya kepada murid baru saya!",
  ui_story_5045_50450201_130_dialog_content = "Cobalah untuk tidak berharap terlalu banyak darinya ... Lagi pula, tidak banyak yang bisa dibandingkan dengan kehebatan saya!",
  ui_story_5045_50450201_131_dialog_content = "<size=32>Tapi saya ingin menjadi asisten Pak Pittman!</size>",
  ui_story_5045_50450301_1_dialog_content = "<color=#737378>Waktu: 20:00</color>",
  ui_story_5045_50450301_2_dialog_content = "<color=#737378>Lokasi: Balai Kehakiman Lumo</color>",
  ui_story_5045_50450301_3_dialog_content = "Saya benar-benar tidak tahu bahwa Anda, dari semua orang, akan menjadi orang yang akhirnya memecahkan kasus ini.",
  ui_story_5045_50450301_4_dialog_content = "Itu hanya keberuntungan bodoh, sungguh ...",
  ui_story_5045_50450301_5_dialog_content = "(Sejujurnya, penampilan Pittman yang meyakinkan itulah yang benar-benar menyelamatkan saya.)",
  ui_story_5045_50450301_6_dialog_content = "Hai, Irridon? Sesuatu memberi tahu saya bahwa persidangan pura-pura hari ini didasarkan pada kasus pencurian yang sebenarnya.",
  ui_story_5045_50450301_7_dialog_content = "Memang benar. Namun asumsi cerdik lainnya, PlayerName.",
  ui_story_5045_50450301_8_dialog_content = "Saya juga tahu bahwa Anda hanya mengirimi saya surat itu untuk membuat saya terlibat dalam semua ini!",
  ui_story_5045_50450301_9_dialog_content = "Anda tahu, jika Anda baru saja memberi tahu saya bahwa itu untuk uji coba tiruan, saya bisa lebih membantu.",
  ui_story_5045_50450301_10_dialog_content = "Dalam percobaan nyata, situasi tak terduga muncul sepanjang waktu.",
  ui_story_5045_50450301_11_dialog_content = "Kami hanya ingin memperkenalkan beberapa variabel independen ke uji coba tiruan.",
  ui_story_5045_50450301_12_dialog_content = "Namun, itu hanya berkat kamu Angel dapat membawa persidangan ke kesimpulan yang memuaskan.",
  ui_story_5045_50450301_13_dialog_content = "Saya melihat ... Tebak itu membuat saya menjadi variabel yang cukup andal, ya?",
  ui_story_5045_50450301_14_dialog_content = "Memang. Kekuatan pengamatan Anda sangat tajam.",
  ui_story_5045_50450301_15_dialog_content = "Faktanya, dan saya mengatakan ini tanpa berlebihan, tetapi kinerja Anda hari ini berada pada level yang sama dengan banyak juri kami yang menjalani penilaian mereka.",
  ui_story_5045_50450301_16_dialog_content = "Kalau saja kami memiliki lebih banyak orang seperti Anda di sini di Hall of Justice.",
  ui_story_5045_50450301_17_dialog_content = "Tapi cukup tentang itu.",
  ui_story_5045_50450301_18_dialog_content = "Kami ingin memberikan kompensasi atas bantuan Anda hari ini. Anggap itu sebagai tanda terima kasih dari kita semua di Hall of Justice.",
  ui_story_5045_50450301_19_dialog_content = "Kompensasi saya?",
  ui_story_5045_50450301_20_dialog_content = "Ini dia: barang curian dari persidangan tiruan hari ini.",
  ui_story_5045_50450301_21_dialog_content = "Wah, saya pikir Nightium ini hanya digunakan sebagai penyangga untuk uji coba.",
  ui_story_5045_50450301_22_dialog_content = "Apakah Anda benar-benar memberikan ini kepada saya?",
  ui_story_5045_50450301_23_dialog_content = "Mengapa? Apakah terlalu sedikit?",
  ui_story_5045_50450301_24_dialog_content = "NN-Tidak sama sekali! Ini lebih dari cukup!",
  ui_story_5045_50450301_25_dialog_content = "Nyatanya, jangan ragu untuk menelepon saya setiap kali Anda memiliki lebih banyak pekerjaan seperti ini!",
  ui_story_5045_50450301_26_dialog_content = "Benar-benar? Aku tidak tahu kau begitu tertarik untuk bekerja di Hall of Justice, PlayerName...",
  ui_story_5045_50450301_27_dialog_content = "Maksudku, selain kejutan awal...",
  ui_story_5045_50450301_28_dialog_content = "Saya benar-benar menemukan pekerjaan itu cukup menarik!",
  ui_story_5045_50450301_29_dialog_content = "Mendengar Anda mengatakan itu membuat saya sangat senang.",
  ui_story_5045_50450301_30_dialog_content = "Katakan padaku, apakah Anda ingin menghabiskan waktu di sini dan bekerja bersama kami?",
  ui_story_5045_50450301_31_dialog_content = "Anda tahu, baru-baru ini saya mendirikan departemen baru di dalam Hall of Justice, dan kami dapat menggunakan seseorang dengan keterampilan interpersonal seperti Anda.",
  ui_story_5045_50450301_32_dialog_content = "Departemen baru?",
  ui_story_5045_50450301_33_dialog_content = "Sepertinya Anda tertarik. Dalam hal ini, harap terima ini. Anda akan membutuhkannya segera.",
  ui_story_5045_50450301_34_dialog_content = "Apakah ini... a<color=#1875ad> Buku Catatan Hakim</color>?",
  ui_story_5045_50450301_35_dialog_content = "Mulai hari ini, Anda adalah a <color=#1875ad>hakim percobaan</color> dari Balai Kehakiman.",
  ui_story_5045_50450301_36_dialog_content = "<color=#737378>Waktu: 08:00</color>",
  ui_story_5045_50450301_37_dialog_content = "<color=#737378>Lokasi: Kantor di Lumo Hall of Justice</color>",
  ui_story_5045_50450301_38_dialog_content = "Apakah ini tempat di mana Irridon menyuruhku melapor?",
  ui_story_5045_50450301_39_dialog_content = "Selamat pagi semuanya! Bagaimana saya bisa membantu-",
  ui_story_5045_50450301_40_dialog_content = "Kasus macam apa ini?!",
  ui_story_5045_50450301_41_dialog_content = "Penggugat benar, begitu juga dengan tergugat...",
  ui_story_5045_50450301_42_dialog_content = "Saya tidak melihat hukum atau preseden hukum yang berlaku untuk kasus ini. Siapa yang harus saya percayai di sini ?!",
  ui_story_5045_50450301_43_dialog_content = "Zzz...",
  ui_story_5045_50450301_44_dialog_content = "Perhatikan baik-baik, Angel.",
  ui_story_5045_50450301_45_dialog_content = "Inilah mengapa Anda belajar di bawah saya, dan bukan salah satu dari dua hakim yang tidak berguna itu.",
  ui_story_5045_50450301_46_dialog_content = "Tapi pak, sejauh yang saya tahu, nilai Anda tidak jauh lebih baik dari nilai mereka...",
  ui_story_5045_50450301_47_dialog_content = "<size=32>Ini akan menjelaskan mengapa Anda ditugaskan ke departemen kecil seperti itu bersama mereka ...</size>",
  ui_story_5045_50450301_48_dialog_content = "Ya ampun. Anda bahkan lebih buruk dari Loewe, bukan?!",
  ui_story_5045_50450301_49_dialog_content = "Izinkan saya mengulangi diri saya sendiri: Saya memilih untuk pindah ke departemen ini karena minat dan rasa tanggung jawab saya yang luar biasa!",
  ui_story_5045_50450301_50_dialog_content = "Sekarang kecuali jika Anda ingin terus gagal dalam penilaian Anda, saya sarankan Anda mengumpulkan barang-barang Anda dan segera datang.",
  ui_story_5045_50450301_51_dialog_content = "Siap, Pak...",
  ui_story_5045_50450301_52_dialog_content = "Hmm? Mengapa jika tidak PlayerName! Apa yang membawa Anda ke ambang pintu <color=#1875ad>Divisi Percintaan Hall of Justice</color> Hari ini?",
  ui_story_5045_50450301_53_dialog_content = "Wow, mereka bahkan memberi kalian kantor yang bagus untuk Divisi Percintaan...",
  ui_story_5045_50450301_54_dialog_content = "Bagus, katamu? Hah!",
  ui_story_5045_50450301_55_dialog_content = "Tunggu saja sampai aku menjadi Hakim Kepala Divisi Percintaan, maka kau akan melihat sebuah kantor yang benar-benar cocok untuk bangsawan sepertiku!",
  ui_story_5045_50450301_56_dialog_content = "Ketua Juri Divisi Percintaan?",
  ui_story_5045_50450301_57_dialog_content = "Ya, dan Anda sebaiknya menyingkir dari saya sekarang!",
  ui_story_5045_50450301_58_dialog_content = "...",
  ui_story_5045_50450301_59_dialog_content = "Sigh... Sejak Divisi Percintaan didirikan, posisi Ketua Juri terus bergilir di antara orang yang berbeda. Sementara itu, simpanan kasus kami semakin besar dan semakin besar.",
  ui_story_5045_50450301_60_dialog_content = "Seperti berdiri, tidak ada yang bersedia untuk menjabat sebagai Ketua Juri Divisi Percintaan.",
  ui_story_5045_50450301_61_dialog_content = "... Dengan pengecualian senior saya di sini, tentu saja. Mereka melakukan segala daya mereka untuk dipromosikan menjadi Hakim Ketua.",
  ui_story_5045_50450301_62_dialog_content = "<size=45>Jangan biarkan aku menunggu, Angel!!</size>",
  ui_story_5045_50450301_63_dialog_content = "Sigh ... Nah, semoga sukses, PlayerName!",
  ui_story_5045_50450301_64_dialog_content = "Saya pikir departemen baru Irridon disebutkan sebelumnya secara khusus untuk uji coba tiruan.",
  ui_story_5045_50450301_65_dialog_content = "Apa sih Divisi Percintaan...?",
  ui_story_5045_50450301_66_dialog_content = "PlayerName?",
  ui_story_5045_50450301_67_dialog_content = "Jadi kamu anggota terbaru dari Divisi Percintaan, ya?",
  ui_story_5045_50450301_68_option_content = "Saya pikir telah terjadi kesalahan.",
  ui_story_5045_50450301_69_dialog_content = "Hakim Irridon meminta Anda untuk membantu kami, kan?",
  ui_story_5045_50450301_70_dialog_content = "Benar.",
  ui_story_5045_50450301_71_dialog_content = "Lalu mengapa bisa terjadi kesalahan? Ini Hakim Irridon kita bicarakan, setelah semua.",
  ui_story_5045_50450301_72_dialog_content = "Jadi, Anda adalah anggota terbaru dari Divisi Percintaan!",
  ui_story_5045_50450301_73_option_content = "Saya harap saya tidak akan memperburuk keadaan.",
  ui_story_5045_50450301_74_dialog_content = "Kamu terlalu rendah hati.",
  ui_story_5045_50450301_75_dialog_content = "Hakim Irridon secara pribadi memilih Anda sebagai anggota terbaru kami. Saya yakin kami akan dapat belajar banyak dari Anda!",
  ui_story_5045_50450301_76_option_content = "Nah, itu hal yang baik Anda berada di sini.",
  ui_story_5045_50450301_77_dialog_content = "Memiliki seseorang yang dapat diandalkan seperti Anda dalam tim benar-benar menenangkan pikiran saya.",
  ui_story_5045_50450301_78_dialog_content = "Saya menantikan untuk belajar dari Anda!",
  ui_story_5045_50450301_79_dialog_content = "J-Jangan berharap terlalu banyak! Aku sudah lama tidak bekerja di Divisi Percintaan. Saya juga masih cukup baru dalam hal ini.",
  ui_story_5045_50450301_80_dialog_content = "Zzz...",
  ui_story_5045_50450301_81_dialog_content = "Siapa disini?",
  ui_story_5045_50450301_82_dialog_content = "Hei, ini tersangka utama kita dari sidang pura-pura kemarin! Senang bertemu denganmu lagi, PlayerName!",
  ui_story_5045_50450301_83_dialog_content = "Meskipun jika Anda di sini, itu berarti Anda mengalami masalah hubungan yang serius?",
  ui_story_5045_50450301_84_dialog_content = "Kirimkan saja keluhan resmi dengan semua detail sengketa Anda, dan kami akan segera menindaklanjutinya! Menguap-",
  ui_story_5045_50450301_85_option_content = "Saya tidak punya masalah seperti itu!",
  ui_story_5045_50450301_86_dialog_content = "Oh? Anda terdengar cukup percaya diri.",
  ui_story_5045_50450301_87_dialog_content = "Apa karena diam-diam kamu jadi artis pick-up? Atau mungkin Anda salah satu kutu buku yang berhati besi?",
  ui_story_5045_50450301_88_dialog_content = "T-Tidak satu pun di atas! Aku di sini untuk membantu kalian!",
  ui_story_5045_50450301_89_dialog_content = "Ah, jadi kamu orang baru itu! Selamat datang, selamat datang!",
  ui_story_5045_50450301_90_option_content = "Maaf membangunkanmu.",
  ui_story_5045_50450301_91_dialog_content = "Wow. Ini adalah pertama kalinya seseorang benar-benar meminta maaf karena membangunkanku! Saya sangat tersentuh...",
  ui_story_5045_50450301_92_dialog_content = "Hanya bercanda, saya tidak keberatan sama sekali! Selain itu, saya harus bangun sekarang, karena kami memiliki anggota baru yang bergabung dengan departemen kami hari ini.",
  ui_story_5045_50450301_93_dialog_content = "Anggota baru itu... Aku cukup yakin itu aku.",
  ui_story_5045_50450301_94_dialog_content = "Ah, jadi kamu orang baru itu! Selamat datang, selamat datang!",
  ui_story_5045_50450301_95_option_content = "Saya di sini untuk membantu.",
  ui_story_5045_50450301_96_dialog_content = "Meskipun saya masih tidak tahu bagaimana saya akan melakukan itu ...",
  ui_story_5045_50450301_97_dialog_content = "Wow. Jadi, Anda adalah tambahan baru yang menjanjikan di tim kami! Anda tidak tahu betapa saya sangat menantikan ini!",
  ui_story_5045_50450301_98_dialog_content = "Bahkan, saya bahkan bermimpi tadi malam bahwa Anda datang ke Divisi Percintaan, PlayerName! Saya tidak pernah berpikir bahwa impian saya akan menjadi kenyataan!",
  ui_story_5045_50450301_99_dialog_content = "Saya selalu memberi tahu orang-orang bahwa tidak ada salahnya tidur dan bermimpi sedikit lebih banyak dari biasanya, dan inilah alasannya!",
  ui_story_5045_50450301_100_dialog_content = "Dan dengan bantuanmu, PlayerName... Saya bahkan mungkin dipromosikan menjadi Hakim Ketua!",
  ui_story_5045_50450301_101_dialog_content = "Bicara apa kamu, Tina?",
  ui_story_5045_50450301_102_dialog_content = "Hah? Anda berarti Anda belum menyadarinya, Leyn?",
  ui_story_5045_50450301_103_dialog_content = "Tidak ada yang mau menjabat sebagai Ketua Juri di departemen yang canggung dan rumit seperti kita sekarang ...",
  ui_story_5045_50450301_104_dialog_content = "Itu sebabnya Matthieu sangat terburu-buru untuk memulai kasus ini sementara posisinya masih kosong.",
  ui_story_5045_50450301_105_dialog_content = "Dia berpikir bahwa dengan melakukan itu, Hakim Irridon mungkin mempertimbangkan untuk mengangkatnya sebagai kepala departemen kami!",
  ui_story_5045_50450301_106_dialog_content = "Matthieu? Sebagai Ketua Juri Divisi Percintaan?!",
  ui_story_5045_50450301_107_dialog_content = "Itu benar. Anda bisa membayangkan seperti apa hidup kita jika saya berhasil, bukan? Itu sebabnya kita akan lebih baik dengan saya yang bertanggung jawab!",
  ui_story_5045_50450301_108_dialog_content = "Saya tidak keberatan sama sekali jika Anda terpilih sebagai Hakim Ketua, Leyn.",
  ui_story_5045_50450301_109_dialog_content = "Saya hanya khawatir dengan Anda yang bertanggung jawab, departemen lain mungkin akan lebih meremehkan Divisi Percintaan.",
  ui_story_5045_50450301_110_dialog_content = "Mereka bisa meremehkanku semau mereka, tapi tidak di Divisi Percintaan!",
  ui_story_5045_50450301_111_dialog_content = "Jika saya diangkat sebagai Hakim Ketua departemen kami, saya bersumpah akan melakukan segala daya saya untuk mendapatkan rasa hormat yang pantas kami terima!",
  ui_story_5045_50450301_112_dialog_content = "Hmm... Sepertinya kamu juga memperhatikan posisinya, Leyn.",
  ui_story_5045_50450301_113_dialog_content = "Bagus! Sedikit kompetisi persahabatan akan memotivasi kita untuk bekerja lebih keras lagi!",
  ui_story_5045_50450301_114_dialog_content = "Aku akan mengandalkanmu, PlayerName!",
  ui_story_5045_50450301_115_dialog_content = "Hei, apa artinya itu? PlayerName ada di sini untuk membantu seluruh departemen kami! Anda tidak bisa hanya memiliki dia untuk diri sendiri!",
  ui_story_5045_50450301_116_dialog_content = "Oh? Tapi saya pikir Anda tidak suka bekerja dengan orang lain, Leyn?",
  ui_story_5045_50450301_117_dialog_content = "Atau mungkinkah Anda merasa sedikit iri?",
  ui_story_5045_50450301_118_dialog_content = "Aku bertanya-tanya, apakah kamu cemburu padaku karena aku punya PlayerName di sisi saya, atau apakah Anda cemburu PlayerName karena dia akan bekerja dengan saya?",
  ui_story_5045_50450301_119_dialog_content = "Aku hanya khawatir bahwa Anda akan menempatkan terlalu banyak stres PlayerName, itu saja.",
  ui_story_5045_50450301_120_dialog_content = "Kami memiliki banyak tugas, dan karena Anda hanya dapat bekerja untuk waktu yang singkat... Tunggu, Anda tidak berencana untuk menambah beban kerja Anda PlayerName, apakah kamu?!",
  ui_story_5045_50450301_121_dialog_content = "Ya ampun, aku tidak tahu kamu bisa begitu simpatik terhadap orang lain.",
  ui_story_5045_50450301_122_dialog_content = "Bagaimanapun, Anda harus menemukan solusi yang lebih berkelanjutan untuk masalah Anda.",
  ui_story_5045_50450301_123_dialog_content = "Saya punya ide!",
  ui_story_5045_50450301_124_dialog_content = "Mengapa kita tidak membiarkan PlayerName memutuskan dengan siapa dia ingin bekerja?",
  ui_story_5045_50450301_125_dialog_content = "Jadi begitu. Kedengarannya cukup adil bagi saya.",
  ui_story_5045_50450301_126_dialog_content = "Bagaimana menurutmu, PlayerName?",
  ui_story_5045_50450301_127_dialog_content = "Aku rasa aku tidak bisa membuat pilihan seperti itu sekarang.",
  ui_story_5045_50450301_128_dialog_content = "Maka jangan terlalu memikirkannya! Anda akan jauh lebih baik sebagai asisten saya, Anda tahu? Saya bahkan dapat membayar Anda ekstra, jika diperlukan!",
  ui_story_5045_50450301_129_dialog_content = "I-Itu bukan...",
  ui_story_5045_50450301_130_dialog_content = "Saya mungkin tidak memiliki dana untuk membeli layanan Anda seperti beberapa orang, tetapi saya jamin tenaga kerja Anda tidak akan dieksploitasi jika Anda memilih bekerja untuk saya.",
  ui_story_5045_50450301_131_dialog_content = "Saya akan mengambil bagian terbesar dari pekerjaan itu; yang perlu Anda lakukan hanyalah menawarkan saya beberapa perspektif baru sesekali dan ingatkan saya untuk bersikap adil setiap saat!",
  ui_story_5045_50450301_132_dialog_content = "(Keduanya tampak sangat membutuhkan bantuanku...)",
  ui_story_5045_50450301_133_dialog_content = "(Apa yang harus saya lakukan?!)",
  ui_story_5045_50450301_134_option_content = "Memilih Leyn",
  ui_story_5045_50450301_135_dialog_content = "Sejujurnya, saya tidak tahu bagaimana membantu kalian di Hall of Justice, dalam hal ini.",
  ui_story_5045_50450301_136_dialog_content = "Tapi jika apa Leyn mengatakan benar, saya pikir saya bisa menangani pekerjaan semacam itu.",
  ui_story_5045_50450301_137_dialog_content = "Saya yakin Anda akan melakukannya dengan baik!",
  ui_story_5045_50450301_138_option_content = "Memilih Tina",
  ui_story_5045_50450301_139_dialog_content = "Nah, sejak Tina benar-benar membutuhkan bantuan sekarang, saya kira saya bisa mencobanya.",
  ui_story_5045_50450301_140_dialog_content = "Peringatan yang adil! Saya hampir tidak memiliki pengetahuan tentang semua hal ini!",
  ui_story_5045_50450301_141_dialog_content = "Jangan khawatir. Aku pasti akan mengajarimu semua yang aku tahu... Menguap—",
  ui_story_5045_50450301_142_dialog_content = "Tapi pertama-tama, tidur siang sebentar.",
  ui_story_5045_50450301_143_option_content = "Pilih keduanya",
  ui_story_5045_50450301_144_dialog_content = "Kalian bilang aku anggota terbaru dari Divisi Percintaan, kan? Jadi apa yang menghentikan saya untuk bersaing dengan kalian untuk posisi Ketua Juri?",
  ui_story_5045_50450301_145_dialog_content = "Ketika Anda mengatakannya seperti itu, saya rasa Anda juga bebas melakukannya! Tapi Anda harus menjadi hakim yang sebenarnya terlebih dahulu.",
  ui_story_5045_50450301_146_dialog_content = "Kamu tahu, Tina, jika PlayerName cukup percaya diri untuk mengatakan sesuatu seperti ini, saya pikir kita harus memberikan dukungan penuh kita.",
  ui_story_5045_50450301_147_dialog_content = "Siapa tahu? Dia bahkan mungkin terbang melalui pelatihan dan menjadi hakim dalam waktu singkat, sama seperti Matthieu!",
  ui_story_5045_50450301_148_dialog_content = "Kedengarannya bagus untukku ... Menguap ...",
  ui_story_5045_50450401_1_dialog_content = "<color=#737378>Waktu: 18:00</color>",
  ui_story_5045_50450401_2_dialog_content = "<color=#737378>Lokasi: Lumo Hall of Justice, Kantor Divisi Percintaan</color>",
  ui_story_5045_50450401_3_dialog_content = "Jadi ada lagi yang bisa saya bantu, Leyn?",
  ui_story_5045_50450401_4_dialog_content = "Oh, kumpulkan saja sisa pernyataan itu dan itu sudah cukup.",
  ui_story_5045_50450401_5_dialog_content = "Aku bisa mengurus sisanya.",
  ui_story_5045_50450401_6_dialog_content = "Meskipun sekarang, Anda harus bersiap-siap untuk pulang hari ini.",
  ui_story_5045_50450401_7_dialog_content = "Bagaimana denganmu?",
  ui_story_5045_50450401_8_dialog_content = "Kami menerima lebih dari seratus keluhan hari ini yang masih perlu ditinjau.",
  ui_story_5045_50450401_9_dialog_content = "Setelah selesai, saya harus menerima keluhan tentang materi yang hilang dan mengirimkannya kembali untuk dikirim ulang.",
  ui_story_5045_50450401_10_dialog_content = "Tapi ini sudah sangat larut... Kau benar-benar tinggal untuk melakukan semua itu?",
  ui_story_5045_50450401_11_dialog_content = "Sejujurnya... Kasus-kasus yang ditangani oleh Divisi Percintaan semuanya sangat sulit untuk saya pahami.",
  ui_story_5045_50450401_12_dialog_content = "Saya perlu meluangkan waktu untuk mempelajarinya dan belajar bagaimana menilai mereka dengan kemampuan terbaik saya.",
  ui_story_5045_50450401_13_dialog_content = "Begitu... Tapi dari yang bisa kukatakan, kau sudah menandai semuanya untuk dikirim ulang. Kenapa begitu?",
  ui_story_5045_50450401_14_dialog_content = "Menurut ketentuan Lumopolis yang baru diubah, sejauh ini, semua kasus yang saya tangani memiliki beberapa masalah.",
  ui_story_5045_50450401_15_dialog_content = "Saya hanya mengikuti aturan, itu saja.",
  ui_story_5045_50450401_16_dialog_content = "Tetapi pada tingkat ini, Anda tidak akan pernah bisa menutup satu kasus pun!",
  ui_story_5045_50450401_17_dialog_content = "Heh... Sepertinya kamu lebih terburu-buru daripada aku.",
  ui_story_5045_50450401_18_dialog_content = "Nah, jelas! Kita rekan, bukan?",
  ui_story_5045_50450401_19_dialog_content = "Mitra...?",
  ui_story_5045_50450401_20_dialog_content = "Benar sekali!",
  ui_story_5045_50450401_21_dialog_content = "Saya menghargai perhatian Anda, sungguh, Tapi saya bersumpah bahwa saya tidak akan mengambil keuntungan dari kerja keras Anda.",
  ui_story_5045_50450401_22_dialog_content = "Baiklah... Kalau begitu mari kita jalan-jalan sebentar, oke? Sepertinya Anda perlu istirahat sebentar.",
  ui_story_5045_50450401_23_dialog_content = "Tentu. Selain itu aku sudah lama bermaksud menanyakan sesuatu padamu, PlayerName.",
  ui_story_5045_50450401_24_dialog_content = "Tahukah kamu apa itu cinta?",
  ui_story_5045_50450401_25_dialog_content = "Saya suka?",
  ui_story_5045_50450401_26_option_content = "Ya.",
  ui_story_5045_50450401_27_dialog_content = "Saat dua orang sangat menyukai satu sama lain sehingga mereka rela menghabiskan sisa hidup mereka bersama, bukan?",
  ui_story_5045_50450401_28_dialog_content = "Saya harus mengatakan, pemahaman Anda tentang dunia kadang-kadang sangat mengesankan saya, PlayerName!",
  ui_story_5045_50450401_29_dialog_content = "Aku hanya menebak, sungguh...",
  ui_story_5045_50450401_30_option_content = "Tidak juga...",
  ui_story_5045_50450401_31_dialog_content = "Tapi aku sudah membaca tentang cinta di banyak cerita!",
  ui_story_5045_50450401_32_dialog_content = "Menilai dari deskripsi mereka, cinta adalah sesuatu yang sangat misterius.",
  ui_story_5045_50450401_33_dialog_content = "Jadi, Anda penggemar kisah cinta, PlayerName? Sepertinya aku bertanya pada orang yang tepat.",
  ui_story_5045_50450401_34_dialog_content = "A-aku tidak akan mengatakan aku penggemar atau apapun...",
  ui_story_5045_50450401_35_option_content = "Saya tidak akan memberi tahu!",
  ui_story_5045_50450401_36_dialog_content = "Ini rahasia, dan aku tidak memberitahu!",
  ui_story_5045_50450401_37_dialog_content = "B-Betapa misteriusnya dirimu...",
  ui_story_5045_50450401_38_dialog_content = "Kamu sendiri cukup populer, bukan, Leyn?",
  ui_story_5045_50450401_39_dialog_content = "Anda mungkin tahu lebih banyak tentang cinta daripada saya, bukan?",
  ui_story_5045_50450401_40_dialog_content = "Hmm…",
  ui_story_5045_50450401_41_dialog_content = "Saya kira memang benar bahwa saya telah menjadi objek kasih sayang lebih dari beberapa wanita.",
  ui_story_5045_50450401_42_dialog_content = "Tapi sayangnya, aku tidak pernah bisa membalas perasaan mereka.",
  ui_story_5045_50450401_43_dialog_content = "Hah? Kenapa begitu?",
  ui_story_5045_50450401_44_dialog_content = "Aku tidak tahu. Sejujurnya, saya tidak pernah terlalu memikirkannya.",
  ui_story_5045_50450401_45_dialog_content = "Tetapi ketika saya ditugaskan ke Divisi Percintaan Hall of Justice, dan bertugas membantu pasangan menyelesaikan perselisihan mereka.",
  ui_story_5045_50450401_46_dialog_content = "Saat itulah saya menyadari bahwa saya tidak tahu apa-apa tentang cinta.",
  ui_story_5045_50450401_47_dialog_content = "Aku bahkan mulai ragu apakah aku pernah merasakan cinta sebelumnya dalam hidupku...",
  ui_story_5045_50450401_48_dialog_content = "Apakah saya benar-benar cocok untuk bekerja sebagai juri di Divisi Percintaan?",
  ui_story_5045_50450401_49_dialog_content = "Tentu saja kamu!",
  ui_story_5045_50450401_50_dialog_content = "Apa yang membuatmu begitu yakin tentang itu?",
  ui_story_5045_50450401_51_dialog_content = "Seorang hakim tidak harus mencuri untuk menghakimi seorang pencuri, bukan?",
  ui_story_5045_50450401_52_dialog_content = "Saya cukup yakin hal yang sama berlaku untuk menyelesaikan masalah hubungan!",
  ui_story_5045_50450401_53_dialog_content = "Itu sepertinya sedikit peregangan ...",
  ui_story_5045_50450401_54_dialog_content = "Tapi di satu sisi, itu sangat masuk akal!",
  ui_story_5045_50450401_55_dialog_content = "Menatap keluhan ini sepanjang hari tidak akan membawa Anda terlalu jauh. Yang paling penting adalah belajar melalui latihan!",
  ui_story_5045_50450401_56_dialog_content = "Anda harus mencoba beberapa kasus dan membangun pengalaman Anda terlebih dahulu. Sisanya harus datang dengan cukup cepat!",
  ui_story_5045_50450401_57_dialog_content = "Kau benar... Aku tidak percaya akhir-akhir ini aku begitu ragu-ragu!",
  ui_story_5045_50450401_58_dialog_content = "Saya harus mulai dengan kasus pertama di depan saya!",
  ui_story_5045_50450401_59_dialog_content = "\"Penggugat, <color=#1875ad>Farrel</color>, menuntut agar tergugat, <color=#1875ad>Sophie</color>, nikahi dia sesuai dengan hukum...\"",
  ui_story_5045_50450401_60_dialog_content = "I-Ini semacam permintaan... Mungkin kamu harus mulai dengan sesuatu yang tidak terlalu rumit?",
  ui_story_5045_50450401_61_dialog_content = "Tak perlu.",
  ui_story_5045_50450401_62_dialog_content = "Sebagai seorang hakim, adalah tanggung jawab saya untuk menangani setiap kasus ini dengan kemampuan terbaik saya.",
  ui_story_5045_50450401_63_dialog_content = "Tidak hanya itu...",
  ui_story_5045_50450401_64_dialog_content = "Saya menyadari bahwa membuang-buang bakat Anda untuk meminta Anda membantu saya mengatur keluhan.",
  ui_story_5045_50450401_65_dialog_content = "Mulai besok, Anda dan saya akan mendengar setiap kasus ini bersama-sama.",
  ui_story_5045_50450401_66_dialog_content = "H-Hah? Apa kamu yakin akan hal itu?",
  ui_story_5045_50450401_67_dialog_content = "Tentu saja. Anda mengatakannya sendiri: kami adalah mitra, bukan?",
  ui_story_5045_50450501_1_dialog_content = "<color=#737378>Waktu: 09:00</color>",
  ui_story_5045_50450501_2_dialog_content = "<color=#737378>Lokasi: Balai Kehakiman Lumo, Ruang Sidang</color>",
  ui_story_5045_50450501_3_dialog_content = "Lihat ke sana! Dia Leyn!",
  ui_story_5045_50450501_4_dialog_content = "...",
  ui_story_5045_50450501_5_dialog_content = "(Sepertinya banyak penonton wanita yang datang hanya untuk melihat Leyn?)",
  ui_story_5045_50450501_6_dialog_content = "<color=#737378>Bum!</color>",
  ui_story_5045_50450501_7_dialog_content = "<size=45>Malam Putih di atas. Pengadilan sekarang dalam sesi!</size>",
  ui_story_5045_50450501_8_dialog_content = "Demi White Night!",
  ui_story_5045_50450501_9_dialog_content = "...",
  ui_story_5045_50450501_10_dialog_content = "Apakah Anda tahu siapa yang harus pertama kali ditangani oleh pengadilan, PlayerName?",
  ui_story_5045_50450501_11_dialog_content = "Hmm... aku cukup yakin itu seharusnya penggugat...",
  ui_story_5045_50450501_12_option_content = "Farrel",
  ui_story_5045_50450501_13_dialog_content = "Itu benar! Senang melihat Anda ingat!",
  ui_story_5045_50450501_14_option_content = "Sophie",
  ui_story_5045_50450501_15_dialog_content = "Penggugatnya adalah Farrel.",
  ui_story_5045_50450501_16_dialog_content = "Membedakan antara penggugat dan tergugat adalah salah satu bagian pekerjaan yang paling mendasar. Anda harus ingat itu di masa depan.",
  ui_story_5045_50450501_17_dialog_content = "(Sobat... Bagaimana saya bisa salah?)",
  ui_story_5045_50450501_18_dialog_content = "(Saya harus memastikan untuk membuat catatan yang lebih baik tentang semuanya lain kali!)",
  ui_story_5045_50450501_19_dialog_content = "Apakah penggugat akan berbicara di pengadilan?",
  ui_story_5045_50450501_20_dialog_content = "Selamat siang, Yang Mulia. Nama saya Farrel.",
  ui_story_5045_50450501_21_dialog_content = "Penggugat adalah a <color=#1875ad>ksatria</color> dari Lumopolis, ya? Itu tak terduga...",
  ui_story_5045_50450501_22_dialog_content = "Hati-hati, PlayerName. Sebagai hakim, kita tidak dapat membiarkan praduga apa pun mempengaruhi penilaian kita.",
  ui_story_5045_50450501_23_dialog_content = "B-baiklah…",
  ui_story_5045_50450501_24_dialog_content = "Farrell, tolong beri tahu kami mengapa Anda datang ke Hall of Justice hari ini?",
  ui_story_5045_50450501_25_dialog_content = "Karena terdakwa dan saya punya kesepakatan!",
  ui_story_5045_50450501_26_dialog_content = "Tolong uraikan perjanjian ini antara kalian berdua.",
  ui_story_5045_50450501_27_dialog_content = "Kesepakatan kami adalah bahwa kami akan segera menikah <color=#1875ad>sumber daya keuangan yang sama</color>!",
  ui_story_5045_50450501_28_dialog_content = "Tapi itu normal, bukan? Orang selalu menandatangani perjanjian pertunangan seperti itu untuk melindungi aset mereka.",
  ui_story_5045_50450501_29_dialog_content = "Orang Sophie ini tidak terlihat terlalu kaya. Dia kemungkinan besar mencoba mengambil keuntungan dari status ekonomi ksatria.",
  ui_story_5045_50450501_30_dialog_content = "Apakah mereka benar-benar berpikir perselisihan kecil seperti itu layak membuang-buang waktu Hakim Leyn?",
  ui_story_5045_50450501_31_dialog_content = "<color=#737378>Bum!</color>",
  ui_story_5045_50450501_32_dialog_content = "Kesunyian! Pesan di pengadilan!",
  ui_story_5045_50450501_33_dialog_content = "Farrell, bolehkah saya bertanya apakah ada saksi dari perjanjian ini? Atau mungkin semacam bukti?",
  ui_story_5045_50450501_34_dialog_content = "Y-Ya, Yang Mulia.",
  ui_story_5045_50450501_35_dialog_content = "Ini dia <color=#1875ad>kontrak</color> kami menandatangani. Anda akan menemukan bahwa itu dibuat sesuai dengan peraturan Lumopolis.",
  ui_story_5045_50450501_36_dialog_content = "Hmm... Kontraknya tampaknya sudah dalam urutan yang sempurna.",
  ui_story_5045_50450501_37_dialog_content = "Maukah Anda menyampaikan tuntutan Anda ke pengadilan?",
  ui_story_5045_50450501_38_dialog_content = "Karena keuangan kami sekarang setara, saya meminta pengadilan menegakkan kesepakatan kami untuk menikah satu sama lain!",
  ui_story_5045_50450501_39_dialog_content = "Maaf, apakah saya mendengarnya dengan benar?",
  ui_story_5045_50450501_40_dialog_content = "Bagaimana mungkin keuangan orang biasa sama dengan seorang ksatria?",
  ui_story_5045_50450501_41_dialog_content = "Terdakwa jelas menipu dia dari uangnya.",
  ui_story_5045_50450501_42_dialog_content = "Sophie.",
  ui_story_5045_50450501_43_dialog_content = "Ya, Yang Mulia!",
  ui_story_5045_50450501_44_dialog_content = "Apakah Anda memiliki sesuatu untuk dikatakan tentang kontrak ini?",
  ui_story_5045_50450501_45_dialog_content = "Saya tahu, Yang Mulia. Memang benar saya menandatangani perjanjian itu.",
  ui_story_5045_50450501_46_dialog_content = "Tetapi ketika saya bertemu Farrell, saya masih muda dan belum berpengalaman dalam cara dunia... Saya tidak tahu apa arti cinta saat itu.",
  ui_story_5045_50450501_47_dialog_content = "Saat itu, Farrell merayuku dengan kata-kata manis dan janji-janji muluk. Dia membuatku benar-benar percaya bahwa dia adalah belahan jiwaku.",
  ui_story_5045_50450501_48_dialog_content = "Saya kewalahan oleh kasih sayangnya yang palsu, itulah sebabnya saya menandatangani kontrak itu.",
  ui_story_5045_50450501_49_dialog_content = "Tapi seiring berjalannya waktu, aku menyadari kita tidak ditakdirkan untuk bersama. Saya bahkan menyarankan agar kami berpisah lebih dari satu kali.",
  ui_story_5045_50450501_50_dialog_content = "Untuk alasan ini, saya mematuhi perjanjian kami untuk menikah.",
  ui_story_5045_50450501_51_dialog_content = "Dengan kata lain, Anda menolak untuk menghormati isi perjanjian yang ditandatangani ini. Apakah itu benar?",
  ui_story_5045_50450501_52_dialog_content = "Ya, Yang Mulia. Saya lebih suka menghabiskan sisa hidup saya di penjara daripada menghabiskannya dengan seseorang yang tidak saya cintai.",
  ui_story_5045_50450501_53_dialog_content = "J-Jangan katakan hal seperti itu, Sophie...",
  ui_story_5045_50450501_54_dialog_content = "Anda tahu bahwa memutuskan pertunangan kita hanya akan merusak reputasi saya sebagai seorang ksatria!",
  ui_story_5045_50450501_55_dialog_content = "Bagaimana mungkin kamu masih begitu buta terhadap cintaku padamu ?!",
  ui_story_5045_50450501_56_dialog_content = "Aku tidak tahan lagi dengan cintamu, Farrel...",
  ui_story_5045_50450501_57_dialog_content = "Anda tidak melakukan apa-apa selain memperhatikan setiap gerakan saya dan melecehkan saya di setiap kesempatan!",
  ui_story_5045_50450501_58_dialog_content = "Aku melakukannya hanya untuk melindungimu, Sophie!",
  ui_story_5045_50450501_59_dialog_content = "Yah, maaf, tapi aku tidak butuh perlindungan siapa pun.",
  ui_story_5045_50450501_60_dialog_content = "Betapa tidak sedap dipandang...",
  ui_story_5045_50450501_61_dialog_content = "Aku sama sekali tidak tahu apa yang mereka bicarakan...",
  ui_story_5045_50450501_62_dialog_content = "(Dan sekarang mereka berdebat? Sepertinya yang lain juga mulai bergosip di antara mereka sendiri.)",
  ui_story_5045_50450501_63_dialog_content = "(Menilai dari desahan Leyn barusan, sepertinya semua ini membuat kepalanya sakit...)",
  ui_story_5045_50450501_64_dialog_content = "Apakah Anda melihat mengapa tidak ada yang mau bergabung dengan Divisi Percintaan sekarang, PlayerName?",
  ui_story_5045_50450501_65_dialog_content = "Dalam kasus seperti ini, jarang ada undang-undang atau preseden yang bisa diandalkan.",
  ui_story_5045_50450501_66_dialog_content = "Kedua belah pihak memiliki argumen yang sangat masuk akal, yang menyulitkan hakim untuk memberikan putusan yang adil dan tidak memihak.",
  ui_story_5045_50450501_67_dialog_content = "Tapi tidak apa-apa, karena itu berfungsi sebagai semacam pelatihan bagi saya. Aku bersumpah akan menegakkan keadilan sampai akhir!",
  ui_story_5045_50450501_68_dialog_content = "Nah, apakah Anda memiliki pemikiran untuk dibagikan tentang kasus ini?",
  ui_story_5045_50450501_69_dialog_content = "Tidak sekarang, tidak...",
  ui_story_5045_50450501_70_dialog_content = "T-Tunggu, aku mengerti!",
  ui_story_5045_50450501_71_dialog_content = "Saya pikir kita harus melihat lebih dekat pada hal-hal.",
  ui_story_5045_50450501_72_dialog_content = "Baiklah…",
  ui_story_5045_50450501_73_dialog_content = "Lihatlah ini, Leyn...",
  ui_story_5045_50450501_74_dialog_content = "Nah, apakah Anda akan melihat itu? Saya harus mengatakan, melihat itu <color=#1875ad>buku catatan</color> benar-benar membawa kembali kenangan.",
  ui_story_5045_50450501_75_dialog_content = "Ketika saya menjadi hakim percobaan, saya akan membawanya setiap hari.",
  ui_story_5045_50450501_76_dialog_content = "Saya pikir ini bukan saat yang tepat untuk berbagi cerita.",
  ui_story_5045_50450501_77_dialog_content = "Mengapa kita tidak fokus pada kasus yang ada saja?",
  ui_story_5045_50450501_78_dialog_content = "Hmm…",
  ui_story_5045_50450501_79_dialog_content = "Mungkin kita harus mulai dengan itu <color=#1875ad>kontrak</color>?",
  ui_story_5045_50450501_80_dialog_content = "Pilihan bijak.",
  ui_story_5045_50450501_81_dialog_content = "Kita mungkin tidak pernah mengerti perasaan antara kedua belah pihak.",
  ui_story_5045_50450501_82_dialog_content = "Tetapi perjanjian tertulis tunduk pada perlindungan penuh hukum Lumopolis!",
  ui_story_5045_50450501_83_dialog_content = "Terima kasih atas saran Anda. Saya pikir saya punya jawaban saya sekarang.",
  ui_story_5045_50450501_84_dialog_content = "Jawaban apa itu?",
  ui_story_5045_50450501_85_dialog_content = "Sebentar lagi kau akan tahu.",
  ui_story_5045_50450501_86_dialog_content = "<color=#737378>Bum!</color>",
  ui_story_5045_50450501_87_dialog_content = "Malam Putih di atas. Sudah waktunya untuk vonis!",
  ui_story_5045_50450501_88_dialog_content = "Kedua belah pihak menyetujui orang dewasa pada penandatanganan kontrak ini, dan harus memikul tanggung jawab atas keputusan mereka.",
  ui_story_5045_50450501_89_dialog_content = "Menurut hukum yang relevan dari Lumopolis...",
  ui_story_5045_50450501_90_dialog_content = "Pengadilan dengan ini memerintahkan tergugat, Sophie, untuk menghormati ketentuan perjanjian dan menikahi penggugat, Farrell.",
  ui_story_5045_50450501_91_dialog_content = "Jika Anda tidak menerima keputusan ini, Anda dapat mengajukan banding sesuai dengan ketentuan Balai Kehakiman.",
  ui_story_5045_50450501_92_dialog_content = "<color=#737378>Bum!</color>",
  ui_story_5045_50450501_93_dialog_content = "Sidang berakhir!",
  ui_story_5045_50450501_94_dialog_content = "Bukankah kita harus bertanya kepada Sophie apakah Farrell telah melanggar bagian mana pun dari perjanjian mereka?",
  ui_story_5045_50450501_95_dialog_content = "Saya pikir Anda baru saja menyentuh aspek penting dari kasus ini, PlayerName!",
  ui_story_5045_50450501_96_dialog_content = "Sophie, Anda mengklaim bahwa penggugat telah memantau pergerakan Anda, serta melecehkan Anda. Apakah itu benar?",
  ui_story_5045_50450501_97_dialog_content = "Sangat cocok!",
  ui_story_5045_50450501_98_dialog_content = "Farrell sering memanfaatkan statusnya sebagai ksatria untuk berkeliaran di luar rumahku.",
  ui_story_5045_50450501_99_dialog_content = "Meskipun dengan jelas menolaknya berkali-kali, dia menolak untuk meninggalkan saya sendirian, dan bahkan membawa saya ke pengadilan!",
  ui_story_5045_50450501_100_dialog_content = "Yang Mulia, meskipun keluarga saya kekurangan status dan kekayaan.",
  ui_story_5045_50450501_101_dialog_content = "Itu tidak berarti saya dapat dieksploitasi oleh orang lain!",
  ui_story_5045_50450501_102_dialog_content = "Saya memiliki hak untuk mencintai atau menolak siapa pun yang saya pilih, sama seperti orang lain!",
  ui_story_5045_50450501_103_dialog_content = "Bukankah itu sebabnya Divisi Percintaan di Hall of Justice didirikan? Untuk melindungi hak-hak diri yang sama?",
  ui_story_5045_50450501_104_dialog_content = "(Terdakwa membuat poin yang sangat valid!)",
  ui_story_5045_50450501_105_dialog_content = "(Kalau dipikir-pikir, ksatria itu agak memaksakan dirinya padanya.)",
  ui_story_5045_50450501_106_dialog_content = "Harus kukatakan, Sophie, pemahamanmu tentang cinta cukup unik. Saya telah belajar banyak dari mendengarkan Anda.",
  ui_story_5045_50450501_107_dialog_content = "Anda benar sekali! Divisi Percintaan di Hall of Justice memiliki kewajiban untuk membela cinta sepenuhnya sesuai hukum!",
  ui_story_5045_50450501_108_dialog_content = "<color=#737378>Bum!</color>",
  ui_story_5045_50450501_109_dialog_content = "Malam Putih di atas. Sudah waktunya untuk vonis!",
  ui_story_5045_50450501_110_dialog_content = "Kontrak yang ditandatangani antara kedua belah pihak benar-benar sah.",
  ui_story_5045_50450501_111_dialog_content = "Namun, perbuatan penggugat telah membuat tergugat tidak mau menikah dengannya, sehingga melanggar syarat-syarat perjanjian mereka.",
  ui_story_5045_50450501_112_dialog_content = "Pengadilan tidak punya pilihan selain mengenakan denda sebesar 100 Nightium kepada terdakwa, yang harus dibayar lunas dalam jangka waktu yang ditentukan.",
  ui_story_5045_50450501_113_dialog_content = "Setelah menerima hukuman atas pelanggaran kontrak, penggugat tidak boleh lagi melecehkan tergugat, Sophie.",
  ui_story_5045_50450501_114_dialog_content = "Jika Anda tidak menerima keputusan ini, Anda dapat mengajukan banding sesuai dengan ketentuan Balai Kehakiman.",
  ui_story_5045_50450501_115_dialog_content = "Saraf orang biasa itu! Beraninya dia menodai kehormatan seorang ksatria!",
  ui_story_5045_50450501_116_dialog_content = "Terlepas dari itu, ini adalah keputusan Hakim Leyn, yang membuatnya adil dan adil.",
  ui_story_5045_50450501_117_dialog_content = "Hakim Leyn! Anda memiliki kewajiban untuk melindungi hak kami untuk mencintai juga!",
  ui_story_5045_50450501_118_dialog_content = "<color=#737378>Bum!</color>",
  ui_story_5045_50450501_119_dialog_content = "Sidang berakhir!",
  ui_story_5045_50450601_1_dialog_content = "<color=#737378>Waktu: 12:00 siang</color>",
  ui_story_5045_50450601_2_dialog_content = "<color=#737378>Lokasi: Balai Utama Balai Kehakiman Lumo</color>",
  ui_story_5045_50450601_3_dialog_content = "Sophie! Tunggu!",
  ui_story_5045_50450601_4_dialog_content = "Tolong menjauhlah dariku.",
  ui_story_5045_50450601_5_dialog_content = "Saya tahu Anda tidak akan mau menikah dengan saya, bahkan jika saya menang di pengadilan hari ini.",
  ui_story_5045_50450601_6_dialog_content = "Tapi tolong, beri kami kesempatan untuk membicarakan semuanya!",
  ui_story_5045_50450601_7_dialog_content = "Simpan ke pengadilan.",
  ui_story_5045_50450601_8_dialog_content = "<color=#737378>Waktu: 14:00</color>",
  ui_story_5045_50450601_9_dialog_content = "<color=#737378>Lokasi: Lumo Hall of Justice, Kantor Divisi Percintaan</color>",
  ui_story_5045_50450601_10_dialog_content = "Hah? Mengapa Anda masih melihat-lihat perjanjian itu, Leyn?",
  ui_story_5045_50450601_11_dialog_content = "Katakan padaku... Apakah menurutmu aku membuat keputusan yang tepat dalam kasus hari ini?",
  ui_story_5045_50450601_12_dialog_content = "Yah, saya tidak begitu tahu banyak tentang hukum dan peraturan Anda.",
  ui_story_5045_50450601_13_dialog_content = "Aku tahu. Ketika saya meminta Anda untuk membantu saya, satu-satunya harapan saya adalah agar Anda mengingatkan saya untuk memberikan penilaian yang adil dengan segala cara.",
  ui_story_5045_50450601_14_dialog_content = "Itulah sebabnya saya meminta Anda membagikan pemikiran Anda kepada saya, jika memungkinkan.",
  ui_story_5045_50450601_15_dialog_content = "Saya pikir keputusan Anda adalah ...",
  ui_story_5045_50450601_16_option_content = "Yang adil.",
  ui_story_5045_50450601_17_dialog_content = "Terima kasih atas jaminannya, tetapi saya merasa ada sesuatu yang salah.",
  ui_story_5045_50450601_18_dialog_content = "Kasus Divisi Percintaan tidak pernah sesederhana ini.",
  ui_story_5045_50450601_19_option_content = "Sedikit kasar.",
  ui_story_5045_50450601_20_dialog_content = "Hukum mungkin memiliki efek yang mengikat pada hal-hal seperti kontrak, tapi jelas tidak bisa memberi tahu orang bagaimana perasaannya.",
  ui_story_5045_50450601_21_dialog_content = "Bahkan jika Sophie akhirnya menikah dengan Farrell, saya tidak dapat membayangkan hidup mereka akan bahagia.",
  ui_story_5045_50450601_22_dialog_content = "Ah! M-Maaf, Leyn! Aku tidak mencoba menantang keputusanmu atau apapun...",
  ui_story_5045_50450601_23_dialog_content = "Tidak ada alasan untuk meminta maaf. Jika ada, saya harus berterima kasih atas kesediaan Anda untuk membimbing saya melalui kasus seperti ini.",
  ui_story_5045_50450601_24_option_content = "Saya tidak benar-benar punya pendapat.",
  ui_story_5045_50450601_25_dialog_content = "Maksudmu?",
  ui_story_5045_50450601_26_dialog_content = "Tidak memiliki pendapat tentang sesuatu adalah pendapat terburuk untuk dimiliki.",
  ui_story_5045_50450601_27_dialog_content = "Huh, sekali lagi, aku seharusnya tidak terus menggantungkan semua harapanku padamu. Maaf.",
  ui_story_5045_50450601_28_dialog_content = "(Leyn terlihat cukup kecewa pada saya ...)",
  ui_story_5045_50450601_29_dialog_content = "(Mungkin saya harus memberi tahu dia apa yang sebenarnya saya pikirkan tentang vonisnya?)",
  ui_story_5045_50450601_30_dialog_content = "Sepertinya kita harus berusaha lebih keras lagi dalam kasus ini.",
  ui_story_5045_50450601_31_dialog_content = "Ayo.",
  ui_story_5045_50450601_32_dialog_content = "Hah? Kemana?",
  ui_story_5045_50450601_33_dialog_content = "Sophie mengajukan banding.",
  ui_story_5045_50450601_34_dialog_content = "Dia mengatakan dia memiliki lebih banyak bukti untuk melengkapi kasusnya.",
  ui_story_5045_50450601_35_dialog_content = "<color=#737378>Waktu: 15:00</color>",
  ui_story_5045_50450601_36_dialog_content = "<color=#737378>Lokasi: Lumopolis Bawah</color>",
  ui_story_5045_50450601_37_dialog_content = "Selamat siang. Maaf, tapi apakah rumah Sophie ada di dekat sini?",
  ui_story_5045_50450601_38_dialog_content = "Maaf, tapi siapa kamu lagi?",
  ui_story_5045_50450601_39_dialog_content = "(Orang ini terlihat agak familiar...)",
  ui_story_5045_50450601_40_dialog_content = "Kami, eh...",
  ui_story_5045_50450601_41_dialog_content = "Oh tidak, PlayerName! Apakah Anda memiliki sesuatu untuk ditunjukkan kepadanya yang membuktikan kami <color=#1875ad>identitas</color>?",
  ui_story_5045_50450601_42_dialog_content = "Apakah ini akan berhasil?",
  ui_story_5045_50450601_43_dialog_content = "Saya tidak berpikir itu tidak banyak untuk membuktikan siapa kita.",
  ui_story_5045_50450601_44_dialog_content = "Oh, b-benarkah? Dalam hal itu...",
  ui_story_5045_50450601_45_dialog_content = "Kami adalah hakim dari Lumopolis Hall of Justice.",
  ui_story_5045_50450601_46_dialog_content = "Kami di sini atas undangan Sophie. Dia mengatakan dia memiliki lebih banyak informasi untuk diberikan untuk kasusnya.",
  ui_story_5045_50450601_47_dialog_content = "Aku tidak menyangka aku berada di hadapan dua juri! Tolong, Anda harus membantu Sophie kecil kami yang malang!",
  ui_story_5045_50450601_48_dialog_content = "Anda kenal dia?",
  ui_story_5045_50450601_49_dialog_content = "Ya pak! Nama saya adalah <color=#1875ad>karl</color>. Saya salah satu tetangganya.",
  ui_story_5045_50450601_50_dialog_content = "Bukan rahasia lagi bahwa beberapa kesatria bernama Farrell telah melecehkannya selama beberapa waktu sekarang. Dia benar-benar sengsara karenanya.",
  ui_story_5045_50450601_51_dialog_content = "Itulah sebabnya, sebagai tetangganya, kami mengambil tanggung jawab sendiri untuk mengusir setiap pengunjung yang mencurigakan.",
  ui_story_5045_50450601_52_dialog_content = "Jadi begitu. Itu menjelaskan mengapa Anda menginginkan bukti siapa kami.",
  ui_story_5045_50450601_53_dialog_content = "Katamu Farrell sudah lama melecehkan Sophie, ya?",
  ui_story_5045_50450601_54_dialog_content = "Aku tahu tidak pantas bagiku mengatakan ini tentang seorang kesatria.",
  ui_story_5045_50450601_55_dialog_content = "Tapi pria itu praktis mengintai rumahnya setiap hari.",
  ui_story_5045_50450601_56_dialog_content = "Bahkan setelah Sophie mengklarifikasi bahwa dia tidak ingin berurusan dengannya, Farrell menolak untuk menerimanya.",
  ui_story_5045_50450601_57_dialog_content = "Melihat hal-hal yang terjadi, saya tidak bisa menahan rasa takut akan keselamatannya, Anda tahu?",
  ui_story_5045_50450601_58_dialog_content = "Sepertinya tuduhan Sophie selama persidangan itu benar?",
  ui_story_5045_50450601_59_dialog_content = "Apakah itu berarti keputusan saya adalah...",
  ui_story_5045_50450601_60_dialog_content = "Rumah Sophie ada di depan. Mari saya tunjukkan jalannya.",
  ui_story_5045_50450601_61_dialog_content = "<color=#737378>Waktu: 15:20</color>",
  ui_story_5045_50450601_62_dialog_content = "<color=#737378>Lokasi: Lumopolis Bawah, Rumah Sophie</color>",
  ui_story_5045_50450601_63_dialog_content = "Mohon maafkan saya, Yang Mulia. Saya yakin rumah saya yang sederhana tampak menggelikan bagi para hakim seperti Anda.",
  ui_story_5045_50450601_64_dialog_content = "Kami tidak akan memimpikannya, Sophie. Rumah Anda sangat hangat dan mengundang, hal lain yang dapat saya pelajari dari Anda.",
  ui_story_5045_50450601_65_dialog_content = "Salah satu tetangga Anda memberi tahu kami bahwa Farrell telah melecehkan Anda setiap hari. Benarkah itu?",
  ui_story_5045_50450601_66_dialog_content = "Huh.",
  ui_story_5045_50450601_67_dialog_content = "Awalnya, dia hanya akan mengikuti saya berkeliling dan berkeliaran di luar rumah saya.",
  ui_story_5045_50450601_68_dialog_content = "Tapi hanya <color=#1875ad>pagi ini</color>, saya melihat satu set aneh <color=#1875ad>jejak kaki</color> di rumahku. Aku mulai benar-benar takut...",
  ui_story_5045_50450601_69_dialog_content = "Maksudmu jejak kaki ini di sini? Mereka terlihat sedikit aneh.",
  ui_story_5045_50450601_70_dialog_content = "Sepertinya siapa pun yang meninggalkan mereka benar-benar ingin Anda melihatnya. Mereka bahkan menginjak selembar kertas dan membiarkannya tergeletak di tanah.",
  ui_story_5045_50450601_71_dialog_content = "Tanda tumit dari jejak kaki ini sangat jelas. Polanya sangat mirip dengan yang ditinggalkan oleh sepatu bot yang biasanya dipakai para ksatria.",
  ui_story_5045_50450601_72_dialog_content = "Jejak kaki tampaknya mulai di dekat jendela ...",
  ui_story_5045_50450601_73_dialog_content = "Mungkinkah Farrell menyelinap masuk saat Sophie tidak melihat?",
  ui_story_5045_50450601_74_dialog_content = "Saya tidak bisa mengatakan dengan pasti. Apa ada barang-barangmu yang hilang, Sophie?",
  ui_story_5045_50450601_75_dialog_content = "Tidak sama sekali. Itulah yang membuat segalanya menjadi lebih menakutkan!",
  ui_story_5045_50450601_76_dialog_content = "Farrell pasti mencoba mengintimidasiku... Dan itu berhasil. Oh, apa yang harus saya lakukan?",
  ui_story_5045_50450601_77_dialog_content = "Andai saja saya meminta Anda untuk informasi lebih lanjut selama persidangan.",
  ui_story_5045_50450601_78_dialog_content = "Saya sama sekali tidak menyalahkan Anda, Yang Mulia.",
  ui_story_5045_50450601_79_dialog_content = "Tidak dapat disangkal bahwa saya melanggar hukum dengan melanggar kontrak saya dengan Farrell. Jadi tolong, kirim saja saya ke penjara!",
  ui_story_5045_50450601_80_dialog_content = "Paling tidak, aku tidak perlu menikah dengan seorang penguntit manipulatif di sana...",
  ui_story_5045_50450601_81_dialog_content = "Tenangkan pikiranmu, Sophie.",
  ui_story_5045_50450601_82_dialog_content = "Sekarang kami memiliki lebih dari cukup alasan untuk mencurigai Farrell melakukan kecurangan, kami akan memeriksa kembali kasus hari ini dengan semua uji tuntas.",
  ui_story_5045_50450601_83_dialog_content = "Apakah tidak apa-apa jika kita melihat-lihat, Sophie?",
  ui_story_5045_50450601_84_dialog_content = "Dengan segala cara, saya hanya berharap Anda tidak keberatan dengan kekacauan ini...",
  ui_story_5045_50450601_85_dialog_content = "Ahem, saya pikir menyelidiki rumah Sophie akan menyebabkan ketidaknyamanan yang tidak perlu, bukan?",
  ui_story_5045_50450601_86_dialog_content = "M-Maaf! Itu bahkan tidak terpikir olehku... Kamu cukup pandai mengetahui perasaan orang lain, Leyn!",
  ui_story_5045_50450601_87_dialog_content = "Tapi tetap saja, kami datang jauh-jauh ke sini... Farrell mungkin meninggalkan lebih banyak petunjuk.",
  ui_story_5045_50450601_88_dialog_content = "Jika ada yang bertanya, katakan saja itu ideku, oke?",
  ui_story_5045_50450601_89_dialog_content = "Bagaimana mungkin aku membiarkanmu menanggung semua kesalahan?",
  ui_story_5045_50450601_90_dialog_content = "Saat kita selesai di sini, aku pasti akan meminta maaf kepada Sophie atas namamu.",
  ui_story_5045_50450601_91_dialog_content = "Haha…",
  ui_story_5045_50450601_92_dialog_content = "Ah! Maaf, saya tidak bermaksud menguping!",
  ui_story_5045_50450601_93_dialog_content = "Tapi cara kalian berdua terus berusaha saling menyalahkan. Anda harus menjadi teman yang sangat baik.",
  ui_story_5045_50450601_94_dialog_content = "Silakan selidiki bagaimanapun Anda mau. Saya tidak pernah bisa tersinggung, ketika kalian berdua bekerja keras untuk membantu saya.",
  ui_story_5045_50450601_95_dialog_content = "... Terima kasih atas pengertian Anda.",
  ui_story_5045_50450601_96_dialog_content = "Nah, di mana kita harus memulai kita <color=#1875ad>penyelidikan</color>?",
  ui_story_5045_50450601_97_dialog_content = "Coba kuingat...",
  ui_story_5045_50450601_98_option_content = "Periksa laci",
  ui_story_5045_50450601_99_dialog_content = "Ada banyak surat yang tampak mewah di sini.",
  ui_story_5045_50450601_100_dialog_content = "Itu bukan surat biasa.",
  ui_story_5045_50450601_101_dialog_content = "Kok kau bisa bilang begitu?",
  ui_story_5045_50450601_102_dialog_content = "Soalnya saya sendiri punya banyak...",
  ui_story_5045_50450601_103_dialog_content = "Kamu juga? Tunggu... Aku mengerti sekarang! Ini adalah surat cinta, bukan?",
  ui_story_5045_50450601_104_dialog_content = "Tulisan tangan dan tanda tangan pada masing-masing berbeda.",
  ui_story_5045_50450601_105_dialog_content = "Sepertinya Sophie juga cukup populer. Tapi kami tidak punya urusan membaca surat pribadinya.",
  ui_story_5045_50450601_106_dialog_content = "Mari kita coba mencari di tempat lain.",
  ui_story_5045_50450601_106X1_dialog_content = "Di mana lagi saya harus menyelidiki?",
  ui_story_5045_50450601_107_option_content = "Periksa tanah",
  ui_story_5045_50450601_108_dialog_content = "Saya tidak melihat jejak kaki lain selain yang ada di dekat jendela.",
  ui_story_5045_50450601_109_dialog_content = "Eh, apa ini?",
  ui_story_5045_50450601_110_dialog_content = "Ini kartu? Sepertinya semacam <color=#1875ad>kartu kehadiran</color>.",
  ui_story_5045_50450601_111_dialog_content = "Oh ya. Saya mulai mengambil beberapa pelajaran tata graha baru-baru ini.",
  ui_story_5045_50450601_112_dialog_content = "Itu kartu kehadiran saya untuk kursus.",
  ui_story_5045_50450601_113_dialog_content = "Dengan kedua orang tua saya meninggal, saya tidak punya cara untuk membangun kembali bisnis keluarga kami. Tetapi itu tidak berarti saya ingin duduk diam dan tidak melakukan apa-apa!",
  ui_story_5045_50450601_114_dialog_content = "Saya ingin bekerja keras dan mengandalkan keterampilan saya sendiri untuk mencari nafkah.",
  ui_story_5045_50450601_115_dialog_content = "Saya... Saya yakin Anda akan berhasil!",
  ui_story_5045_50450601_116_option_content = "Bungkus",
  ui_story_5045_50450601_117_dialog_content = "Sepertinya tidak ada yang lain di sini, selain jejak kaki itu.",
  ui_story_5045_50450601_118_dialog_content = "Jadi dia tidak membawa apa pun, atau meninggalkan apa pun.",
  ui_story_5045_50450601_119_dialog_content = "Apa sebenarnya yang Farrel rencanakan?",
  ui_story_5045_50450601_120_dialog_content = "<color=#737378>Waktu: 17:00</color>",
  ui_story_5045_50450601_121_dialog_content = "<color=#737378>Lokasi: Stasiun Penjaga Lumopolis</color>",
  ui_story_5045_50450601_122_dialog_content = "I-Tempat ini menakutkan... Apakah ini benar-benar tempat kerja Farrell?",
  ui_story_5045_50450601_123_dialog_content = "Tentu saja itu menakutkan. Hanya bangsawan yang paling berani yang layak bekerja di sini.",
  ui_story_5045_50450601_124_dialog_content = "B-Beverly?!",
  ui_story_5045_50450601_125_dialog_content = "Farrell sedang bertugas sekarang. Jika Anda ingin melihatnya, Anda harus kembali di lain hari.",
  ui_story_5045_50450601_126_dialog_content = "Maaf mengganggu, Lady Duchess, tapi kami di sini sedang menyelidiki.",
  ui_story_5045_50450601_127_dialog_content = "Dari yang saya pahami, Farrell adalah salah satu rekan Anda di sini, ya?",
  ui_story_5045_50450601_128_dialog_content = "Memang, dia. Tapi saya pikir kasusnya sudah diselesaikan?",
  ui_story_5045_50450601_129_dialog_content = "Terdakwa mengajukan banding, yang mengharuskan kami untuk memeriksa kembali kasus tersebut.",
  ui_story_5045_50450601_130_dialog_content = "Hmph. Apakah begitu?",
  ui_story_5045_50450601_131_dialog_content = "Maka Anda sebaiknya memeriksa hal-hal lebih hati-hati kali ini. Sejak dia bertemu Sophie itu, Farrell telah menjadi pria yang sama sekali berbeda.",
  ui_story_5045_50450601_132_dialog_content = "Dia terus menggerutu tentang kehilangan kehormatannya sebagai seorang ksatria jika dia gagal menyelamatkan puterinya.",
  ui_story_5045_50450601_133_dialog_content = "Meskipun tidak menimbulkan komplikasi apa pun dalam pekerjaannya, saya menemukan semuanya sangat menjengkelkan.",
  ui_story_5045_50450601_134_dialog_content = "Seorang ksatria sejati harus melayani rakyat dengan sepenuh hati. Tapi aku takut hatinya sudah diucapkan.",
  ui_story_5045_50450601_135_dialog_content = "Saya mendengar dia pindah ke barak ini baru-baru ini. Benarkah itu?",
  ui_story_5045_50450601_136_dialog_content = "Dia. Belum lama ini, dia menyumbangkan semua kekayaan dan asetnya kepada orang miskin di Umbraton.",
  ui_story_5045_50450601_137_dialog_content = "Dia sudah tinggal di sini sejak itu.",
  ui_story_5045_50450601_138_dialog_content = "Ketidakegoisannya adalah sesuatu yang harus dipuji, tentu saja. Tapi apa hubungannya ini dengan kasusnya?",
  ui_story_5045_50450601_139_dialog_content = "A-Semua asetnya?!",
  ui_story_5045_50450601_140_dialog_content = "Bisakah Anda menunjukkan kepada kami tempat Farrell?",
  ui_story_5045_50450601_141_dialog_content = "Tempat tinggalnya ada di sebelah kiri sini. Anda mungkin melihat diri Anda masuk.",
  ui_story_5045_50450601_142_dialog_content = "<color=#737378>Beberapa lama kemudian…</color>",
  ui_story_5045_50450601_143_dialog_content = "Dengan baik? Menemukan sesuatu belum?",
  ui_story_5045_50450601_144_dialog_content = "Ukuran dan bentuk tapak kaki sangat cocok dengan cetakan sepatu bot yang ditinggalkan Farrell di rumah.",
  ui_story_5045_50450601_145_dialog_content = "Jadi sebenarnya orang yang masuk ke rumah Sophie adalah Farrell...",
  ui_story_5045_50450601_146_dialog_content = "Bagaimana denganmu, PlayerName? Ada penemuan?",
  ui_story_5045_50450601_147_dialog_content = "Selain itu, saya tidak melihat sesuatu yang aneh di kamarnya.",
  ui_story_5045_50450601_148_dialog_content = "Apakah ini... a<color=#1875ad> layang-layang</color>?",
  ui_story_5045_50450601_149_dialog_content = "Dan lihat, ada nama Sophie tertulis di atasnya!",
  ui_story_5045_50450601_150_dialog_content = "Apakah ini berarti Farrell memang mengambil sesuatu dari rumahnya? Kenapa dia tidak memberitahu kita tentang hal itu?",
  ui_story_5045_50450601_151_dialog_content = "Mungkin itu tidak terlalu berharga?",
  ui_story_5045_50450601_152_dialog_content = "Semua bukti yang kami kumpulkan sejauh ini tampaknya mengarah pada kesalahan Farrell.",
  ui_story_5045_50450601_153_dialog_content = "Jika ini masalahnya, Farrell tidak hanya akan kehilangan kasusnya. Dia akan dihadapkan dengan hukuman yang lebih berat.",
  ui_story_5045_50450601_154_dialog_content = "Hukuman seperti apa?",
  ui_story_5045_50450601_155_dialog_content = "Dia akan kehilangan statusnya sebagai ksatria, dan terpaksa hidup sebagai orang biasa.",
  ui_story_5045_50450601_156_dialog_content = "Bagi bangsawan, ini adalah salah satu hukuman terburuk yang dapat diberikan kepada seseorang dengan status mereka.",
  ui_story_5045_50450601_157_dialog_content = "Aku mengerti... Tapi sesuatu memberitahuku bahwa kasus ini lebih dari yang kita sadari.",
  ui_story_5045_50450601_158_dialog_content = "Aku juga berpikir begitu.",
  ui_story_5045_50450601_159_dialog_content = "Kami tidak boleh melewatkan satu detail pun dari persidangan besok.",
  ui_story_5045_50450701_1_dialog_content = "<color=#737378>Waktu: 09:00</color>",
  ui_story_5045_50450701_2_dialog_content = "<color=#737378>Lokasi: Balai Kehakiman Lumo, Ruang Sidang</color>",
  ui_story_5045_50450701_3_dialog_content = "Wow! Leyn terlihat setampan hari ini, bukan begitu?",
  ui_story_5045_50450701_4_dialog_content = "(Sepertinya klub penggemar Leyn kembali lagi...)",
  ui_story_5045_50450701_5_dialog_content = "Apa yang sedang kamu pikirkan, PlayerName?",
  ui_story_5045_50450701_6_dialog_content = "Tidak ada hanya...",
  ui_story_5045_50450701_7_option_content = "Anda terlihat tampan seperti biasa hari ini, Leyn!",
  ui_story_5045_50450701_8_dialog_content = "(Sial, aku mengulangi kata-kata gadis itu tanpa berpikir...)",
  ui_story_5045_50450701_9_dialog_content = "A-Ahem... Sidang akan segera berlangsung, jadi cobalah untuk fokus.",
  ui_story_5045_50450701_10_option_content = "Ingatlah untuk membuat penilaian yang adil!",
  ui_story_5045_50450701_11_dialog_content = "Saya akan. Terima kasih telah mengingatkan saya.",
  ui_story_5045_50450701_12_dialog_content = "Saya belajar pelajaran saya dari percobaan terakhir. Saya tidak akan menunjukkan keragu-raguan hari ini.",
  ui_story_5045_50450701_13_option_content = "Saya berharap saya sepopuler Anda ...",
  ui_story_5045_50450701_14_dialog_content = "Benar-benar? Saya selalu berpikir Anda memiliki ambisi yang lebih besar dari itu ...",
  ui_story_5045_50450701_15_dialog_content = "Tapi sekarang bukan waktunya untuk pembicaraan seperti itu! Sidang akan segera digelar!",
  ui_story_5045_50450701_16_dialog_content = "(Dan di sini saya pikir Leyn akan merasa lebih baik jika saya memberinya sedikit pujian...)",
  ui_story_5045_50450701_17_dialog_content = "<color=#737378>Bum!</color>",
  ui_story_5045_50450701_18_dialog_content = "<size=45>Malam Putih di atas. Pengadilan sekarang dalam sesi!</size>",
  ui_story_5045_50450701_19_dialog_content = "Pertama-tama, akankah pemohon banding, Sophie, jelaskan kasusnya?",
  ui_story_5045_50450701_20_dialog_content = "Selamat siang, Yang Mulia. Saya tidak bisa menerima putusan tingkat pertama.",
  ui_story_5045_50450701_21_dialog_content = "Saya memohon untuk membatalkan perjanjian antara Farrell dan saya.",
  ui_story_5045_50450701_22_dialog_content = "Sebagai seorang ksatria, dia menggunakan posisinya untuk menguntit dan melecehkanku.",
  ui_story_5045_50450701_23_dialog_content = "Dia bahkan masuk ke rumahku <color=#1875ad>setelah sidang pertama</color> dan meninggalkan jejak kakinya di sana!",
  ui_story_5045_50450701_24_dialog_content = "Ada yang salah dengan pernyataan Sophie!",
  ui_story_5045_50450701_25_dialog_content = "Memangnya kenapa?",
  ui_story_5045_50450701_26_dialog_content = "Hah? Tidak masalah?",
  ui_story_5045_50450701_26X1_dialog_content = "Apakah Anda yakin Anda tidak salah dengar? Izinkan saya mengatakannya sekali lagi...",
  ui_story_5045_50450701_27_dialog_content = "Lihatlah ini, Leyn...",
  ui_story_5045_50450701_28_dialog_content = "Nah, apakah Anda akan melihat itu? Saya harus mengatakan, melihat notebook itu benar-benar membawa kembali kenangan.",
  ui_story_5045_50450701_29_dialog_content = "Ketika saya menjadi hakim percobaan, saya akan membawanya setiap hari.",
  ui_story_5045_50450701_30_dialog_content = "Mengapa percakapan ini tampak begitu akrab?",
  ui_story_5045_50450701_31_dialog_content = "Maksudmu apa sih?",
  ui_story_5045_50450701_32_dialog_content = "aku sedang berpikir...",
  ui_story_5045_50450701_33_dialog_content = "Sophie, kamu bilang kamu menemukan jejak kaki ini <color=#1875ad>pagi hari sidang pertama</color>?",
  ui_story_5045_50450701_34_dialog_content = "Oh... Aku pasti salah.",
  ui_story_5045_50450701_35_dialog_content = "Yang Mulia, saya benar-benar gugup sekarang... Izinkan saya mengatakannya lagi!",
  ui_story_5045_50450701_36_dialog_content = "Pada pagi hari sidang pertama, saya menemukan jejak kaki ini di rumah saya.",
  ui_story_5045_50450701_37_dialog_content = "Tapi tidak ada yang dicuri... Saya tahu itu pasti upaya yang disengaja untuk masuk ke rumah saya dan menakut-nakuti saya!",
  ui_story_5045_50450701_38_dialog_content = "Tidak ada yang dicuri? Tetapi...",
  ui_story_5045_50450701_39_dialog_content = "Kurasa aku ingat Farrell punya <color=#1875ad>sesuatu yang menjadi milikmu</color>!",
  ui_story_5045_50450701_40_dialog_content = "Apakah ada yang salah di sini?",
  ui_story_5045_50450701_41_dialog_content = "Ah, bukan itu! Yang ingin saya katakan adalah...",
  ui_story_5045_50450701_42_dialog_content = "Ini <color=#1875ad>layang-layang</color> memiliki tanda tangan Sophie di atasnya. Itu pasti milikmu, kan?",
  ui_story_5045_50450701_43_dialog_content = "Ini...",
  ui_story_5045_50450701_44_dialog_content = "Yang Mulia, ini adalah tanda cinta kita!",
  ui_story_5045_50450701_45_dialog_content = "Saat itu, saya baru saja selesai patroli...",
  ui_story_5045_50450701_46_dialog_content = "(Erm, apakah dia akan jatuh cinta lagi di sini, di Hall of Justice?)",
  ui_story_5045_50450701_47_dialog_content = "Pak…",
  ui_story_5045_50450701_48_dialog_content = "Ya, apa yang bisa saya bantu?",
  ui_story_5045_50450701_49_dialog_content = "A-Layang-layangku tersangkut di pohon sana. Aku tahu aku seharusnya tidak menyusahkanmu...",
  ui_story_5045_50450701_50_dialog_content = "Tapi layang-layang itu sangat penting bagiku. Itu dibuat oleh ayahku...",
  ui_story_5045_50450701_51_dialog_content = "Tidak ada masalah sama sekali. Silakan tunggu beberapa saat.",
  ui_story_5045_50450701_52_dialog_content = "Terima kasih banyak! Saya benar-benar tidak tahu harus berbuat apa jika bukan karena Anda ...",
  ui_story_5045_50450701_53_dialog_content = "Itu semua dalam satu hari kerja. Tolong, jangan sebutkan itu.",
  ui_story_5045_50450701_54_dialog_content = "Erm... Apakah kamu suka menerbangkan layang-layang?",
  ui_story_5045_50450701_55_dialog_content = "Jadi, kami bertemu dari waktu ke waktu untuk menerbangkan layang-layang bersama, dan lambat laun menjadi akrab satu sama lain.",
  ui_story_5045_50450701_56_dialog_content = "Saat itulah keluarga saya ingin memilihkan istri yang cocok untuk saya.",
  ui_story_5045_50450701_57_dialog_content = "Tapi saya percaya bahwa cinta lahir dari kebebasan, dan saya tidak ingin dikendalikan oleh keluarga saya.",
  ui_story_5045_50450701_58_dialog_content = "Jadi saya meninggalkan keluarga saya dan melamar Sophie.",
  ui_story_5045_50450701_59_dialog_content = "Farrell, layang-layang kita terbang sangat tinggi!",
  ui_story_5045_50450701_60_dialog_content = "Setinggi apapun layang-layang terbang, ia harus kembali ke tanah setelah angin berhenti.",
  ui_story_5045_50450701_61_dialog_content = "Seperti tidak peduli seberapa jauh kita bepergian di dunia luas, kita akhirnya harus kembali ke keluarga yang hangat dan penuh kasih.",
  ui_story_5045_50450701_62_dialog_content = "Saya tidak yakin saya mengerti.",
  ui_story_5045_50450701_63_dialog_content = "Sophie, maukah kamu membangun keluarga bahagia bersamaku?",
  ui_story_5045_50450701_64_dialog_content = "Saya... Saya menghargai perasaan baik Anda.",
  ui_story_5045_50450701_65_dialog_content = "Tetapi apakah keluarga Anda akan menerima seseorang dengan posisi serendah saya?",
  ui_story_5045_50450701_66_dialog_content = "Sophie, jangan khawatir. Aku akan membuat mereka menerimamu.",
  ui_story_5045_50450701_67_dialog_content = "Jika kamu berselisih dengan keluargamu karena aku, aku tidak akan bisa memaafkan diriku sendiri...",
  ui_story_5045_50450701_68_dialog_content = "Aku berjanji akan menikah denganmu, tapi tolong tunggu sampai waktunya matang.",
  ui_story_5045_50450701_69_dialog_content = "Saya ingin mengembalikan kehormatan keluarga saya...",
  ui_story_5045_50450701_70_dialog_content = "Keluarga Anda dapat menerima saya setelah saya memulihkan properti keluarga saya.",
  ui_story_5045_50450701_71_dialog_content = "Itu sebabnya Anda menandatangani perjanjian pertunangan!",
  ui_story_5045_50450701_72_dialog_content = "Keberatan! Peristiwa masa lalu ini tidak ada hubungannya dengan kasus hari ini.",
  ui_story_5045_50450701_73_dialog_content = "Meskipun sedikit memalukan, harus duduk melalui kisah cinta orang lain...",
  ui_story_5045_50450701_74_dialog_content = "Saya yakinkan Anda bahwa ini semua terkait dengan kasus ini!",
  ui_story_5045_50450701_75_dialog_content = "Ditolak!",
  ui_story_5045_50450701_76_dialog_content = "Yang Mulia, saya akui bahwa kami memiliki hubungan yang baik, tetapi itu sudah berakhir sekarang.",
  ui_story_5045_50450701_77_dialog_content = "Aku sudah lama putus dengannya.",
  ui_story_5045_50450701_78_dialog_content = "Kita memiliki kebebasan untuk mencintai, dan kebebasan untuk tidak mencintai.",
  ui_story_5045_50450701_79_dialog_content = "Anda tidak dapat memaksa seseorang untuk menyerahkan kebahagiaan hidupnya hanya karena apa yang tertulis di selembar kertas!",
  ui_story_5045_50450701_80_dialog_content = "Ya, apa yang dikatakan Pemohon cukup beralasan.",
  ui_story_5045_50450701_81_dialog_content = "Tapi setelah kami putus, Farrell masih melecehkan saya dan sering mengikuti saya...",
  ui_story_5045_50450701_82_dialog_content = "Dia bahkan masuk ke rumahku!",
  ui_story_5045_50450701_83_dialog_content = "Hmm... Kenapa Sophie begitu yakin bahwa jejak kaki itu adalah milik Farrell?",
  ui_story_5045_50450701_84_dialog_content = "Itu karena Farrell melecehkan Sophie sehingga secara tidak sadar dia percaya itu miliknya, bukan?",
  ui_story_5045_50450701_85_dialog_content = "Tapi... ini hanya tebakan. Mari kita bertanya kepada klien.",
  ui_story_5045_50450701_86_dialog_content = "Farrell, apakah Anda mengakui tuduhan Sophie?",
  ui_story_5045_50450701_87_dialog_content = "Aku…",
  ui_story_5045_50450701_88_dialog_content = "Saya akui bahwa kadang-kadang saya mencari Sophie setelah patroli saya, tetapi saya hanya ingin memintanya untuk memberi saya kesempatan lagi.",
  ui_story_5045_50450701_89_dialog_content = "Malam Putih di atas. Saya bersumpah atas kehormatan saya sebagai seorang ksatria bahwa saya tidak melakukan apa pun yang tidak diinginkan kepada Sophie.",
  ui_story_5045_50450701_90_dialog_content = "Sophie, apakah seseorang masuk ke kamarmu?",
  ui_story_5045_50450701_91_dialog_content = "Itu semua salah ku. Seharusnya aku ada di sana untuk melindungimu...",
  ui_story_5045_50450701_92_dialog_content = "Sepertinya dia tidak akan mengakui bahwa jejak kaki itu adalah miliknya.",
  ui_story_5045_50450701_93_dialog_content = "Kalau saja ada beberapa cara untuk mengidentifikasi jejak kaki...",
  ui_story_5045_50450701_94_dialog_content = "... Itu dia! Mari kita bandingkan jejak kaki di pengadilan!",
  ui_story_5045_50450701_95_dialog_content = "<color=#737378>Bum!</color>",
  ui_story_5045_50450701_96_dialog_content = "Farrell, tolong buat jejak di kertas ini.",
  ui_story_5045_50450701_97_dialog_content = "B-baiklah…",
  ui_story_5045_50450701_98_dialog_content = "Dapatkah Anda melihat perbedaan, PlayerName?",
  ui_story_5045_50450701_99_dialog_content = "Jejak yang ditinggalkan oleh sol dan tumit yang keras kira-kira memiliki kedalaman yang sama.",
  ui_story_5045_50450701_100_dialog_content = "Dan ada banyak robekan di sepanjang tepi telapak kaki. Tampaknya sepatu bot ini telah dipakai selama bertahun-tahun.",
  ui_story_5045_50450701_101_dialog_content = "Tetapi <color=#1875ad>jejak kaki</color> kami menemukan hari itu adalah...",
  ui_story_5045_50450701_102_dialog_content = "Apakah ada masalah dengan ini?",
  ui_story_5045_50450701_103_dialog_content = "Batuk, batuk, saya telah membuat kesalahan!",
  ui_story_5045_50450701_104_dialog_content = "Jejak kaki dari rumah Sophie memiliki pola yang sangat jelas—pola yang jelas dibuat oleh sepatu baru, tetapi sepatu Farrell sudah tua dan compang-camping.",
  ui_story_5045_50450701_105_dialog_content = "Kedua jejak kaki itu sangat berbeda.",
  ui_story_5045_50450701_106_dialog_content = "Apa!?",
  ui_story_5045_50450701_107_dialog_content = "TIDAK! Mungkin dia memakai sepasang sepatu baru hari itu.",
  ui_story_5045_50450701_108_dialog_content = "Yah, itu bukan hal yang mustahil.",
  ui_story_5045_50450701_109_dialog_content = "Yang Mulia, saya hanya punya sepatu bot ini sekarang...",
  ui_story_5045_50450701_110_dialog_content = "Siapa tahu? Mungkin Anda menyembunyikan sepatu bot sejak hari itu di suatu tempat yang tidak akan ditemukan siapa pun?",
  ui_story_5045_50450701_111_dialog_content = "Tidak... Orang yang masuk ke rumah Sophie bukanlah Farrell!",
  ui_story_5045_50450701_112_dialog_content = "Dan apa yang membuat Anda begitu yakin pada kesimpulan itu, PlayerName?",
  ui_story_5045_50450701_113_dialog_content = "Jejak kaki yang ditemukan di rumah Sophie... Jejak kaki yang ditinggalkan sangat jelas.",
  ui_story_5045_50450701_114_dialog_content = "Jejak kaki seperti itu hanya terjadi saat memakai sepatu yang jauh lebih besar dari kaki Anda sendiri.",
  ui_story_5045_50450701_115_dialog_content = "Oleh karena itu, jejak kaki di rumah Sophie tidak mungkin merupakan milik Farrell.",
  ui_story_5045_50450701_116_dialog_content = "Kekuatan pengamatanmu sangat cerdik!",
  ui_story_5045_50450701_117_dialog_content = "Lantas, siapa yang sengaja memakai sepatu boots yang ukurannya lebih besar dari kakinya sendiri agar bisa meninggalkan jejak kaki di rumah Sophie?",
  ui_story_5045_50450701_118_dialog_content = "Hmm…",
  ui_story_5045_50450701_119_dialog_content = "Sophie, apakah Anda membuat bukti ini sendiri?",
  ui_story_5045_50450701_120_dialog_content = "Eh, aku...",
  ui_story_5045_50450701_121_dialog_content = "Malam Putih tinggi-tinggi! Ini Balai Kehakiman, Anda wajib mengatakan yang sebenarnya!",
  ui_story_5045_50450701_122_dialog_content = "Saya takut Anda masih akan mempertahankan penilaian awal, jadi saya membuat keputusan sendiri.",
  ui_story_5045_50450701_123_dialog_content = "Saya melakukan kesalahan, Yang Mulia, tapi saya benar-benar tidak ingin menikah dengan Farrell!",
  ui_story_5045_50450701_124_dialog_content = "Apakah karena Farrell tidak memiliki satu sen pun untuk namanya?",
  ui_story_5045_50450701_125_dialog_content = "...",
  ui_story_5045_50450701_126_dialog_content = "Meskipun tidak secara eksplisit dinyatakan, perjanjian Anda menyebutkan bahwa jika Anda memiliki cukup uang, Anda akan menikah.",
  ui_story_5045_50450701_127_dialog_content = "Tapi, sekarang...",
  ui_story_5045_50450701_128_dialog_content = "<color=#1875ad>Kondisi harta Farrell</color> telah mengalami perubahan yang signifikan.",
  ui_story_5045_50450701_129_dialog_content = "Tempat apa itu?",
  ui_story_5045_50450701_130_dialog_content = "Oh, sebenarnya yang ingin kukatakan adalah...",
  ui_story_5045_50450701_131_dialog_content = "Farrell, dapatkah Anda memberi tahu kami mengapa Anda ingin memberikan semua properti Anda?",
  ui_story_5045_50450701_132_dialog_content = "I-Ini adalah tanggung jawabku sebagai seorang ksatria.",
  ui_story_5045_50450701_133_dialog_content = "Benarkah begitu?",
  ui_story_5045_50450701_134_dialog_content = "Malam Putih tinggi-tinggi! Farrell, kamu harus tahu bahwa kejujuran adalah kualitas paling dasar dari ksatria mana pun.",
  ui_story_5045_50450701_135_dialog_content = "Hmm…",
  ui_story_5045_50450701_136_dialog_content = "Baiklah, aku akan bicara.",
  ui_story_5045_50450701_137_dialog_content = "Maaf, investasi terakhir itu adalah bebek lumpuh lainnya...",
  ui_story_5045_50450701_138_dialog_content = "Tapi kali ini akan berbeda!",
  ui_story_5045_50450701_139_dialog_content = "Farrell, bisakah kamu meminjamkan saya uang lagi? Saya tahu saya akan memilih pemenang kali ini!",
  ui_story_5045_50450701_140_dialog_content = "Sophie, aku punya kabar baik.",
  ui_story_5045_50450701_141_dialog_content = "Saya telah memberikan semua properti saya.",
  ui_story_5045_50450701_142_dialog_content = "Tapi... kenapa kau melakukan hal seperti itu?",
  ui_story_5045_50450701_143_dialog_content = "Dengan cara ini, kita akan setara secara finansial.",
  ui_story_5045_50450701_144_dialog_content = "Kita bisa menikah.",
  ui_story_5045_50450701_145_dialog_content = "Sophie mencoba untuk waktu yang lama, tetapi dia tidak bisa mendapatkan kembali harta keluarganya.",
  ui_story_5045_50450701_146_dialog_content = "Aku tidak ingin dia bekerja begitu keras.",
  ui_story_5045_50450701_147_dialog_content = "Uang dan harta benda adalah hal-hal yang dangkal. Cinta di antara kita berdua lebih penting dari apa pun di dunia!",
  ui_story_5045_50450701_148_dialog_content = "Jelas, Sophie tidak setuju dengan Anda tentang itu.",
  ui_story_5045_50450701_149_dialog_content = "... Benar, saya tidak berpikir dia melakukannya.",
  ui_story_5045_50450701_150_dialog_content = "Saya percaya uang menjadi prasyarat untuk membangun keluarga.",
  ui_story_5045_50450701_151_dialog_content = "Saya tidak pernah setuju dengan pendekatan Farrell, yang menunjukkan bahwa kami jelas tidak cocok—jadi saya putus dengannya.",
  ui_story_5045_50450701_152_dialog_content = "Apakah ada yang salah dengan itu?",
  ui_story_5045_50450701_153_dialog_content = "Setelah kita menikah, kita bisa bekerja keras bersama dan perlahan membangun kekayaan kita sendiri!",
  ui_story_5045_50450701_154_dialog_content = "Tapi aku tidak mencintaimu lagi.",
  ui_story_5045_50450701_155_dialog_content = "Atau lebih tepatnya, aku tidak mencintaimu sejak awal.",
  ui_story_5045_50450701_156_dialog_content = "Apakah Anda puas sekarang?",
  ui_story_5045_50450701_157_dialog_content = "Sophie... Tidak... Itu tidak benar!",
  ui_story_5045_50450701_158_dialog_content = "Farrel yang malang...",
  ui_story_5045_50450701_159_dialog_content = "Leyn, bagaimana kita menghadapi ini?",
  ui_story_5045_50450701_160_dialog_content = "Saya selalu berpikir kasus bisa dinilai berdasarkan hukum saja.",
  ui_story_5045_50450701_161_dialog_content = "Tetapi hal-hal berbeda di Divisi Percintaan ...",
  ui_story_5045_50450701_162_dialog_content = "Lagi pula, emosi tidak dapat dijelaskan dan dipahami dengan mudah.",
  ui_story_5045_50450701_163_dialog_content = "Jika terus seperti ini, mereka berdua hanya akan berakhir dengan kesengsaraan dan penyesalan.",
  ui_story_5045_50450701_164_dialog_content = "Saya harap penilaian kami dapat melindungi keduanya pada saat yang sama.",
  ui_story_5045_50450701_165_dialog_content = "Apakah itu berarti Anda punya ide?",
  ui_story_5045_50450701_166_dialog_content = "Ya.",
  ui_story_5045_50450701_167_dialog_content = "<color=#737378>Bum!</color>",
  ui_story_5045_50450701_168_dialog_content = "Malam Putih di atas. Sudah waktunya untuk vonis!",
  ui_story_5045_50450701_169_dialog_content = "Pertama, meskipun perjanjian pertunangan antara Farrell dan Sophie sah dan efektif...",
  ui_story_5045_50450701_170_dialog_content = "Namun, persidangan ulang menemukan bahwa perbedaan antara Sophie dan Farrell tidak dapat didamaikan.",
  ui_story_5045_50450701_171_dialog_content = "Kedua, tuduhan Sophie terhadap Farrell tidak benar. Secara khusus, Farrell tidak mengikuti Sophie ke rumahnya dan memasuki propertinya secara ilegal.",
  ui_story_5045_50450701_172_dialog_content = "Tapi cintanya yang sedih dan sepihak tidak membuat pernikahan.",
  ui_story_5045_50450701_173_dialog_content = "Oleh karena itu, kami sampai pada penilaian berikut!",
  ui_story_5045_50450701_174_dialog_content = "Sophie harus memberi Farrell permintaan maaf publik...",
  ui_story_5045_50450701_175_dialog_content = "... mengklarifikasi alasan pembatalan pertunangan dan tuduhan palsu atas intrusi ilegal Farrell.",
  ui_story_5045_50450701_176_dialog_content = "Setelah persidangan, Farrell tidak boleh menghubungi Sophie secara pribadi—Pengawal akan memberlakukan pemantauan internalnya sendiri untuk efek ini.",
  ui_story_5045_50450701_177_dialog_content = "<color=#737378>Bum!</color>",
  ui_story_5045_50450701_178_dialog_content = "Sidang berakhir!",
  ui_story_5045_50450801_1_dialog_content = "<color=#737378>Waktu: 12:00 siang</color>",
  ui_story_5045_50450801_2_dialog_content = "<color=#737378>Lokasi: Balai Kehakiman Lumo, Ruang Sidang</color>",
  ui_story_5045_50450801_3_dialog_content = "Yang Mulia, bisakah Anda membantu saya memberikan ini kepada Sophie?",
  ui_story_5045_50450801_4_dialog_content = "Saya pikir Sophie dan saya akan menerbangkan layang-layang bersama lagi...",
  ui_story_5045_50450801_5_dialog_content = "Sekarang sepertinya itu tidak akan pernah terjadi... Tidak dalam hidup ini.",
  ui_story_5045_50450801_6_dialog_content = "Meskipun saya tergoda untuk menyimpannya sebagai kenang-kenangan ...",
  ui_story_5045_50450801_7_dialog_content = "Itu dibuat oleh mendiang ayah Sophie, jadi saya pikir dia mungkin lebih membutuhkannya daripada saya.",
  ui_story_5045_50450801_8_dialog_content = "Yakinlah, kami akan mengirimkannya ke Sophie.",
  ui_story_5045_50450801_9_dialog_content = "Anda akan bertemu seseorang yang benar-benar mencintai Anda suatu hari nanti!",
  ui_story_5045_50450801_10_dialog_content = "Tolong beri tahu Sophie bahwa saya akan menunggunya.",
  ui_story_5045_50450801_11_dialog_content = "... Saya pikir Anda pantas mendapatkan istirahat yang baik.",
  ui_story_5045_50450801_12_dialog_content = "Huh...",
  ui_story_5045_50450801_13_dialog_content = "Sophie, harap tunggu!",
  ui_story_5045_50450801_14_dialog_content = "Apa ada masalah?",
  ui_story_5045_50450801_15_dialog_content = "Farrell meminta kami mengembalikan layang-layang ini padamu.",
  ui_story_5045_50450801_16_dialog_content = "Saya tidak membutuhkannya lagi. Buang saja.",
  ui_story_5045_50450801_17_dialog_content = "Bukankah itu dibuat oleh ayahmu?",
  ui_story_5045_50450801_18_dialog_content = "... Orang tua itu membuat banyak layang-layang. Aku tidak mau yang ini lagi.",
  ui_story_5045_50450801_19_dialog_content = "Haruskah Anda benar-benar menyibukkan diri dengan masalah sepele seperti itu, Yang Mulia?",
  ui_story_5045_50450801_20_dialog_content = "Hmm…",
  ui_story_5045_50450801_21_dialog_content = "Saya punya satu pertanyaan terakhir untuk ditanyakan kepada Anda, Sophie.",
  ui_story_5045_50450801_22_dialog_content = "Saya tidak punya apa-apa untuk dikatakan tentang ini.",
  ui_story_5045_50450801_23_dialog_content = "Pernahkah Anda menipu orang lain secara emosional?",
  ui_story_5045_50450801_24_dialog_content = "Bagaimana Anda bisa menggunakan kata \"tertipu\" untuk menggambarkan hubungan yang saya miliki dengan mereka?",
  ui_story_5045_50450801_25_dialog_content = "Jika kami meminta Balai Kehakiman untuk menyelidiki hubungan interpersonal Anda lebih teliti...",
  ui_story_5045_50450801_26_dialog_content = "Kami mungkin menemukan bahwa Anda tidak berbahaya seperti kelihatannya.",
  ui_story_5045_50450801_27_dialog_content = "... Tidak ada yang mengajukan tuntutan terhadap saya — Anda tidak berhak melakukan itu!",
  ui_story_5045_50450801_28_dialog_content = "Memang, tidak ada yang mengajukan tuntutan terhadap Anda.",
  ui_story_5045_50450801_29_dialog_content = "Karena targetmu adalah para bangsawan.",
  ui_story_5045_50450801_30_dialog_content = "Bahkan jika mereka tertipu, mereka tidak ingin orang lain mengetahuinya.",
  ui_story_5045_50450801_31_dialog_content = "Kali ini, Anda menemui banyak gangguan yang tidak terduga, yaitu, dia dengan sepenuh hati tulus kepada Anda.",
  ui_story_5045_50450801_32_dialog_content = "Dan entah bagaimana Anda tidak ingin mengatakan yang sebenarnya kepadanya.",
  ui_story_5045_50450801_33_dialog_content = "Dan kemudian, ketika Farrell benar-benar menyerahkan segalanya untukmu...",
  ui_story_5045_50450801_34_dialog_content = "Cukup!",
  ui_story_5045_50450801_35_dialog_content = "Saya sudah membuang terlalu banyak waktu di sini. Maaf saya harus pergi.",
  ui_story_5045_50450801_36_dialog_content = "Dia kabur... Begitu saja.",
  ui_story_5045_50450801_37_dialog_content = "Kami berjanji pada Farrell bahwa kami akan menyerahkan layang-layang itu...",
  ui_story_5045_50450801_38_dialog_content = "Kasus di sini jelas tidak jelas...",
  ui_story_5045_50450801_39_dialog_content = "Meski penghakiman telah berlalu, jiwaku berjerih lelah dalam siksaan yang tak terbendung.",
  ui_story_5045_50450801_40_dialog_content = "Yeah, aku merasa seperti... ada beban yang tak terlukiskan yang menyeret hatiku.",
  ui_story_5045_50450801_41_option_content = "Kuharap Farrel tidak terlalu keberatan.",
  ui_story_5045_50450801_42_dialog_content = "Kami melakukan semua yang kami bisa, dan hukum tidak memiliki jawaban atas pertanyaan yang tersisa.",
  ui_story_5045_50450801_43_dialog_content = "Argh, lupakan saja. Ayo cepat kembali!",
  ui_story_5045_50450801_44_dialog_content = "Kamu benar. Sebaiknya kita bergegas dan memulai kasus berikutnya!",
  ui_story_5045_50450801_45_dialog_content = "Mungkin kita akan dapat menyelesaikan kasus apa pun dengan lancar jika kita memiliki yang lebih tinggi <color=#1875ad>Hubungan</color>!",
  ui_story_5045_50450801_46_dialog_content = "Apa!?",
  ui_story_5045_50450801_47_dialog_content = "Aku hanya...",
  ui_story_5045_50450801_48_dialog_content = "Saya hanya ingin kembali dan beristirahat!",
  ui_story_5045_50450801_49_option_content = "Anda melakukan yang terbaik yang Anda bisa!",
  ui_story_5045_50450801_50_dialog_content = "Saya pikir ini adalah hasil terbaik yang bisa kami harapkan.",
  ui_story_5045_50450801_51_dialog_content = "Semoga saja begitu.",
  ui_story_5045_50450801_52_dialog_content = "Bagaimanapun, mari gunakan kesempatan ini untuk berjalan-jalan.",
  ui_story_5045_50450801_53_dialog_content = "Sedikit olahraga mungkin membuat Anda merasa lebih baik.",
  ui_story_5045_50450801_54_dialog_content = "Jika itu maumu.",
  ui_story_5045_50450801_55_dialog_content = "Cuaca hari ini benar-benar...",
  ui_story_5045_50450801_56_dialog_content = "<color=#737378>Wuuss—</color>",
  ui_story_5045_50450801_57_dialog_content = "Anginnya sangat kencang! Itu hampir mengejutkan saya.",
  ui_story_5045_50450801_58_dialog_content = "Layang-layang yang tadi kupegang... Kemana perginya layang-layang itu?",
  ui_story_5045_50450801_59_dialog_content = "Di sana!",
  ui_story_5045_50450801_60_dialog_content = "<color=#737378>Wuuss—</color>",
  ui_story_5045_50450801_61_dialog_content = "(Leyn?)",
  ui_story_5045_50450801_62_dialog_content = "(Bagaimana dia bisa terbang ke langit dan mengambil layang-layang itu!?)",
  ui_story_5045_50450801_63_dialog_content = "(Tunggu...)",
  ui_story_5045_50450801_64_dialog_content = "(Mengapa saya merasa telah melihat seluruh skenario ini dimainkan sebelumnya?)",
  ui_story_5045_50450801_65_dialog_content = "(Aku ingat sekarang!)",
  ui_story_5045_50450801_66_dialog_content = "(Itu karena Farrell, dia bertemu Sophie karena dia...)",
  ui_story_5045_50450801_67_dialog_content = "Sepertinya layang-layang ini sangat suka kabur dari tuannya.",
  ui_story_5045_50450801_68_dialog_content = "Atau apakah semua layang-layang hanya ingin mengejar kebebasan dalam angin?",
  ui_story_5045_50450801_69_dialog_content = "(Memang benar layang-layang bisa terbang ke langit biru karena angin yang mengangkatnya.)",
  ui_story_5045_50450801_70_dialog_content = "(Tapi kenapa kita harus membatasi kebebasannya dengan benang sutra?)",
  ui_story_5045_50450801_71_dialog_content = "PlayerName, Saya tahu apa yang Anda pikirkan.",
  ui_story_5045_50450801_72_dialog_content = "Tetapi saya percaya bahwa kebebasan tanpa pengekangan sama sekali bukanlah kebebasan sejati.",
  ui_story_5045_50450801_73_dialog_content = "Jika layang-layang tidak memiliki dukungan benang, ia akan segera diterbangkan ke padang gurun tandus oleh angin tanpa ampun.",
  ui_story_5045_50450801_74_dialog_content = "Meningkatnya cinta bebas baru-baru ini di Lumopolis seperti keinginan layang-layang untuk langit.",
  ui_story_5045_50450801_75_dialog_content = "Jika tidak ada benang—benang keadilan...",
  ui_story_5045_50450801_76_dialog_content = "Baik kebebasan untuk mencintai maupun kebebasan untuk tidak mencintai tidak dapat dijamin.",
  ui_story_5045_50450801_77_dialog_content = "Aku harus menyerahkannya padamu...",
  ui_story_5045_50450801_78_dialog_content = "Dari sekadar layang-layang nakal yang terbang di langit, Anda telah berhasil mengungkap misteri kehidupan, cinta, dan kebebasan.",
  ui_story_5045_50450801_79_dialog_content = "Ah! Permintaan maaf saya.",
  ui_story_5045_50450801_80_dialog_content = "Tolong jangan perhatikan omong kosongku!",
  ui_story_5045_50450801_81_dialog_content = "Hanya saja, setelah persidangan baru-baru ini, saya rasa saya mengerti bagaimana untuk maju mencoba kasus Divisi Percintaan lainnya.",
  ui_story_5045_50450801_82_dialog_content = "Tentu saja, saya berhutang semuanya atas bantuan Anda.",
  ui_story_5045_50450801_83_option_content = "Bukan masalah!",
  ui_story_5045_50450801_84_dialog_content = "Faktanya, Anda melakukan sebagian besar pekerjaan sendiri.",
  ui_story_5045_50450801_85_dialog_content = "Saya hanya mengajukan beberapa saran tidak profesional dari pinggiran.",
  ui_story_5045_50450801_86_dialog_content = "Kamu terlalu rendah hati.",
  ui_story_5045_50450801_87_dialog_content = "Jika bukan karena saran Anda, siapa yang tahu kapan saya akan menyelesaikan kasus pertama itu.",
  ui_story_5045_50450801_88_option_content = "Sepertinya ada sesuatu di pikiranmu?",
  ui_story_5045_50450801_89_dialog_content = "Tak perlu dikatakan, tidak ada yang melewati Anda, PlayerName.",
  ui_story_5045_50450801_90_dialog_content = "Sejujurnya, aku berpikir... andai saja tidak ada cinta di dunia ini.",
  ui_story_5045_50450801_91_dialog_content = "Hah? Anda tidak ingin bekerja di Divisi Percintaan?",
  ui_story_5045_50450801_92_dialog_content = "Tidak, tidak, saya menghargai posisi saya saat ini.",
  ui_story_5045_50450801_93_dialog_content = "Saya semakin merasa seolah-olah cinta itu seperti racun.",
  ui_story_5045_50450801_94_dialog_content = "Itu bisa membuat seorang ksatria yang jujur tiba-tiba menjadi begitu rendah hati...",
  ui_story_5045_50450801_95_dialog_content = "Cinta sangat sulit untuk dipahami, tetapi kami tidak dapat membiarkan kasus-kasus ini menimpa kami.",
  ui_story_5045_50450801_96_dialog_content = "Pasti ada banyak kasus cinta yang benar-benar luar biasa di dunia.",
  ui_story_5045_50450801_97_dialog_content = "Alasan Anda belum melihatnya adalah karena semua kekasih yang bahagia ini tidak akan pernah berakhir di Aula Kehakiman.",
  ui_story_5045_50450801_98_dialog_content = "Benar-benar cinta yang luar biasa? Aku ingin tahu seperti apa rasanya?",
  ui_story_5045_50450801_99_dialog_content = "Dua orang saling menghargai, percaya satu sama lain, dan memperbaiki diri untuk satu sama lain.",
  ui_story_5045_50450801_100_dialog_content = "Itulah yang saya anggap sebagai cinta yang benar-benar luar biasa.",
  ui_story_5045_50450801_101_dialog_content = "Oke…",
  ui_story_5045_50450801_102_dialog_content = "Apa yang membuat Anda tiba-tiba berada dalam suasana filosofis ini?",
  ui_story_5045_50450801_103_dialog_content = "Kata-katamu mengingatkanku pada seseorang.",
  ui_story_5045_50450801_104_dialog_content = "Siapa? Apakah saya mengenal mereka?",
  ui_story_5045_50450801_105_dialog_content = "Kau rupanya, PlayerName.",
  ui_story_5045_50450801_106_dialog_content = "Apa!?",
  ui_story_5045_50450801_107_dialog_content = "Ternyata cinta antar kekasih begitu mirip dengan persahabatan antar sekutu?",
  ui_story_5045_50450801_108_dialog_content = "Bener banget tuh... Hahaha...",
  ui_story_5045_50450801_109_dialog_content = "Dalam kasus seperti itu, saya berharap semua orang mendapatkan yang terbaik dalam masalah hati.",
  ui_story_5045_50450801_110_dialog_content = "Malam Putih, semoga cinta semua orang bisa tetap bahagia untuk waktu yang sangat lama.",
  ui_story_5045_50450801_111_dialog_content = "Tapi apa yang akan kita lakukan dengan layang-layang ini, sekarang?",
  ui_story_5045_50450801_112_dialog_content = "Untuk saat ini, mari kita urus itu atas nama mereka.",
  ui_story_5045_50450801_113_dialog_content = "<color=#737378>Wuuss—</color>",
  ui_story_5045_50450801_114_dialog_content = "Ah, angin bertiup lagi. Kali ini, aku akan merawat layang-layang ini dengan baik.",
  ui_story_5045_50450801_115_dialog_content = "May jadi kita harus membiarkan layang-layang itu terbang sekali lagi.",
  ui_story_5045_50450801_116_dialog_content = "Eh?",
  ui_story_5045_50450801_117_dialog_content = "PlayerName, pernahkah kamu menerbangkan layang-layang?",
  ui_story_5045_50450901_1_dialog_content = "<color=#737378>Waktu: 15:00</color>",
  ui_story_5045_50450901_2_dialog_content = "<color=#737378>Lokasi: Lumo Hall of Justice, Kantor Divisi Percintaan</color>",
  ui_story_5045_50450901_3_dialog_content = "(Saya tidak pernah berpikir saya akan menyelesaikan kasus secepat ini.)",
  ui_story_5045_50450901_4_dialog_content = "(Kemampuan hukum saya tidak bisa lebih baik dari kemampuan psikis saya, bukan?)",
  ui_story_5045_50450901_5_dialog_content = "(Jika Irridon melihat persidangan kami, dia mungkin berpikir untuk membayar saya lebih banyak.)",
  ui_story_5045_50450901_6_dialog_content = "(Ketika saatnya tiba, heh, saya akan memberikan Vice dan yang lainnya kejutan!)",
  ui_story_5045_50450901_7_dialog_content = "(Tapi sekali lagi...)",
  ui_story_5045_50450901_8_dialog_content = "Mengapa begitu banyak orang yang mengajukan hari ini !?",
  ui_story_5045_50450901_9_dialog_content = "Hah? Kehilangan minat dalam pekerjaan percobaan begitu cepat?",
  ui_story_5045_50450901_10_dialog_content = "T-Tidak mungkin!",
  ui_story_5045_50450901_11_dialog_content = "Ah, apa yang membuat Bunda kita selalu sibuk Irridon Di Sini?",
  ui_story_5045_50450901_12_dialog_content = "Zzz...",
  ui_story_5045_50450901_13_dialog_content = "Tina, bangun!",
  ui_story_5045_50450901_14_dialog_content = "Oke…",
  ui_story_5045_50450901_15_dialog_content = "Angel, apa yang kamu tunggu? Pergi dan buatkan teh untuk ketua juri kita yang terhormat!",
  ui_story_5045_50450901_16_dialog_content = "... Oh.",
  ui_story_5045_50450901_17_dialog_content = "Tidak perlu.",
  ui_story_5045_50450901_18_dialog_content = "Saya mendengar bahwa Anda mengadili sebuah kasus pagi ini, jadi saya datang untuk menilai akibatnya.",
  ui_story_5045_50450901_19_dialog_content = "Kasus ini dilakukan oleh buku.",
  ui_story_5045_50450901_20_dialog_content = "Sebaliknya, ujian saya besok akan menginspirasi dunia dan menjadi preseden bagi generasi mendatang untuk dipelajari dan ditiru.",
  ui_story_5045_50450901_21_dialog_content = "Ketika saatnya tiba, silakan datang lagi dan saksikan sendiri.",
  ui_story_5045_50450901_22_dialog_content = "Kita lihat saja nanti. Mungkin, jika saya punya waktu.",
  ui_story_5045_50450901_23_dialog_content = "Saya baru dengar kasus tadi pagi cukup menggegerkan. Saya ingin tahu secara spesifik.",
  ui_story_5045_50450901_24_dialog_content = "Wanita Irridon, PlayerName dan saya mencoba kasus pagi ini.",
  ui_story_5045_50450901_25_dialog_content = "Detail dan proses trialnya saya catat di notebook ini. Mohon dilihat.",
  ui_story_5045_50450901_26_dialog_content = "Menakjubkan. Anda telah membentuk beberapa kebiasaan baik sejak tiba di sini, PlayerName.",
  ui_story_5045_50450901_27_dialog_content = "Apakah Anda baru saja mengatakan bahwa kasus ini menimbulkan kegemparan?",
  ui_story_5045_50450901_28_dialog_content = "Ya.",
  ui_story_5045_50450901_29_dialog_content = "Lantas, bagaimana opini publik saat ini terkait kasus ini?",
  ui_story_5045_50450901_30_dialog_content = "Bagaimana menurutmu?",
  ui_story_5045_50450901_31_dialog_content = "Yah... Saya menduga itu pasti cukup positif, bukan?",
  ui_story_5045_50450901_32_dialog_content = "PlayerName telah membuktikan dirinya layak dipilih secara pribadi oleh Anda, Hakim Ketua, untuk membantu kami di sini.",
  ui_story_5045_50450901_33_dialog_content = "Dengan bantuan PlayerName, itu wajar saja Leyn harus membuat beberapa kemajuan juga.",
  ui_story_5045_50450901_34_dialog_content = "Mungkin tidak lama lagi dia akan menjadi juri terbaik kedua di Divisi Percintaan!",
  ui_story_5045_50450901_35_dialog_content = "Leyn, adalah PlayerNamecatatan lengkap?",
  ui_story_5045_50450901_36_dialog_content = "Ya, catatannya memang sangat lengkap.",
  ui_story_5045_50450901_37_dialog_content = "Investigasi hanya menggores permukaan, dan para pihak tidak diizinkan untuk sepenuhnya menjelaskan diri mereka sendiri di pengadilan ...",
  ui_story_5045_50450901_38_dialog_content = "Saya ingat bahwa uji coba Anda sebelumnya tidak begitu ceroboh.",
  ui_story_5045_50450901_39_dialog_content = "Kasus Divisi Percintaan berbeda dari apa pun yang pernah kita temui sebelumnya.",
  ui_story_5045_50450901_40_dialog_content = "Saya juga mencoba mencari cara terbaik untuk menangani kasus seperti itu",
  ui_story_5045_50450901_41_dialog_content = "Divisi Percintaan baru saja dibentuk, dan tidak ada kasus yang bisa kita pelajari.",
  ui_story_5045_50450901_42_dialog_content = "Saya mengerti tekanannya.",
  ui_story_5045_50450901_43_dialog_content = "Namun harap diingat bahwa kasus kecil sekalipun di mata kami dapat mempengaruhi kehidupan pihak-pihak yang berkepentingan.",
  ui_story_5045_50450901_44_dialog_content = "Cara Anda menangani setiap kasus akan memengaruhi sikap masyarakat Lumopolis terhadap hubungan romantis di masa depan.",
  ui_story_5045_50450901_45_dialog_content = "Tampaknya opini publik sebagai akibat dari mengangkat kasus ini pagi ini tidak terlalu baik...",
  ui_story_5045_50450901_46_dialog_content = "Kasus pagi ini menunjukkan kepada kita bahwa biaya untuk melanggar perjanjian pertunangan dapat diabaikan.",
  ui_story_5045_50450901_47_dialog_content = "Kita mungkin melihat lebih banyak kasus yang melibatkan pembubaran perikatan.",
  ui_story_5045_50450901_48_dialog_content = "Persiapkan dirimu.",
  ui_story_5045_50450901_49_dialog_content = "Apakah uji coba Leyn baru saja menambah beban kerja kita?",
  ui_story_5045_50450901_50_dialog_content = "Karena semua kasing kami memiliki jenis yang sama, kami seharusnya dapat menanganinya lebih cepat.",
  ui_story_5045_50450901_51_dialog_content = "Jika itu benar, kasus seperti itu akan diserahkan kepada Leyn Dan PlayerName di masa depan.",
  ui_story_5045_50450901_52_dialog_content = "Hah? Tapi dengan semua kasus ini...",
  ui_story_5045_50450901_53_dialog_content = "Berapa banyak sesi yang diperlukan untuk menyelesaikan setiap percobaan?",
  ui_story_5045_50451001_1_dialog_content = "<color=#737378>Waktu: 14:00</color>",
  ui_story_5045_50451001_2_dialog_content = "<color=#737378>Lokasi: Lumo Hall of Justice, Kantor Divisi Percintaan</color>",
  ui_story_5045_50451001_3_dialog_content = "Hoamm—",
  ui_story_5045_50451001_4_dialog_content = "Hah? PlayerName, kenapa kamu menatapku dengan sangat serius?",
  ui_story_5045_50451001_5_dialog_content = "Apakah Anda baru saja tertidur?",
  ui_story_5045_50451001_6_dialog_content = "Tentu, saya tertidur ...",
  ui_story_5045_50451001_7_dialog_content = "Tapi kamu sangat bahagia sekarang ...",
  ui_story_5045_50451001_8_dialog_content = "Kalau dipikir-pikir, aku baru saja bermimpi indah... Heeheehee!",
  ui_story_5045_50451001_9_dialog_content = "Ehem... Pokoknya, selama kamu bangun sekarang.",
  ui_story_5045_50451001_10_dialog_content = "Saya tidak yakin persis bagaimana saya harus membantu Anda.",
  ui_story_5045_50451001_11_dialog_content = "Jadi ketika Anda sedang tidur, saya hanya membantu berbicara dengan beberapa orang yang mengajukan kasus.",
  ui_story_5045_50451001_12_dialog_content = "Kasus baru?",
  ui_story_5045_50451001_13_dialog_content = "Biar kulihat...",
  ui_story_5045_50451001_14_dialog_content = "Baiklah terima kasih, PlayerName, tetapi keluhan ini bukan tanggung jawab Divisi Percintaan.",
  ui_story_5045_50451001_15_dialog_content = "B-Benarkah? Maaf. Saya kira saya telah melakukan lebih banyak kerugian daripada kebaikan ...",
  ui_story_5045_50451001_16_dialog_content = "Jangan dimasukkan ke dalam hati.",
  ui_story_5045_50451001_17_dialog_content = "Aku tidak memberitahumu tentang itu sebelum aku tertidur, jadi itu salahku.",
  ui_story_5045_50451001_18_dialog_content = "Namun, Anda dapat yakin bahwa meskipun jam kerja saya singkat, efisiensi saya sangat tinggi.",
  ui_story_5045_50451001_19_dialog_content = "Saya akan mengajari Anda rahasia kerja unik saya sebentar lagi.",
  ui_story_5045_50451001_20_dialog_content = "Wow, itu luar biasa! Mari kita mulai!",
  ui_story_5045_50451001_21_dialog_content = "Tidak perlu terburu-buru. Jawab saja pertanyaanku dulu.",
  ui_story_5045_50451001_22_dialog_content = "Jika suatu hari Anda jatuh cinta dengan seseorang, apakah Anda akan memberi tahu mereka?",
  ui_story_5045_50451001_23_option_content = "Ya.",
  ui_story_5045_50451001_24_dialog_content = "Jika saya tahu itu benar-benar cinta, saya ingin memberi tahu mereka.",
  ui_story_5045_50451001_25_dialog_content = "Bahkan jika mereka menolakku, itu tidak masalah. Saya akan melakukannya untuk menghormati perasaan itu.",
  ui_story_5045_50451001_26_dialog_content = "Saya tidak pernah berharap Anda begitu berwawasan dalam hal ini, PlayerName.",
  ui_story_5045_50451001_27_dialog_content = "Saya berharap orang yang saya suka berpikir seperti Anda, heehee.",
  ui_story_5045_50451001_28_option_content = "Tidak.",
  ui_story_5045_50451001_29_dialog_content = "Jika mereka tidak membalas cintaku, mengakui cintaku hanya akan membuat mereka kesulitan.",
  ui_story_5045_50451001_30_dialog_content = "Jadi, saya tidak berpikir saya akan memberi tahu mereka terlalu tergesa-gesa.",
  ui_story_5045_50451001_31_dialog_content = "Heehee, kamu sama pemalunya seperti yang kukira, PlayerName.",
  ui_story_5045_50451001_32_option_content = "Aku tidak tahu.",
  ui_story_5045_50451001_33_dialog_content = "Saya tidak bisa memprediksi bagaimana perasaan saya di masa depan.",
  ui_story_5045_50451001_34_dialog_content = "Saya mungkin tahu apa yang harus dilakukan saat itu.",
  ui_story_5045_50451001_35_dialog_content = "Hmph, jawaban yang membosankan.",
  ui_story_5045_50451001_36_dialog_content = "Aku tidak memahami maksudmu. Mengapa Anda bertanya?",
  ui_story_5045_50451001_37_dialog_content = "Sepertinya ini tidak ada hubungannya dengan pekerjaan kita.",
  ui_story_5045_50451001_38_dialog_content = "Itu ada hubungannya dengan pekerjaan kita.",
  ui_story_5045_50451001_39_dialog_content = "Di divisi apa kita bekerja?",
  ui_story_5045_50451001_40_dialog_content = "Divisi Romantis.",
  ui_story_5045_50451001_41_dialog_content = "Jadi, tentunya kita harus membahas topik yang berhubungan dengan cinta.",
  ui_story_5045_50451001_42_dialog_content = "Dan membahas topik cinta dapat dengan cepat menghasilkan hubungan kerja yang lebih dekat.",
  ui_story_5045_50451001_43_dialog_content = "Saya berharap kami dapat bekerja sama dengan senang hati.",
  ui_story_5045_50451001_44_dialog_content = "Kalau begitu…",
  ui_story_5045_50451001_45_dialog_content = "Bagaimana Anda menjawab pertanyaan tadi, Tina?",
  ui_story_5045_50451001_46_dialog_content = "Haha, saya tidak berharap Anda membalikkan keadaan pada saya seperti ini. Baiklah, izinkan saya memberi tahu Anda.",
  ui_story_5045_50451001_47_dialog_content = "Saya tidak akan pernah mengambil inisiatif. Bagaimanapun, saya seorang wanita.",
  ui_story_5045_50451001_48_dialog_content = "Paling-paling... Aku akan secara diam-diam, secara aktif meningkatkan kemungkinan kita bertemu satu sama lain.",
  ui_story_5045_50451001_49_dialog_content = "Tetapi jika Anda tidak bertemu satu sama lain, bagaimana Anda bisa tahu jika Anda benar-benar menyukainya?",
  ui_story_5045_50451001_50_dialog_content = "Apa yang akan Anda lakukan jika orang lain ternyata salah untuk Anda?",
  ui_story_5045_50451001_51_dialog_content = "Saya tidak pernah mempertimbangkan hal-hal dari perspektif seperti itu ...",
  ui_story_5045_50451001_52_dialog_content = "Itu sama seperti Anda, PlayerName. Anda mengerti lebih dari Leyn!",
  ui_story_5045_50451001_53_dialog_content = "Anda memang asisten yang baik. Saya pasti akan menyusahkan Anda dengan hal-hal seperti itu mulai sekarang.",
  ui_story_5045_50451001_54_dialog_content = "Tolong bantu saya menerima semua kasus, periksa apakah pernyataan itu benar, dan tentukan undang-undang dan peraturan yang relevan...",
  ui_story_5045_50451001_55_dialog_content = "Kemudian rangkum detail kasusnya untuk saya!",
  ui_story_5045_50451001_56_dialog_content = "Maksudmu, pada dasarnya kau ingin aku melakukan segalanya untukmu?",
  ui_story_5045_50451001_57_dialog_content = "Saya akan duduk di kursi hakim dan akhirnya melaksanakan persidangan. Ini adalah bagian yang paling krusial dan melelahkan.",
  ui_story_5045_50451001_58_dialog_content = "Tapi sepertinya kau cukup tertarik dengan persidangan... Kenapa kau tidak bergabung denganku di pengadilan?",
  ui_story_5045_50451001_59_dialog_content = "<size=32>Itu hal yang baik dia berjanji untuk membayar saya ekstra ...</size>",
  ui_story_5045_50451001_60_dialog_content = "Hmm? Apakah Anda mengatakan sesuatu?",
  ui_story_5045_50451001_61_dialog_content = "Saya bilang... dengan begitu banyak kasus yang harus diproses, yang mana yang harus kita mulai?",
  ui_story_5045_50451001_62_dialog_content = "Jangan buang waktumu untuk hal-hal sepele seperti itu... Menguap—",
  ui_story_5045_50451001_63_dialog_content = "Pilih saja yang ada di tangan Anda sekarang.",
  ui_story_5045_50451001_64_dialog_content = "\"Permintaan tergugat Fanny dan penggugat Bacon <color=#1875ad>cerai</color> menurut hukum...\"?",
  ui_story_5045_50451001_65_dialog_content = "Benar! Ayo mulai!",
  ui_story_5045_50451001_66_dialog_content = "Zzz...",
  ui_story_5045_50451001_67_dialog_content = "Apakah dia bermaksud untuk mulai bekerja atau mulai tidur...",
  ui_story_5045_50451101_1_dialog_content = "<color=#737378>Waktu: 09:00</color>",
  ui_story_5045_50451101_2_dialog_content = "<color=#737378>Lokasi: Balai Kehakiman Lumo, Ruang Sidang</color>",
  ui_story_5045_50451101_3_dialog_content = "PlayerName, apakah Anda ingat kasus mana yang kita coba hari ini?",
  ui_story_5045_50451101_4_dialog_content = "Aku ingat! Penggugat, <color=#1875ad>Daging babi asap</color> dan tergugat, <color=#1875ad>Fanny</color>'S...",
  ui_story_5045_50451101_5_option_content = "Sengketa perceraian",
  ui_story_5045_50451101_6_dialog_content = "Itu benar. Sepertinya pelajaran sebelum sidang benar-benar bekerja padamu.",
  ui_story_5045_50451101_7_dialog_content = "Mungkin suatu hari nanti, Anda akan dapat menyelesaikan uji coba sendiri.",
  ui_story_5045_50451101_8_option_content = "Pembatalan pertunangan",
  ui_story_5045_50451101_9_dialog_content = "Wow! Sepertinya pelajaran sebelum uji coba tidak berhasil untukmu.",
  ui_story_5045_50451101_10_dialog_content = "Tanggung jawab Anda yang paling mendasar adalah mengingat informasi dalam berkas kasus ini sebelum sesi pengadilan.",
  ui_story_5045_50451101_11_dialog_content = "Pada uji coba berikutnya, Anda harus mencoba untuk menonton, mendengarkan, dan mempelajari lebih lanjut.",
  ui_story_5045_50451101_12_dialog_content = "Ah, file kasus mengatakan \"perselisihan perceraian\"!",
  ui_story_5045_50451101_13_dialog_content = "Saya tidak pernah berpikir saya akan tersandung pada rintangan pertama seperti ini ...",
  ui_story_5045_50451101_14_dialog_content = "<color=#737378>Bum!</color>",
  ui_story_5045_50451101_15_dialog_content = "<size=45>Malam Putih di atas. Pengadilan sekarang dalam sesi!</size>",
  ui_story_5045_50451101_16_dialog_content = "Demi White Night!",
  ui_story_5045_50451101_17_dialog_content = "(Ada begitu banyak orang yang mendengarkan hari ini! Saya kira semua orang benar-benar memperhatikan kasus Divisi Percintaan akhir-akhir ini...)",
  ui_story_5045_50451101_18_dialog_content = "Pertama-tama, mari kita dengar apa yang dikatakan penggugat.",
  ui_story_5045_50451101_19_dialog_content = "K-Yang Mulia, nama saya Bacon.",
  ui_story_5045_50451101_20_dialog_content = "Mengapa penggugat terlihat begitu ketakutan?",
  ui_story_5045_50451101_21_dialog_content = "Bacon, tolong jangan merasa gugup atau takut.",
  ui_story_5045_50451101_22_dialog_content = "Hall of Justice adalah tempat teradil dan teraman di Lumopolis.",
  ui_story_5045_50451101_23_dialog_content = "Anda dapat menyatakan permintaan Anda dengan percaya diri di sini.",
  ui_story_5045_50451101_24_dialog_content = "Aku ingin menceraikan istriku, Fanny...",
  ui_story_5045_50451101_25_dialog_content = "Bacon, apakah Anda benar-benar harus melakukan ini?",
  ui_story_5045_50451101_26_dialog_content = "Bisakah... Bisakah Anda membiarkan saya menyelesaikannya?",
  ui_story_5045_50451101_27_dialog_content = "<color=#737378>Bum!</color>",
  ui_story_5045_50451101_28_dialog_content = "Tergugat tidak akan mengganggu penggugat.",
  ui_story_5045_50451101_29_dialog_content = "...",
  ui_story_5045_50451101_30_dialog_content = "Bacon, mengapa kamu ingin menceraikan istrimu Fanny?",
  ui_story_5045_50451101_31_dialog_content = "Karena kita... kita sangat berbeda!",
  ui_story_5045_50451101_32_dialog_content = "Sudah berapa lama kamu menikah?",
  ui_story_5045_50451101_33_dialog_content = "Tujuh tahun.",
  ui_story_5045_50451101_34_dialog_content = "Beberapa tahun yang lalu, saya memiliki pekerjaan yang cukup baik untuk menghidupi kami, sehingga hidup dapat ditoleransi.",
  ui_story_5045_50451101_35_dialog_content = "Tapi tahun lalu, saya tiba-tiba di PHK dan kehilangan sumber penghasilan.",
  ui_story_5045_50451101_36_dialog_content = "Sejak saat itu, Fanny mengomeli saya setiap hari di rumah, dan membenci saya karena tidak memiliki pekerjaan.",
  ui_story_5045_50451101_37_dialog_content = "Aku kini baru menyadari bahwa cinta diantara kita telah tergerus oleh waktu.",
  ui_story_5045_50451101_38_dialog_content = "Yang kita lihat sekarang adalah kekurangan masing-masing.",
  ui_story_5045_50451101_39_dialog_content = "Saya tidak ingin membuang waktu lagi dalam pernikahan seperti itu... Saya ingin bercerai, agar saya bisa bebas lagi.",
  ui_story_5045_50451101_40_dialog_content = "Dengan kata lain, hubungan Anda telah rusak?",
  ui_story_5045_50451101_41_dialog_content = "Tergugat, apakah Anda sependapat dengan penggugat?",
  ui_story_5045_50451101_42_dialog_content = "Yang Mulia, saya tidak setuju.",
  ui_story_5045_50451101_43_dialog_content = "Bacon menjadi sangat tertekan setelah majikannya melepaskannya.",
  ui_story_5045_50451101_44_dialog_content = "Saya hanya ingin menghibur Bacon, jadi saya akan terus memintanya untuk berbicara dan berjalan bersama saya.",
  ui_story_5045_50451101_45_dialog_content = "Saya tidak pernah berpikir untuk meninggalkan Bacon.",
  ui_story_5045_50451101_46_dialog_content = "Sejak dia kehilangan pekerjaannya, saya bekerja paruh waktu untuk menambah tabungan kami. Saya hanya pernah mengeluh mungkin sekali atau dua kali.",
  ui_story_5045_50451101_47_dialog_content = "Tapi sejak...",
  ui_story_5045_50451101_48_dialog_content = "Tapi, pada akhirnya, jika saya melakukan kesalahan, saya akan berubah!",
  ui_story_5045_50451101_49_dialog_content = "(Sepertinya Fanny baru saja ingin mengatakan sesuatu, tapi tiba-tiba <color=#1875ad>berubah pikiran</color>...)",
  ui_story_5045_50451101_50_dialog_content = "Begitulah adanya.",
  ui_story_5045_50451101_51_dialog_content = "Benarkah?",
  ui_story_5045_50451101_52_dialog_content = "Saya pikir Bacon mungkin sudah terlalu lama tidak bekerja... Dia menjadi sangat mudah gelisah.",
  ui_story_5045_50451101_53_dialog_content = "Itu sebabnya dia ingin menceraikanku—dia sangat stres!",
  ui_story_5045_50451101_54_dialog_content = "Tapi saya ingin percaya bahwa Bacon pada akhirnya akan menjadi lebih baik.",
  ui_story_5045_50451101_55_dialog_content = "Dan, apa pun yang terjadi, saya tidak akan menceraikannya!",
  ui_story_5045_50451101_56_dialog_content = "Aku tahu.",
  ui_story_5045_50451101_57_dialog_content = "Jadi... Menguap—",
  ui_story_5045_50451101_58_dialog_content = "Tina, kita sedang dalam masa percobaan! Jangan tertidur!",
  ui_story_5045_50451101_59_dialog_content = "Hah...? Ah!",
  ui_story_5045_50451101_60_dialog_content = "Terima kasih telah membangunkan saya, PlayerName. Aku hampir membodohi diriku sendiri barusan...",
  ui_story_5045_50451101_61_dialog_content = "Nah, percayalah Anda untuk memilih kasus seperti ini. Tidak mudah untuk mencoba.",
  ui_story_5045_50451101_62_dialog_content = "Setelah gelombang cinta bebas melanda Lumopolis, jumlah kasus perceraian memang meningkat.",
  ui_story_5045_50451101_63_dialog_content = "Tetapi apakah akan mengabulkan cerai atau tidak adalah masalah yang telah lama dicari oleh Divisi Percintaan.",
  ui_story_5045_50451101_64_dialog_content = "Untuk kasus saat ini, PlayerName...",
  ui_story_5045_50451101_65_dialog_content = "Apakah Anda punya ide lain?",
  ui_story_5045_50451101_66_dialog_content = "Sepertinya Anda juga belum menemukan petunjuk yang berguna.",
  ui_story_5045_50451101_67_dialog_content = "I-Petunjuk ini tidak berguna?",
  ui_story_5045_50451101_67X1_dialog_content = "Selain itu...",
  ui_story_5045_50451101_68_dialog_content = "Oh saya tahu!",
  ui_story_5045_50451101_69_dialog_content = "Tina, Lihatlah ini!",
  ui_story_5045_50451101_70_dialog_content = "Sekarang Anda dapat merekam pernyataan dari kedua sisi pengadilan tanpa saya? Tidak buruk.",
  ui_story_5045_50451101_71_dialog_content = "Anda benar-benar menyenangkan sebagai asisten.",
  ui_story_5045_50451101_72_dialog_content = "Tapi jangan hanya memperhatikan catatan!",
  ui_story_5045_50451101_73_dialog_content = "Untuk kasus saat ini...",
  ui_story_5045_50451101_74_dialog_content = "Saya tidak berpikir alasan perceraian Bacon sepenuhnya sewenang-wenang.",
  ui_story_5045_50451101_75_dialog_content = "Bukankah Bacon mengatakan bahwa dia merasa tidak ada cinta di antara mereka?",
  ui_story_5045_50451101_76_dialog_content = "Pernikahan tanpa cinta... Sulit dibayangkan.",
  ui_story_5045_50451101_77_dialog_content = "Tapi Fanny juga menjelaskan bagaimana dia hanya ingin menghibur Bacon.",
  ui_story_5045_50451101_78_dialog_content = "Dan tampak jelas bagi saya bahwa Fanny telah membulatkan tekad untuk membantu Bacon melewati masa sulit ini, apa pun yang terjadi.",
  ui_story_5045_50451101_79_dialog_content = "Masuk akal, Bacon menganggur dan depresi...",
  ui_story_5045_50451101_80_dialog_content = "Tapi Fanny tidak hanya tidak keberatan, dia juga berjanji untuk tetap bersama Bacon dan membantunya bangkit kembali.",
  ui_story_5045_50451101_81_dialog_content = "Hubungan antara suami dan istri semacam ini hanyalah kisah Lumopolis!",
  ui_story_5045_50451101_82_dialog_content = "Jika Bacon hanya marah pada saat ini, dan hakim memutuskan untuk memberinya cerai...",
  ui_story_5045_50451101_83_dialog_content = "Bukankah Dewa Cahaya akan merampas kesempatanku untuk menemukan cinta sejatiku?",
  ui_story_5045_50451101_84_dialog_content = "<color=#737378>Bum!</color>",
  ui_story_5045_50451101_85_dialog_content = "Malam Putih di atas. Sudah waktunya untuk vonis!",
  ui_story_5045_50451101_86_dialog_content = "Hall of Justice akhirnya memutuskan bahwa hubungan antara penggugat Bacon dan tergugat Fanny tidak boleh dibubarkan.",
  ui_story_5045_50451101_87_dialog_content = "Persatuan yang terbentuk di depan mata Dewa Cahaya seharusnya tidak dibuang begitu saja.",
  ui_story_5045_50451101_88_dialog_content = "Silakan terus saling mencintai dan bekerja pada pernikahan Anda.",
  ui_story_5045_50451101_89_dialog_content = "<color=#737378>Bum!</color>",
  ui_story_5045_50451101_90_dialog_content = "Sidang berakhir!",
  ui_story_5045_50451101_91_dialog_content = "Sisi cerita Fanny sangat menyentuh.",
  ui_story_5045_50451101_92_dialog_content = "Tapi tidakkah kamu merasa dia sengaja menyembunyikan sesuatu?",
  ui_story_5045_50451101_93_dialog_content = "PlayerName, kekuatan pengamatanmu cukup mengesankan.",
  ui_story_5045_50451101_94_dialog_content = "Ayo tanya Fanny apa yang dia sembunyikan.",
  ui_story_5045_50451101_95_dialog_content = "<color=#737378>Bum!</color>",
  ui_story_5045_50451101_96_dialog_content = "White Night up high, Fanny, apakah Anda yakin telah menceritakan keseluruhan cerita kepada kami?",
  ui_story_5045_50451101_97_dialog_content = "K-kurasa begitu...",
  ui_story_5045_50451101_98_dialog_content = "Jika Anda tidak mau mengatakannya... maka izinkan saya!",
  ui_story_5045_50451101_99_dialog_content = "Yang Mulia, Fanny tahu bahwa kami tidak punya banyak uang, tetapi dia masih meminjam dalam jumlah besar, dan sekarang kami berhutang.",
  ui_story_5045_50451101_100_dialog_content = "Bacon, seperti yang kubilang, itu semua untukmu.",
  ui_story_5045_50451101_101_dialog_content = "Demi aku?",
  ui_story_5045_50451101_102_dialog_content = "Kamu... Kamu meminjamnya bahkan tanpa bertanya padaku!",
  ui_story_5045_50451101_103_dialog_content = "aku hanya... aku hanya...",
  ui_story_5045_50451101_104_dialog_content = "Fanny, benarkah kamu meminjam uang tanpa sepengetahuan Bacon?",
  ui_story_5045_50451101_105_dialog_content = "... Itu benar.",
  ui_story_5045_50451101_106_dialog_content = "Yang Mulia, saya tidak bisa hidup dengan seseorang yang berbohong kepada saya seperti itu.",
  ui_story_5045_50451101_107_dialog_content = "Tolong izinkan saya untuk menceraikan Fanny.",
  ui_story_5045_50451101_108_dialog_content = "Saya hanya punya satu permintaan — tolong izinkan kami mendiskusikan pembagian aset kami.",
  ui_story_5045_50451101_109_dialog_content = "Fanny, apakah kamu setuju dengan permintaan Bacon?",
  ui_story_5045_50451101_110_dialog_content = "Sigh, saya tidak punya apa-apa lagi untuk dikatakan ...",
  ui_story_5045_50451101_111_dialog_content = "Saya akan mengikuti apa pun yang diinginkan Bacon.",
  ui_story_5045_50451101_112_dialog_content = "<color=#737378>Bum!</color>",
  ui_story_5045_50451101_113_dialog_content = "Malam Putih di atas. Sudah waktunya untuk vonis!",
  ui_story_5045_50451101_114_dialog_content = "Karena perbedaan yang tidak dapat didamaikan antara penggugat Bacon dan tergugat Fanny, Dewan Kehakiman memutuskan bahwa pernikahan mereka harus segera dibubarkan.",
  ui_story_5045_50451101_115_dialog_content = "Sesuai permintaan para pihak, mereka sekarang dapat menegosiasikan pembagian aset mereka di antara mereka sendiri.",
  ui_story_5045_50451101_116_dialog_content = "Setelah itu, mereka akan menandatangani perjanjian yang sesuai di hadapan hakim.",
  ui_story_5045_50451101_117_dialog_content = "Jika Anda tidak menerima keputusan ini, Anda dapat mengajukan banding sesuai dengan ketentuan Balai Kehakiman.",
  ui_story_5045_50451101_118_dialog_content = "<color=#737378>Bum!</color>",
  ui_story_5045_50451101_119_dialog_content = "Sidang berakhir!",
  ui_story_5045_50451201_1_dialog_content = "<color=#737378>Waktu: 11:00</color>",
  ui_story_5045_50451201_2_dialog_content = "<color=#737378>Lokasi: Balai Kehakiman Lumo, Ruang Sidang</color>",
  ui_story_5045_50451201_3_dialog_content = "Huh, Tina benar-benar akan membiarkanku melakukannya sendiri...?",
  ui_story_5045_50451201_4_dialog_content = "Apapun yang terjadi, jangan bangunkan aku sebelum jam dua siang.",
  ui_story_5045_50451201_5_dialog_content = "Tapi perjanjian penyelesaian properti antara Bacon dan Fanny...",
  ui_story_5045_50451201_6_dialog_content = "Selama tidak ada yang keberatan dengan perjanjian tersebut, Anda bisa membiarkan mereka melanjutkan dan menandatanganinya.",
  ui_story_5045_50451201_7_dialog_content = "Aku tahu kamu bisa mengatasinya... Menguap—",
  ui_story_5045_50451201_8_dialog_content = "Zzz...",
  ui_story_5045_50451201_9_dialog_content = "Hei, tidak mungkin kau bisa tertidur secepat itu!",
  ui_story_5045_50451201_10_dialog_content = "Bacon dan Fanny menandatangani perjanjian pada akhirnya. Untungnya, tidak ada yang luar biasa yang muncul.",
  ui_story_5045_50451201_11_dialog_content = "Uhh!",
  ui_story_5045_50451201_12_dialog_content = "Yang mulia...",
  ui_story_5045_50451201_13_dialog_content = "Fanny, apa yang kau lakukan di sini?",
  ui_story_5045_50451201_14_dialog_content = "<color=#737378>Waktu: 14:00</color>",
  ui_story_5045_50451201_15_dialog_content = "<color=#737378>Lokasi: Lumo Hall of Justice, Kantor Divisi Percintaan</color>",
  ui_story_5045_50451201_16_dialog_content = "Menguap.",
  ui_story_5045_50451201_17_dialog_content = "Apa yang memakanmu, PlayerName?",
  ui_story_5045_50451201_18_dialog_content = "Anda akhirnya bangun.",
  ui_story_5045_50451201_19_dialog_content = "Bacon dan Fanny menandatangani perjanjian pagi ini.",
  ui_story_5045_50451201_20_dialog_content = "Tapi Fanny segera mengajukan banding.",
  ui_story_5045_50451201_21_dialog_content = "Hah? Apakah dia tidak senang dengan bagaimana properti mereka dibagi?",
  ui_story_5045_50451201_22_dialog_content = "Anda bisa mengatakan itu, tapi bukan itu yang mungkin Anda pikirkan.",
  ui_story_5045_50451201_23_dialog_content = "Lihat kesepakatan mereka.",
  ui_story_5045_50451201_24_dialog_content = "\"Semua properti pasangan itu sekarang menjadi milik Fanny, dan semua hutang mereka menjadi milik Bacon\"?",
  ui_story_5045_50451201_25_dialog_content = "Apakah... Fanny memaksa Bacon untuk menulis ini?",
  ui_story_5045_50451201_26_dialog_content = "Sebaliknya—perjanjian itu ditulis oleh Bacon. Fanny tidak ingin memperebutkan harta mereka karena dia terlalu tertekan dengan seluruh cobaan itu.",
  ui_story_5045_50451201_27_dialog_content = "Dia menandatangani perjanjian tanpa membacanya, lalu menemukan bahwa ini adalah ketentuan setelah fakta.",
  ui_story_5045_50451201_28_dialog_content = "Bacon dengan jelas menunjukkan kepada kami bahwa dia membenci Fanny di persidangan. Kenapa dia melakukan hal ini?",
  ui_story_5045_50451201_29_dialog_content = "Fanny merasa ini menunjukkan Bacon masih mencintainya, jadi dia mengajukan banding atas putusan tersebut.",
  ui_story_5045_50451201_30_dialog_content = "Dia telah meminta kami untuk menarik keputusan perceraian.",
  ui_story_5045_50451201_31_dialog_content = "Penilaian saya... salah?",
  ui_story_5045_50451201_32_option_content = "Jangan terlalu cepat menyalahkan diri sendiri.",
  ui_story_5045_50451201_33_dialog_content = "Pihak-pihak yang berkepentingan tidak mungkin menyatakan semua fakta di pengadilan.",
  ui_story_5045_50451201_34_dialog_content = "Anda membuat penilaian yang paling sesuai dengan situasi saat itu.",
  ui_story_5045_50451201_35_dialog_content = "Sekarang, kita hanya perlu menemukan cara untuk mengekstraksi fakta dari semua ini dan bersiap untuk naik banding!",
  ui_story_5045_50451201_36_dialog_content = "... Saya tidak pernah berpikir Anda akan menjadi orang yang menghibur saya.",
  ui_story_5045_50451201_37_dialog_content = "Tapi tetap, terima kasih, PlayerName.",
  ui_story_5045_50451201_38_dialog_content = "Lagipula aku adalah hakim sejati—aku tidak akan pernah membiarkan hal sekecil ini membuatku bingung.",
  ui_story_5045_50451201_39_option_content = "Kami belum bisa memastikan.",
  ui_story_5045_50451201_40_dialog_content = "Perjanjian penyelesaian properti Bacon jelas bertentangan dengan pernyataannya sebelumnya tentang perbedaan mereka yang tidak dapat didamaikan.",
  ui_story_5045_50451201_41_dialog_content = "Bagaimana kita bisa menghakimi ketika kita tidak tahu apa yang sebenarnya terjadi di antara mereka?",
  ui_story_5045_50451201_42_dialog_content = "Kamu benar. Untuk mencoba kasus ini dengan benar, sangat penting bagi kita untuk mengetahui apa yang sebenarnya terjadi.",
  ui_story_5045_50451201_43_option_content = "Maka itu salah",
  ui_story_5045_50451201_44_dialog_content = "Tidak ada penjelasan lain untuk apa yang terjadi sekarang.",
  ui_story_5045_50451201_45_dialog_content = "Benarkah…?",
  ui_story_5045_50451201_46_dialog_content = "Namun, sebagai hakim, kami tetap harus membuat penilaian berdasarkan fakta.",
  ui_story_5045_50451201_47_dialog_content = "Tapi apa yang terjadi di antara mereka?",
  ui_story_5045_50451201_48_dialog_content = "Ayo kita pergi!",
  ui_story_5045_50451201_49_dialog_content = "Hah? Kemana?",
  ui_story_5045_50451201_50_dialog_content = "Ke rumah mereka untuk menyelidiki apa yang sebenarnya terjadi, tentunya.",
  ui_story_5045_50451201_51_dialog_content = "Dan sebaiknya kita segera melakukannya—jika kita tidak menyelesaikan penyelidikan dalam dua jam ke depan...",
  ui_story_5045_50451201_52_dialog_content = "Anda harus menggendong saya di punggung Anda ketika saya tertidur.",
  ui_story_5045_50451201_53_dialog_content = "A-Baiklah, ayo pergi!",
  ui_story_5045_50451201_54_dialog_content = "<color=#737378>Waktu: 14:30</color>",
  ui_story_5045_50451201_55_dialog_content = "<color=#737378>Lokasi: Lumopolis Bawah</color>",
  ui_story_5045_50451201_56_dialog_content = "Rumah Bacon dan Fanny ada di depan.",
  ui_story_5045_50451201_57_dialog_content = "Hei, siapa pria yang berdiri di depan pintu mereka?",
  ui_story_5045_50451201_58_dialog_content = "(Kenapa dia terlihat sangat familiar...?)",
  ui_story_5045_50451201_59_dialog_content = "...",
  ui_story_5045_50451201_60_dialog_content = "Halo. Apakah Anda tahu Bacon dan Fanny?",
  ui_story_5045_50451201_61_dialog_content = "Maaf, tapi... siapa kamu?",
  ui_story_5045_50451201_62_dialog_content = "Kami dari Balai Kehakiman.",
  ui_story_5045_50451201_63_dialog_content = "PlayerName, tunjukkan padanya hal itu dan Anda bisa membuktikan milik kami <color=#1875ad>identitas</color>.",
  ui_story_5045_50451201_64_dialog_content = "Ini?",
  ui_story_5045_50451201_65_dialog_content = "Itu bukanlah apa yang saya maksud.",
  ui_story_5045_50451201_66_dialog_content = "Oh, i-itu? Dalam hal itu...",
  ui_story_5045_50451201_67_dialog_content = "Anda hakim? Mohon maafkan kekasaran saya barusan.",
  ui_story_5045_50451201_68_dialog_content = "Saya teman Bacon. Nama <color=#1875ad>karl</color>.",
  ui_story_5045_50451201_69_dialog_content = "Saya baru saja datang ke sini mencari Bacon, tapi sepertinya hanya Fanny yang ada di rumah sekarang.",
  ui_story_5045_50451201_70_dialog_content = "(Apakah dia tidak tahu bahwa Bacon dan Fanny akan bercerai?)",
  ui_story_5045_50451201_71_dialog_content = "Jadi, apa pendapatmu tentang hubungan Bacon dengan istrinya?",
  ui_story_5045_50451201_72_dialog_content = "... Apakah mereka melakukan sesuatu yang ilegal?",
  ui_story_5045_50451201_73_dialog_content = "Mereka akan—",
  ui_story_5045_50451201_74_dialog_content = "...",
  ui_story_5045_50451201_75_dialog_content = "<size=32>Ehem... Jangan sampai detail kasus mempengaruhi pendapat saksi!</size>",
  ui_story_5045_50451201_76_dialog_content = "Kami sebenarnya hanya melakukan penelitian tentang kebahagiaan hidup berumah tangga di Lumopolis.",
  ui_story_5045_50451201_77_dialog_content = "Kami akan sangat menghargai jika Anda dapat menjawab beberapa pertanyaan untuk kami.",
  ui_story_5045_50451201_78_dialog_content = "Yah, mereka selalu menjadi pasangan yang sangat mencintai—teladan cemerlang bagi semua orang yang mengenal mereka.",
  ui_story_5045_50451201_79_dialog_content = "Apakah Anda mengetahui adanya masalah yang mungkin diperdebatkan oleh mereka berdua?",
  ui_story_5045_50451201_80_dialog_content = "Ha ha! Membantah? Bahkan jika Lumopolis jatuh dari langit, mereka tidak akan bertarung.",
  ui_story_5045_50451201_81_dialog_content = "Oh, begitu…",
  ui_story_5045_50451201_82_dialog_content = "<color=#737378>Waktu: 15:00</color>",
  ui_story_5045_50451201_83_dialog_content = "<color=#737378>Lokasi: Lumopolis Bawah, Rumah Bacon dan Fanny</color>",
  ui_story_5045_50451201_84_dialog_content = "Halo? Apakah ada orang di rumah?",
  ui_story_5045_50451201_85_dialog_content = "Yang Mulia, apa yang membawa Anda ke sini?",
  ui_story_5045_50451201_86_dialog_content = "Kami telah menerima permintaan banding Anda dan menyadari bahwa kesalahan mungkin telah dibuat selama persidangan pertama.",
  ui_story_5045_50451201_87_dialog_content = "Jadi, kami di sini untuk menemukan kalian berdua untuk memastikan detail lengkap dari situasinya.",
  ui_story_5045_50451201_88_dialog_content = "Bacon... dia bilang dia akan pulang nanti untuk mengepak tasnya.",
  ui_story_5045_50451201_89_dialog_content = "Tapi tolong, masuklah!",
  ui_story_5045_50451201_90_dialog_content = "Apa ini di tanah...?",
  ui_story_5045_50451201_91_dialog_content = "Saya minta maaf. Saya tidak punya waktu untuk membersihkan barang-barang ...",
  ui_story_5045_50451201_92_dialog_content = "Ini <color=#1875ad>piring</color> adalah...",
  ui_story_5045_50451201_93_dialog_content = "Ini aku! aku sengaja memecahkannya...",
  ui_story_5045_50451201_94_dialog_content = "Tapi piring ini sepertinya tidak rusak secara tidak sengaja.",
  ui_story_5045_50451201_95_dialog_content = "Fanny, kami datang ke sini karena suatu alasan—kami ingin menemukan kebenaran.",
  ui_story_5045_50451201_96_dialog_content = "Jika Anda masih menahan sesuatu, saya khawatir kebenaran kasus ini tidak akan terungkap.",
  ui_story_5045_50451201_97_dialog_content = "... Baik.",
  ui_story_5045_50451201_98_dialog_content = "Bacon memecahkan piring ini tadi malam.",
  ui_story_5045_50451201_99_dialog_content = "Tapi aku bisa merasakan dia sengaja mencoba membuatku marah jadi aku menerima kenyataan bahwa kami akan segera bercerai.",
  ui_story_5045_50451201_100_dialog_content = "Saya tidak mengerti. Jika Bacon memperlakukanmu seperti ini... Kenapa kau masih ingin tinggal bersamanya?",
  ui_story_5045_50451201_101_dialog_content = "Jelas, Anda tidak pernah tahu cinta sejati.",
  ui_story_5045_50451201_102_dialog_content = "Suatu hari, Anda akan memulai sebuah keluarga sendiri dengan orang yang Anda cintai...",
  ui_story_5045_50451201_103_dialog_content = "Ketika hari itu tiba, Anda akan melakukan segala daya Anda untuk mempertahankan keluarga itu.",
  ui_story_5045_50451201_104_dialog_content = "Bahkan jika Bacon ingin menghancurkan keluargamu?",
  ui_story_5045_50451201_105_dialog_content = "Yang Mulia, ada beberapa hal yang tidak bisa saya katakan di pengadilan. Saya takut Bacon akan ditertawakan.",
  ui_story_5045_50451201_106_dialog_content = "Yakinlah bahwa kami akan menjaga rahasia Anda tetap aman.",
  ui_story_5045_50451201_107_dialog_content = "Akan menjadi kepentingan terbaik semua orang jika Anda memberi tahu kami apa yang ingin Anda katakan.",
  ui_story_5045_50451201_108_dialog_content = "Suatu hari, saya mengajak Bacon berjalan-jalan dan kami menemukan acara konsultasi gratis yang diadakan oleh klinik tertentu.",
  ui_story_5045_50451201_109_dialog_content = "Saat itulah Bacon didiagnosis <color=#1875ad>depresi</color>.",
  ui_story_5045_50451201_110_dialog_content = "Dokter mengatakan ada sesuatu tentang jantungnya yang membuat Bacon lesu, depresi, insomnia...",
  ui_story_5045_50451201_111_dialog_content = "Saat itulah saya pertama kali mengetahui bahwa Bacon sakit, dan tidak hanya bermalas-malasan demi itu.",
  ui_story_5045_50451201_112_dialog_content = "Jadi setelah itu, saya tidak mengomelinya lagi.",
  ui_story_5045_50451201_113_dialog_content = "Saya hanya berharap Bacon bisa mendapatkan perawatan yang dia butuhkan dan secara bertahap menjadi lebih baik.",
  ui_story_5045_50451201_114_dialog_content = "Tapi aku benar-benar tidak menyangka Bacon tiba-tiba pergi ke Balai Kehakiman dan mengajukan gugatan cerai.",
  ui_story_5045_50451201_115_dialog_content = "Sesuatu pasti telah terjadi padanya... tapi dia menolak memberitahuku apapun.",
  ui_story_5045_50451201_116_dialog_content = "Apa yang bisa terjadi pada Bacon?",
  ui_story_5045_50451201_117_dialog_content = "Dia mungkin tidak akan memberi tahu kita jika kita bertanya langsung padanya. Mengapa kita tidak mencari petunjuk di sekitar rumah mereka terlebih dahulu?",
  ui_story_5045_50451201_118_dialog_content = "Apakah ada tempat khusus yang ingin Anda selidiki?",
  ui_story_5045_50451201_119_dialog_content = "Coba kuingat...",
  ui_story_5045_50451201_120_option_content = "Periksa dindingnya",
  ui_story_5045_50451201_121_dialog_content = "Dapatkah saya melihat itu <color=#1875ad>foto</color> tergantung di dinding?",
  ui_story_5045_50451201_122_dialog_content = "Tentu, saya akan menurunkannya untuk Anda.",
  ui_story_5045_50451201_123_dialog_content = "Ini foto Fanny dan Bacon.",
  ui_story_5045_50451201_124_dialog_content = "Ya, tapi itu tujuh tahun yang lalu.",
  ui_story_5045_50451201_125_dialog_content = "Saat itu, kami baru saja menikah dan kami tidak punya apa-apa.",
  ui_story_5045_50451201_126_dialog_content = "Saya tidak tahu bagaimana caranya, tapi entah bagaimana Bacon membujuk seorang fotografer untuk mengambil foto ini untuk kami secara gratis...",
  ui_story_5045_50451201_127_dialog_content = "Kalau dipikir-pikir, ini adalah foto pertama dan satu-satunya yang kami ambil bersama.",
  ui_story_5045_50451201_128_dialog_content = "Adalah <color=#1875ad>alamat</color> tertulis di belakang di mana Anda mengambilnya?",
  ui_story_5045_50451201_129_dialog_content = "Hm, itu aneh. Saya tidak ingat ada sesuatu yang tertulis di belakangnya ...",
  ui_story_5045_50451201_130_dialog_content = "Tapi ini tulisan tangan Bacon.",
  ui_story_5045_50451201_131_dialog_content = "Tampaknya agak mencurigakan, bukan? Mari kita tuliskan.",
  ui_story_5045_50451201_132_dialog_content = "Selain itu...",
  ui_story_5045_50451201_133_option_content = "Periksa meja",
  ui_story_5045_50451201_134_dialog_content = "Hah? Apa ini <color=#1875ad>kartu</color>?",
  ui_story_5045_50451201_135_dialog_content = "... Itu dari <color=#1875ad>kursus swadaya</color>. Itu adalah <color=#1875ad>kartu kehadiran</color>.",
  ui_story_5045_50451201_136_dialog_content = "Teman kami Karl memberi tahu saya bahwa kursus ini sangat bagus.",
  ui_story_5045_50451201_137_dialog_content = "Mereka membantu orang mengembangkan kemauan mereka sehingga mereka tidak lagi takut menghadapi kesulitan hidup.",
  ui_story_5045_50451201_138_dialog_content = "Dia mengatakan bahwa banyak orang yang mengikuti kursus ini menjalani kehidupan yang lebih baik.",
  ui_story_5045_50451201_139_dialog_content = "Mereka benar-benar menawarkan kursus seperti ini di Lumopolis?",
  ui_story_5045_50451201_140_dialog_content = "Saya sendiri belum pernah mengambil kursus seperti ini, tetapi saya tahu bahwa kursus itu cukup mahal.",
  ui_story_5045_50451201_141_dialog_content = "... Saya ingin Bacon mendapatkan bantuan, jadi saya meminjam uang untuk mendaftarkannya.",
  ui_story_5045_50451201_142_dialog_content = "Tapi Bacon mengatakan dia tidak akan pergi... Namun, tidak ada pengembalian uang untuk kursus swadaya.",
  ui_story_5045_50451201_143_dialog_content = "Jadi, saya harap Bacon bisa kembali, meski hanya untuk mencobanya sekali...",
  ui_story_5045_50451201_144_dialog_content = "Jadi Fanny meminjam uang untuk Bacon...",
  ui_story_5045_50451201_145_dialog_content = "Selain itu...",
  ui_story_5045_50451201_146_option_content = "Bungkus",
  ui_story_5045_50451201_147_dialog_content = "Memang. Sepertinya tidak ada petunjuk yang lebih berharga di sini.",
  ui_story_5045_50451201_148_dialog_content = "Tapi ini <color=#1875ad>botol</color> tampaknya agak menarik.",
  ui_story_5045_50451201_149_dialog_content = "<color=#737378>Berdesir-</color>",
  ui_story_5045_50451201_150_dialog_content = "Bumbu apa yang Anda simpan di botol ini?",
  ui_story_5045_50451201_151_dialog_content = "Oh, itu milik Bacon <color=#1875ad>botol obat</color>!",
  ui_story_5045_50451201_152_dialog_content = "Bacon telah menerima pengobatan dari dokter klinik gratis sejak saat itu, dan harus minum obat setiap hari.",
  ui_story_5045_50451201_153_dialog_content = "Saya tidak tahu apakah dia bahkan minum obatnya hari ini.",
  ui_story_5045_50451201_154_dialog_content = "Erm, Bacon benar-benar tidak keberatan membuat orang khawatir tentang dia.",
  ui_story_5045_50451201_155_dialog_content = "<color=#737378>Waktu: 16:00</color>",
  ui_story_5045_50451201_156_dialog_content = "<color=#737378>Lokasi: Lumopolis Bawah, Di Luar Klinik Gratis</color>",
  ui_story_5045_50451201_157_dialog_content = "Jadi, kami pergi ke rumah Bacon untuk menyelidiki, tapi sekarang aku merasa lebih bingung dari sebelumnya.",
  ui_story_5045_50451201_158_dialog_content = "Saya harap kami dapat menemukan beberapa informasi berguna di sini.",
  ui_story_5045_50451201_159_dialog_content = "Hai, PlayerName dan Hakim Tina!",
  ui_story_5045_50451201_160_dialog_content = "Raphael, sedang apa kau di sini?",
  ui_story_5045_50451201_161_dialog_content = "Saya bisa menanyakan hal yang sama... Di sinilah saya bekerja!",
  ui_story_5045_50451201_162_dialog_content = "Kami yakin salah satu pihak dalam kasus kami mungkin adalah pasien di sini, jadi kami datang ke sini untuk menyelidiki situasinya.",
  ui_story_5045_50451201_163_dialog_content = "Selain makanan sarapan, apakah nama Bacon berarti bagi Anda?",
  ui_story_5045_50451201_164_dialog_content = "Daging babi asap? Dia milikku <color=#1875ad>sabar</color>!",
  ui_story_5045_50451201_165_dialog_content = "Benar-benar? Kebetulan sekali...",
  ui_story_5045_50451201_166_dialog_content = "Pastilah itu. Bacon adalah pasien yang saya tangani selama acara penjangkauan klinik gratis.",
  ui_story_5045_50451201_167_dialog_content = "Kondisinya belum menunjukkan tanda-tanda membaik. Ini benar-benar sangat membingungkan.",
  ui_story_5045_50451201_168_dialog_content = "Tapi dia sudah lama tidak datang berkunjung, sekarang. Saya khawatir...",
  ui_story_5045_50451201_169_dialog_content = "Tunggu! Anda mengatakan Bacon adalah klien Anda? Apa yang terjadi padanya? Dia tidak di penjara, kan!?",
  ui_story_5045_50451201_170_dialog_content = "Jangan khawatir, tidak ada yang serius.",
  ui_story_5045_50451201_171_dialog_content = "Benar-benar? Maka Anda harus mengingatkan dia untuk datang kepada saya sesegera mungkin untuk konsultasi lebih lanjut, dan untuk mengambil obatnya.",
  ui_story_5045_50451201_172_dialog_content = "Dia pasti sudah menghabiskan obat yang kuberikan padanya terakhir kali.",
  ui_story_5045_50451201_173_dialog_content = "Hah? Tapi kami menemukan botol obat di rumahnya, dan itu penuh dengan pil...",
  ui_story_5045_50451201_174_dialog_content = "Tidak mungkin!",
  ui_story_5045_50451201_175_dialog_content = "Obat yang saya berikan Bacon hanya diberikan dalam dosis kecil. Dia seharusnya kembali padaku setelah menyelesaikan semuanya.",
  ui_story_5045_50451201_176_dialog_content = "Mungkinkah Fanny melakukan kesalahan?",
  ui_story_5045_50451201_177_dialog_content = "<color=#737378>Waktu: 17:00</color>",
  ui_story_5045_50451201_178_dialog_content = "<color=#737378>Lokasi: Lumopolis Bawah, Rumah Bacon dan Fanny</color>",
  ui_story_5045_50451201_179_dialog_content = "<size=45>Surga!</size>",
  ui_story_5045_50451201_180_dialog_content = "Ssst! Jika Fanny menemui dokter Bacon di sini, dia akan khawatir.",
  ui_story_5045_50451201_181_dialog_content = "Apa yang kautemukan, Raphael?",
  ui_story_5045_50451201_182_dialog_content = "Ini adalah obat tidur yang kuberikan pada Bacon beberapa waktu lalu.",
  ui_story_5045_50451201_183_dialog_content = "Kenapa dia tidak mengambil satu pun dari mereka?",
  ui_story_5045_50451201_184_dialog_content = "Maksudmu, Bacon telah mengumpulkan pil ini dengan sengaja?",
  ui_story_5045_50451201_185_dialog_content = "Aku benar-benar tidak mengerti apa yang dipikirkan Bacon...",
  ui_story_5045_50451201_186_dialog_content = "Raphael, seharusnya, anggap saja sebentar...",
  ui_story_5045_50451201_187_dialog_content = "Misalkan seseorang menelan semua pil ini sekaligus... Apa yang akan terjadi pada mereka?",
  ui_story_5045_50451201_188_dialog_content = "<size=45>Woah!</size>",
  ui_story_5045_50451201_189_dialog_content = "Anda masih memiliki banyak hal untuk hidup!",
  ui_story_5045_50451201_190_dialog_content = "PlayerName, aku mendapatkan firasat buruk tentang semua ini...",
  ui_story_5045_50451201_191_dialog_content = "Iya, aku juga.",
  ui_story_5045_50451201_192_dialog_content = "Tampaknya kita harus memulai persidangan lebih cepat daripada nanti.",
  ui_story_5045_50451201_193_dialog_content = "Tapi sebelum itu, aku harus meminta satu hal darimu, PlayerName.",
  ui_story_5045_50451201_194_dialog_content = "Ayo, katakan itu!",
  ui_story_5045_50451201_195_dialog_content = "Aku... akan... tidur... menggendongku kembali...",
  ui_story_5045_50451201_196_dialog_content = "Zzz...",
  ui_story_5045_50451201_197_dialog_content = "...",
  ui_story_5045_50451301_1_dialog_content = "<color=#737378>Waktu: 09:00</color>",
  ui_story_5045_50451301_2_dialog_content = "<color=#737378>Lokasi: Balai Kehakiman Lumo, Ruang Sidang</color>",
  ui_story_5045_50451301_3_dialog_content = "Hmm? Sepertinya kita tidak punya penonton hari ini...",
  ui_story_5045_50451301_4_dialog_content = "Setelah memikirkannya lama, saya percaya bahwa penonton yang hadir mungkin berpengaruh pada pihak-pihak yang terlibat dalam kasus ini.",
  ui_story_5045_50451301_5_dialog_content = "Oleh karena itu, kasus hari ini tidak akan dibuka untuk umum.",
  ui_story_5045_50451301_6_dialog_content = "Hah? Kapan Anda mulai memikirkan hal ini?",
  ui_story_5045_50451301_7_dialog_content = "Mungkin itu tadi malam ketika Anda kembali dengan saya tidur telentang.",
  ui_story_5045_50451301_8_dialog_content = "Maksudmu, kamu...",
  ui_story_5045_50451301_9_option_content = "Kamu masih bekerja sambil tidur!?",
  ui_story_5045_50451301_10_dialog_content = "Ya, saya banyak bermimpi.",
  ui_story_5045_50451301_11_dialog_content = "Kadang-kadang saya bahkan dapat memikirkan solusi dalam mimpi saya untuk masalah yang tidak pernah dapat saya tangani dalam kehidupan nyata saya.",
  ui_story_5045_50451301_12_dialog_content = "Dibandingkan dengan kehidupan nyatamu, mimpimu terdengar melelahkan...",
  ui_story_5045_50451301_13_dialog_content = "Heehee, aku tahu kau akan mengerti, PlayerName.",
  ui_story_5045_50451301_14_dialog_content = "Leyn tidak pernah sebaik Anda kepada saya.",
  ui_story_5045_50451301_15_dialog_content = "S-sungguh...?",
  ui_story_5045_50451301_16_option_content = "Anda sebenarnya cukup bisa diandalkan.",
  ui_story_5045_50451301_17_dialog_content = "Uh-huh, tentu saja.",
  ui_story_5045_50451301_18_dialog_content = "Keandalan adalah persyaratan minimum dalam profesi ini.",
  ui_story_5045_50451301_19_dialog_content = "Tunggu! Jadi, dalam pikiranmu, kamu selalu menganggapku tidak bisa diandalkan?",
  ui_story_5045_50451301_20_dialog_content = "Aku… aku…",
  ui_story_5045_50451301_21_option_content = "Apakah Anda berpura-pura tertidur?",
  ui_story_5045_50451301_22_dialog_content = "Hmm.. Sepertinya kamu masih tertinggal jauh Leyn dalam hal perhatian terhadap pasangan Anda, PlayerName.",
  ui_story_5045_50451301_23_dialog_content = "(Apakah saya membayangkan sesuatu, atau apakah Tina tiba-tiba menatapku dengan tatapan jijik?)",
  ui_story_5045_50451301_24_dialog_content = "(Tampaknya jawaban saya telah menggoyahkan kepercayaan di antara kita...)",
  ui_story_5045_50451301_25_dialog_content = "Tapi sudahlah, kita harus segera memulai uji coba.",
  ui_story_5045_50451301_26_dialog_content = "<color=#737378>Bum!</color>",
  ui_story_5045_50451301_27_dialog_content = "<size=45>Malam Putih di atas. Pengadilan sekarang dalam sesi!</size>",
  ui_story_5045_50451301_28_dialog_content = "Pertama-tama, saya memanggil Fanny pemohon untuk membuat pernyataannya.",
  ui_story_5045_50451301_29_dialog_content = "Terima kasih, Yang Mulia. Saya tidak bisa menerima keputusan perceraian dari persidangan pertama.",
  ui_story_5045_50451301_30_dialog_content = "Saya tidak setuju bahwa hubungan saya dengan Bacon telah rusak, oleh karena itu saya tidak ingin bercerai.",
  ui_story_5045_50451301_31_dialog_content = "Fani, hentikan ini...",
  ui_story_5045_50451301_32_dialog_content = "Biarkan aku pergi, tolong.",
  ui_story_5045_50451301_33_dialog_content = "Bacon, kamu masih bersikeras bahwa hubunganmu telah rusak, benar?",
  ui_story_5045_50451301_34_dialog_content = "Benar, Yang Mulia.",
  ui_story_5045_50451301_35_dialog_content = "Namun…",
  ui_story_5045_50451301_36_dialog_content = "Tindakan Anda membuktikan bahwa Anda pernah <color=#1875ad>melindungi kepentingan terbaik Fanny</color> selama ini!",
  ui_story_5045_50451301_37_dialog_content = "PlayerName, apa yang membuatmu tiba-tiba mengatakan ini?",
  ui_story_5045_50451301_38_dialog_content = "M-Kesalahanku!",
  ui_story_5045_50451301_39_dialog_content = "Yang sebenarnya ingin saya katakan adalah...",
  ui_story_5045_50451301_40_dialog_content = "Tina, Lihatlah ini!",
  ui_story_5045_50451301_41_dialog_content = "Hmm, catatanmu memang sangat detail.",
  ui_story_5045_50451301_42_dialog_content = "Tapi mengapa adegan ini tampak begitu akrab? Bukankah aku melihat ini semua dalam mimpi?",
  ui_story_5045_50451301_43_dialog_content = "Saya belum pernah mengalami mimpi buruk akhir-akhir ini... jadi, uji coba hari ini seharusnya sukses!",
  ui_story_5045_50451301_44_dialog_content = "Kemudian lagi, apakah Anda tiba-tiba menarik ini hanya agar saya menuruti ego Anda?",
  ui_story_5045_50451301_45_dialog_content = "Bukan itu. Yang sebenarnya ingin saya katakan adalah...",
  ui_story_5045_50451301_46_dialog_content = "Anda menyerahkan semua properti Anda kepada Fanny dan mengambil semua hutang Anda sendiri! Apa lagi yang perlu saya katakan?",
  ui_story_5045_50451301_47_dialog_content = "I-Ini tidak ada hubungannya dengan kehancuran pernikahan kami.",
  ui_story_5045_50451301_48_dialog_content = "Saya menyerahkan semua properti kami kepada Fanny sebagai kompensasi atas kerja kerasnya di rumah selama tujuh tahun terakhir.",
  ui_story_5045_50451301_49_dialog_content = "Aku hanya ingin memperdagangkan sebanyak ini demi kebebasanku... itu saja.",
  ui_story_5045_50451301_50_dialog_content = "Itu saja?",
  ui_story_5045_50451301_51_dialog_content = "Kau benar-benar tidak mencintaiku lagi, kan...?",
  ui_story_5045_50451301_52_dialog_content = "Itu benar, sekarang tolong berhenti menggangguku.",
  ui_story_5045_50451301_53_dialog_content = "Boo-hoo... Kenapa? Kenapa kau melakukan ini padaku!?",
  ui_story_5045_50451301_54_dialog_content = "Fanny, kami belum membawa kasus ini ke tingkat kejelasan yang memuaskan. Jangan khawatir tentang hal itu dulu.",
  ui_story_5045_50451301_55_dialog_content = "Yang Mulia, jika itu yang Bacon rasakan, saya benar-benar tidak ingin mengganggunya lagi.",
  ui_story_5045_50451301_56_dialog_content = "Apakah ada gunanya menunda uji coba ini lebih jauh?",
  ui_story_5045_50451301_57_dialog_content = "Ya! Tentu saja ada!",
  ui_story_5045_50451301_58_dialog_content = "Hmm? Mengapa Anda tiba-tiba tampak begitu bersemangat, PlayerName?",
  ui_story_5045_50451301_59_dialog_content = "Saya percaya bahwa kedua belah pihak masih saling mencintai ...",
  ui_story_5045_50451301_60_dialog_content = "Nah, apa yang Anda rencanakan selanjutnya?",
  ui_story_5045_50451301_61_dialog_content = "E-entahlah…",
  ui_story_5045_50451301_62_dialog_content = "Haha, lihat dan pelajari saja.",
  ui_story_5045_50451301_63_dialog_content = "Ahem, kami menemukan beberapa hal aneh selama penyelidikan kami.",
  ui_story_5045_50451301_64_dialog_content = "Jika Anda tidak dapat menjelaskannya dengan jelas, Anda mungkin menghadapi lebih dari sekadar cobaan di Divisi Percintaan.",
  ui_story_5045_50451301_65_dialog_content = "Salah satu hal aneh yang disebutkan adalah <color=#1875ad>hal Raphael diperiksa kemarin</color>. Dia pasti bermaksud...",
  ui_story_5045_50451301_66_dialog_content = "Bukan itu. Pikirkan lagi, PlayerName.",
  ui_story_5045_50451301_67_dialog_content = "Siap!",
  ui_story_5045_50451301_68_dialog_content = "Bacon, apakah Anda mengenali ini?",
  ui_story_5045_50451301_69_dialog_content = "Hmm…",
  ui_story_5045_50451301_70_dialog_content = "Bisakah Anda memberi tahu kami obat apa yang ada di dalam botol ini?",
  ui_story_5045_50451301_71_dialog_content = "I-Ini adalah obat tidur yang diresepkan dokter untukku.",
  ui_story_5045_50451301_72_dialog_content = "Kami bertemu dokter klinik gratis Anda Raphael Kemarin.",
  ui_story_5045_50451301_73_dialog_content = "Menurutnya, dia hanya memberi Anda pil tidur dosis kecil setiap kali Anda melihatnya.",
  ui_story_5045_50451301_74_dialog_content = "Tampaknya Anda diam-diam menimbun pil tanpa memberi tahu dokter Anda.",
  ui_story_5045_50451301_75_dialog_content = "Dengan dosis pil tidur yang begitu besar yang Anda inginkan... mungkinkah Anda berencana meracuni istri Anda?",
  ui_story_5045_50451301_76_dialog_content = "<size=45>Apa!?</size>",
  ui_story_5045_50451301_77_dialog_content = "Fanny, tidak, bukan itu! Saya tidak ingin meracuni siapa pun ...",
  ui_story_5045_50451301_78_dialog_content = "Lalu kenapa kau sengaja menyimpan obat tidur ini?",
  ui_story_5045_50451301_79_dialog_content = "...",
  ui_story_5045_50451301_80_dialog_content = "Itu tidak ada hubungannya dengan perceraian.",
  ui_story_5045_50451301_81_dialog_content = "Bacon, kamu benar-benar telah berubah. aku tidak tahu siapa kamu lagi...",
  ui_story_5045_50451301_82_dialog_content = "Fanny...",
  ui_story_5045_50451301_83_dialog_content = "Tina, Apa yang harus kita lakukan sekarang?",
  ui_story_5045_50451301_84_dialog_content = "Jika Bacon tidak membocorkan rahasianya, tidak ada yang bisa kita lakukan.",
  ui_story_5045_50451301_85_dialog_content = "Bisakah Anda memikirkan poin yang dipertanyakan yang belum kami klarifikasi?",
  ui_story_5045_50451301_86_dialog_content = "Seluruh kasus adalah satu hal besar yang patut dipertanyakan!",
  ui_story_5045_50451301_87_dialog_content = "Hm, kalau dipikir-pikir...",
  ui_story_5045_50451301_88_dialog_content = "Itu <color=#1875ad>alamat</color>!",
  ui_story_5045_50451301_89_dialog_content = "Alamat apa?",
  ui_story_5045_50451301_90_dialog_content = "Tidak... Benar, ini dia!",
  ui_story_5045_50451301_91_dialog_content = "Ada alamat di belakang foto ini yang belum kami selidiki sepenuhnya.",
  ui_story_5045_50451301_92_dialog_content = "Oh! Itu benar, Anda baru saja mengingatkan saya. Saya mengundang seorang saksi!",
  ui_story_5045_50451301_93_dialog_content = "Kapan Anda mengundang saksi? Apakah itu juga selama mimpimu?",
  ui_story_5045_50451301_94_dialog_content = "<color=#737378>Bum!</color>",
  ui_story_5045_50451301_95_dialog_content = "Sekarang, saya ingin meminta saksi <color=#1875ad>Michenny</color> untuk mengambil sikap.",
  ui_story_5045_50451301_96_dialog_content = "Selamat pagi semuanya. saya pemungut pajak, Michenny.",
  ui_story_5045_50451301_97_dialog_content = "Apakah Anda mengenali alamat tulisan tangan di belakang foto ini?",
  ui_story_5045_50451301_98_dialog_content = "Ini adalah jenis organisasi baru yang menyediakan <color=#1875ad>layanan asuransi</color>.",
  ui_story_5045_50451301_99_dialog_content = "Bacon, penggugat dalam kasus ini, membeli <color=#1875ad>asuransi jiwa</color> untuk dirinya sendiri dari agen asuransi ini.",
  ui_story_5045_50451301_100_dialog_content = "Jika Bacon menjadi korban kematian atau cedera karena kecelakaan, a <color=#1875ad>klaim besar</color> dapat diajukan ke agen asuransi.",
  ui_story_5045_50451301_101_dialog_content = "Jika itu terjadi, siapa yang akan menerima pembayaran?",
  ui_story_5045_50451301_102_dialog_content = "Menurut agensi, informasi ini bersifat rahasia.",
  ui_story_5045_50451301_103_dialog_content = "Tapi jika informasi ini sangat penting untuk kasus ini, undang-undang menyatakan bahwa kami berhak atas informasi ini.",
  ui_story_5045_50451301_104_dialog_content = "Baiklah... Terima kasih banyak!",
  ui_story_5045_50451301_105_dialog_content = "Kalau begitu, aku akan pergi.",
  ui_story_5045_50451301_106_dialog_content = "Yang Mulia, apa yang Anda maksud dengan ini?",
  ui_story_5045_50451301_107_dialog_content = "Mungkinkah ... Bacon menyiapkan semua pil ini untuk dirinya sendiri?",
  ui_story_5045_50451301_108_dialog_content = "Dia berencana meninggalkan pembayaran asuransi yang sangat besar kepada seseorang?",
  ui_story_5045_50451301_109_dialog_content = "Bacon, apakah Anda menyadari bahwa perilaku seperti ini dapat membuat Anda dipenjara?",
  ui_story_5045_50451301_110_dialog_content = "Mereka mengatakan bahwa dikirim ke Penjara Lumopolis adalah takdir yang lebih buruk daripada kematian.",
  ui_story_5045_50451301_111_dialog_content = "...",
  ui_story_5045_50451301_112_dialog_content = "Aku…",
  ui_story_5045_50451301_113_dialog_content = "Jangan khawatir. Jika Anda mengaku sekarang, kami akan menangani Anda dengan lunak.",
  ui_story_5045_50451301_114_dialog_content = "Bacon, apa yang kau rencanakan?",
  ui_story_5045_50451301_115_dialog_content = "Beritahu hakim dengan cepat. Ini adalah hal terakhir yang pernah saya minta dari Anda sebagai istri Anda.",
  ui_story_5045_50451301_116_dialog_content = "Fany, maafkan aku.",
  ui_story_5045_50451301_117_dialog_content = "Saya merencanakan begitu lama, menipu diri sendiri, dan bahkan menipu Anda, tetapi pada akhirnya ... Saya masih gagal.",
  ui_story_5045_50451301_118_dialog_content = "Apa yang telah kau lakukan...?",
  ui_story_5045_50451301_119_dialog_content = "Yang Mulia, saya adalah seorang tukang kebun, bekerja untuk rumah tangga bangsawan.",
  ui_story_5045_50451301_120_dialog_content = "Itu karena saya tidak sengaja memecahkan piring porselen kesayangan tuan sehingga saya dipecat.",
  ui_story_5045_50451301_121_dialog_content = "Karena itu, aku menjadi bahan tertawaan di antara para pelayan, dan tak seorang pun berpikir untuk mempekerjakanku...",
  ui_story_5045_50451301_122_dialog_content = "Saya bersembunyi di rumah, semakin takut untuk keluar rumah, dan tanpa harapan akan masa depan.",
  ui_story_5045_50451301_123_dialog_content = "Setelah itu, seiring bertambahnya hutang kami, Fanny mulai bekerja semakin keras.",
  ui_story_5045_50451301_124_dialog_content = "Seharusnya aku yang melindungi Fanny—melindungi rumah kami—tapi aku tidak bisa berbuat apa-apa...",
  ui_story_5045_50451301_125_dialog_content = "Saat itulah saya menemukan agen asuransi baru itu.",
  ui_story_5045_50451301_126_dialog_content = "Aku berpikir bahwa daripada menjadi beban bagi Fanny, akan lebih baik jika...",
  ui_story_5045_50451301_127_dialog_content = "Kamu bodoh! Aku tidak pernah menganggapmu sebagai beban! Tidak pernah!",
  ui_story_5045_50451301_128_dialog_content = "Itu semua karena aku terlalu serakah.",
  ui_story_5045_50451301_129_dialog_content = "Saya pikir jika saya menceraikan Fanny, saya dapat menanggung semua hutang kami.",
  ui_story_5045_50451301_130_dialog_content = "Kemudian, setelah kematian saya, hutang juga akan dihapuskan.",
  ui_story_5045_50451301_131_dialog_content = "Pada akhirnya, ternyata aku terlalu tidak berguna bahkan untuk melakukan sebanyak ini.",
  ui_story_5045_50451301_132_dialog_content = "Bacon, izinkan saya memberi tahu Anda sesuatu.",
  ui_story_5045_50451301_133_dialog_content = "Jika Anda mengakhiri hidup Anda sendiri, perusahaan asuransi akan menolak klaim tersebut.",
  ui_story_5045_50451301_134_dialog_content = "B-Benarkah!?",
  ui_story_5045_50451301_135_dialog_content = "Jika Anda melakukan hal seperti itu, Anda hanya akan meninggalkan Fanny dengan banyak hutang dan kesedihan yang tak ada habisnya.",
  ui_story_5045_50451301_136_dialog_content = "Surga, apa yang telah saya lakukan?",
  ui_story_5045_50451301_137_dialog_content = "Fany, maafkan aku! Saya minta maaf...",
  ui_story_5045_50451301_138_dialog_content = "Pada akhirnya, saya masih gagal memberi Anda kehidupan yang bahagia.",
  ui_story_5045_50451301_139_dialog_content = "Bacon, apa yang kamu bicarakan?",
  ui_story_5045_50451301_140_dialog_content = "Aku selalu bahagia bersamamu.",
  ui_story_5045_50451301_141_dialog_content = "...",
  ui_story_5045_50451301_142_dialog_content = "Ingat piring tanah liat yang kita buat sendiri?",
  ui_story_5045_50451301_143_dialog_content = "saya ingat itu <color=#1875ad>piring tanah liat</color>!",
  ui_story_5045_50451301_144_dialog_content = "PlayerName, jangan membuat ini lebih berantakan dari yang sudah ada.",
  ui_story_5045_50451301_145_dialog_content = "Maaf, tapi saya pikir...",
  ui_story_5045_50451301_146_dialog_content = "Apakah ini piring yang pecah?",
  ui_story_5045_50451301_147_dialog_content = "Aku ingat, sejak kami menikah...",
  ui_story_5045_50451301_148_dialog_content = "Uh, apakah Bacon akan mengingat kegembiraan selama bulan madu mereka di pengadilan ini?",
  ui_story_5045_50451301_149_dialog_content = "Hush!",
  ui_story_5045_50451301_150_dialog_content = "Maaf…",
  ui_story_5045_50451301_151_dialog_content = "Fanny, untuk apa kamu minta maaf?",
  ui_story_5045_50451301_152_dialog_content = "Aku ingin mengejutkanmu dengan makan malam, tapi aku tidak sengaja memecahkan piring kita...",
  ui_story_5045_50451301_153_dialog_content = "Ha ha ha! Mengapa Anda meminta maaf untuk itu?",
  ui_story_5045_50451301_154_dialog_content = "Saya bahkan tidak ingat sudah berapa lama piring itu digunakan. Sudah saatnya kita menggantinya.",
  ui_story_5045_50451301_155_dialog_content = "Tapi... kami tidak punya uang sekarang.",
  ui_story_5045_50451301_156_dialog_content = "Kita bisa membuatnya sendiri.",
  ui_story_5045_50451301_157_dialog_content = "Diri? Bagaimana?",
  ui_story_5045_50451301_158_dialog_content = "Ikuti aku!",
  ui_story_5045_50451301_159_dialog_content = "Hahaha, saya pikir Bacon bertemu dengan penjaga toko yang bisa membantu kami dengan beberapa piring.",
  ui_story_5045_50451301_160_dialog_content = "Tanpa diduga, dia membawa saya ke hutan belantara.",
  ui_story_5045_50451301_161_dialog_content = "Menunjuk tanah liat dari sungai, dia berkata dia akan melakukan sihir untukku.",
  ui_story_5045_50451301_162_dialog_content = "Kita bisa membentuk tanah liat ini menjadi bentuk apapun yang kita inginkan, lalu memanggangnya di atas api....",
  ui_story_5045_50451301_163_dialog_content = "... dan kami akan memiliki piring kami sendiri.",
  ui_story_5045_50451301_164_dialog_content = "Wow, suamiku luar biasa!",
  ui_story_5045_50451301_165_dialog_content = "Heh, meski piring ini agak jelek.",
  ui_story_5045_50451301_166_dialog_content = "Punyaku terlihat lebih buruk.",
  ui_story_5045_50451301_167_dialog_content = "Tapi ini adalah piring tanah liat unik kami! Tidak peduli seberapa besar keinginan para bangsawan itu, mereka tidak dapat memilikinya!",
  ui_story_5045_50451301_168_dialog_content = "Saat itu, kami tidak punya apa-apa, tapi kami sangat bahagia.",
  ui_story_5045_50451301_169_dialog_content = "Sekarang kami memiliki rumah sendiri, meskipun kami terlilit hutang...",
  ui_story_5045_50451301_170_dialog_content = "Tapi kita masih bisa sehat dan bahagia bersama, sesuatu yang tidak bisa dibeli oleh Nightium sebanyak apa pun!",
  ui_story_5045_50451301_171_dialog_content = "Fanny...",
  ui_story_5045_50451301_172_dialog_content = "Semuanya akan baik-baik saja.",
  ui_story_5045_50451301_173_dialog_content = "Ini adalah kebenaran yang Anda ajarkan kepada saya dan membuat saya percaya melalui tindakan Anda.",
  ui_story_5045_50451301_174_dialog_content = "Maukah kau percaya padaku kali ini, Bacon?",
  ui_story_5045_50451301_175_dialog_content = "... Iya.",
  ui_story_5045_50451301_176_dialog_content = "Tampaknya kasus ini sudah mencapai kesimpulan.",
  ui_story_5045_50451301_177_dialog_content = "<color=#737378>Bum!</color>",
  ui_story_5045_50451301_178_dialog_content = "Malam Putih di atas. Sudah waktunya untuk vonis!",
  ui_story_5045_50451301_179_dialog_content = "Pertama, Bacon dan Fanny, melalui persidangan ini, membuktikan cinta yang ada di antara mereka.",
  ui_story_5045_50451301_180_dialog_content = "Kedua, meskipun Bacon berniat melakukan penipuan asuransi, hukumannya akan lebih ringan, karena dia tidak melaksanakan rencananya dan menunjukkan ketulusan pertobatannya.",
  ui_story_5045_50451301_181_dialog_content = "Oleh karena itu, kami sampai pada penilaian berikut!",
  ui_story_5045_50451301_182_dialog_content = "Status pernikahan Bacon dan Fanny akan tetap tidak berubah.",
  ui_story_5045_50451301_183_dialog_content = "Obat yang terkumpul dari Bacon akan disita. Dia akan diminta menemui dokter secara teratur dan meminum obatnya pada hari-hari setelah kunjungan ini.",
  ui_story_5045_50451301_184_dialog_content = "<color=#737378>Bum!</color>",
  ui_story_5045_50451301_185_dialog_content = "Sidang berakhir!",
  ui_story_5045_50451401_1_dialog_content = "<color=#737378>Waktu: 14:00</color>",
  ui_story_5045_50451401_2_dialog_content = "<color=#737378>Lokasi: Lumo Hall of Justice, Kantor Divisi Percintaan</color>",
  ui_story_5045_50451401_3_dialog_content = "Hoamm—",
  ui_story_5045_50451401_4_dialog_content = "Anda bangun?",
  ui_story_5045_50451401_5_dialog_content = "Saya telah memilih beberapa ringkasan kasus. Tina, mari kita lihat kasus mana yang harus kita lihat terlebih dahulu.",
  ui_story_5045_50451401_6_dialog_content = "Tidak buruk, PlayerName.",
  ui_story_5045_50451401_7_dialog_content = "Anda sangat proaktif dalam pekerjaan Anda. Mungkin Anda harus tinggal dan menjadi asisten saya di masa depan.",
  ui_story_5045_50451401_8_dialog_content = "Eh...",
  ui_story_5045_50451401_9_dialog_content = "Yang mulia.",
  ui_story_5045_50451401_10_dialog_content = "Eh?!",
  ui_story_5045_50451401_11_dialog_content = "Daging babi asap? Dan Fanny juga? Apa yang kamu lakukan di sini?",
  ui_story_5045_50451401_12_dialog_content = "Apakah masalah lain muncul?",
  ui_story_5045_50451401_13_dialog_content = "Tidak ada yang seperti itu, Yang Mulia. Kami di sini untuk berterima kasih kepada kalian berdua.",
  ui_story_5045_50451401_14_dialog_content = "Setelah persidangan, saya seperti baru saja terbangun dari mimpi...",
  ui_story_5045_50451401_15_dialog_content = "Saya menyadari bahwa saya hampir membuat kesalahan besar, dan saya juga menyebabkan banyak masalah bagi kalian berdua.",
  ui_story_5045_50451401_16_dialog_content = "Terima kasih kembali. Merupakan kehormatan bagi kami untuk membantu Anda.",
  ui_story_5045_50451401_17_dialog_content = "Dan saya sama sekali tidak merasa Anda membawa masalah bagi kami!",
  ui_story_5045_50451401_18_dialog_content = "(Karena saya melakukan semua kerja keras...)",
  ui_story_5045_50451401_19_dialog_content = "PlayerName, apakah Anda memiliki sesuatu yang ingin Anda katakan kepada Bacon?",
  ui_story_5045_50451401_20_dialog_content = "Oh, benar, aku ingin <color=#1875ad>memberi tahu</color> kamu sesuatu...",
  ui_story_5045_50451401_21_dialog_content = "Kasusnya sudah berakhir. Mengapa Anda masih bertanya tentang ini?",
  ui_story_5045_50451401_22_dialog_content = "Raphael telah mengkhawatirkanmu.",
  ui_story_5045_50451401_23_dialog_content = "Meskipun Raphael terlihat seperti anak kecil, dan teknik perawatannya mungkin terlihat sedikit kasar...",
  ui_story_5045_50451401_24_dialog_content = "Tapi keterampilan medisnya luar biasa!",
  ui_story_5045_50451401_25_dialog_content = "Saya mengerti... Saya akan meminta maaf kepada Dr. Raphael juga.",
  ui_story_5045_50451401_26_dialog_content = "Jika dia bersedia memberi saya kesempatan lagi, saya akan menerima perawatannya.",
  ui_story_5045_50451401_27_dialog_content = "Bacon, Fanny—apa rencanamu untuk masa depan?",
  ui_story_5045_50451401_28_dialog_content = "Saya tidak yakin, tetapi kami akan mencoba melakukan kerja paruh waktu bersama terlebih dahulu dan melunasi hutang kami sedikit demi sedikit.",
  ui_story_5045_50451401_29_dialog_content = "Juga, pergi ke <color=#1875ad>kursus swadaya</color> mungkin membantu saya menemukan arah baru dalam hidup.",
  ui_story_5045_50451401_30_dialog_content = "Kedengarannya sangat membesarkan hati!",
  ui_story_5045_50451401_31_dialog_content = "Tapi ada apa dengan semua barang bawaan ini? Apakah Anda pindah rumah?",
  ui_story_5045_50451401_32_dialog_content = "Ini adalah alat tembikar kami.",
  ui_story_5045_50451401_33_dialog_content = "Kami akan pergi ke pedesaan nanti untuk membuat beberapa piring baru.",
  ui_story_5045_50451401_34_dialog_content = "Wow! Menghidupkan kembali masa lalu yang indah?",
  ui_story_5045_50451401_35_dialog_content = "Ehem... Bisa dibilang begitu.",
  ui_story_5045_50451401_36_dialog_content = "Saya harus disalahkan karena memecahkan kenang-kenangan kita yang paling berharga.",
  ui_story_5045_50451401_37_dialog_content = "Itu hanya benar bahwa saya membuat untuk itu.",
  ui_story_5045_50451401_38_dialog_content = "Itu sangat manis!",
  ui_story_5045_50451401_39_option_content = "Apakah itu sedikit kecemburuan yang saya deteksi, Tina?",
  ui_story_5045_50451401_40_dialog_content = "Hmm... Ada yang aneh dengan mengagumi indahnya cinta?",
  ui_story_5045_50451401_41_dialog_content = "Jika Yang Mulia tidak keberatan, kami akan membuat beberapa piring kecil lagi untuk kalian berdua!",
  ui_story_5045_50451401_42_dialog_content = "Kami akan menyukainya, tetapi sebagai juri, kami tidak dapat menerima hadiah dari klien kami.",
  ui_story_5045_50451401_43_dialog_content = "Piring tanah liat yang kami buat nilainya sangat kecil ...",
  ui_story_5045_50451401_44_dialog_content = "Kami menghargai kebaikan Anda, tetapi menurut saya, piring Anda tak ternilai harganya.",
  ui_story_5045_50451401_45_dialog_content = "Terima kasih, Yang Mulia... Kalau begitu, kami sudah cukup menyita waktu Anda.",
  ui_story_5045_50451401_46_dialog_content = "Huh, aku sangat berharap suatu hari nanti, kekasihku akan mengajakku melakukan sesuatu yang romantis.",
  ui_story_5045_50451401_47_dialog_content = "Tapi ini masih jam kerja, PlayerName, kembalilah bekerja...",
  ui_story_5045_50451401_47X1_dialog_content = "Sebagai mitra, ada ruang untuk kita <color=#1875ad>Hubungan</color> meningkatkan!",
  ui_story_5045_50451401_48_dialog_content = "Bagaimana denganmu?",
  ui_story_5045_50451401_49_dialog_content = "Aku perlu mengejar tidur, tentu saja. Mungkin akan ada beberapa mimpi indah yang menungguku jika aku tertidur dengan hati yang bahagia!",
  ui_story_5045_50451401_50_dialog_content = "Apa-?!",
  ui_story_5045_50451401_51_option_content = "Kita juga ikut!",
  ui_story_5045_50451401_52_dialog_content = "Hah?",
  ui_story_5045_50451401_53_dialog_content = "Ah, maaf... aku lupa ini masih jam kerja.",
  ui_story_5045_50451401_54_dialog_content = "Kalau begitu ayo berangkat!",
  ui_story_5045_50451401_55_dialog_content = "Baiklah, saya hanya akan—",
  ui_story_5045_50451401_56_dialog_content = "Hah? Dia pergi?",
  ui_story_5045_50451401_57_dialog_content = "<color=#737378>Waktu: 21:00</color>",
  ui_story_5045_50451401_58_dialog_content = "<color=#737378>Lokasi: Pinggiran Lumopolis</color>",
  ui_story_5045_50451401_59_dialog_content = "Setelah Anda siap, Anda bisa memasukkannya ke dalam api untuk memanggangnya.",
  ui_story_5045_50451401_60_dialog_content = "Tina, kamu membuat apa?",
  ui_story_5045_50451401_61_dialog_content = "Tunggu sebentar, saya akan segera menunjukkannya.",
  ui_story_5045_50451401_62_dialog_content = "Jangan khawatir tentang itu, milikku terlihat mengerikan. Aku berjanji tidak akan menertawakanmu.",
  ui_story_5045_50451401_63_dialog_content = "Saya sangat puas dengan mahakarya saya, saya hanya belum menyelesaikannya—",
  ui_story_5045_50451401_64_dialog_content = "Heh... Hahaha!",
  ui_story_5045_50451401_65_dialog_content = "A-Apa itu?",
  ui_story_5045_50451401_66_dialog_content = "PlayerName, piringmu benar-benar jelek, dan wajahmu tertutup tanah liat.",
  ui_story_5045_50451401_67_dialog_content = "Apakah Anda mencoba mengubah diri Anda menjadi patung tanah liat?",
  ui_story_5045_50451401_68_dialog_content = "B-Benarkah? Aku bahkan tidak menyadarinya...",
  ui_story_5045_50451401_69_dialog_content = "Tapi aku bisa mengatakan hal yang sama tentangmu...",
  ui_story_5045_50451401_70_dialog_content = "Apa!?",
  ui_story_5045_50451401_71_dialog_content = "Itu tidak masalah. Penampilan tidak penting selama itu untuk mahakarya saya!",
  ui_story_5045_50451401_72_dialog_content = "Benda yang kamu pegang itu adalah... mahakaryamu?",
  ui_story_5045_50451401_73_dialog_content = "Itu benar, heehee!",
  ui_story_5045_50451401_74_dialog_content = "Saya tidak mengerti... Apa yang seharusnya?",
  ui_story_5045_50451401_75_dialog_content = "Apa yang tidak bisa didapatkan? Perhatikan baik-baik...",
  ui_story_5045_50451401_76_dialog_content = "Ini laki-laki dan ini perempuan.",
  ui_story_5045_50451401_77_dialog_content = "Mereka sangat mencintai satu sama lain. Menatap mata satu sama lain dengan penuh kasih sayang, mereka ingin menawarkan ciuman termanis satu sama lain...",
  ui_story_5045_50451401_78_dialog_content = "Ahem... Saya membuat ornamen kecil ini, khusus untuk Divisi Romance.",
  ui_story_5045_50451401_79_dialog_content = "Jadi, seharusnya ada dua patung tanah liat...",
  ui_story_5045_50451401_80_dialog_content = "Kedua patung tanah liat kecil ini sangat lucu. Mengapa saya tidak berpikir untuk membuat hiasan kecil?",
  ui_story_5045_50451401_81_dialog_content = "Anda tahu, patung tanah liat kecil ini terlihat agak familiar...",
  ui_story_5045_50451401_82_dialog_content = "Haha, bukankah mereka terlihat seperti dua juri?",
  ui_story_5045_50451401_83_dialog_content = "Apa?",
  ui_story_5045_50451401_84_option_content = "Kurasa tidak.",
  ui_story_5045_50451401_85_dialog_content = "Itu benar, mereka bukan kita!",
  ui_story_5045_50451401_86_dialog_content = "Mereka hanya anak laki-laki dan perempuan acak yang saya kumpulkan dengan santai.",
  ui_story_5045_50451401_87_dialog_content = "Saya harap semua pecinta di Lumopolis akan diberkati oleh Dewa Cahaya.",
  ui_story_5045_50451401_88_dialog_content = "Setidaknya Divisi Percintaan tidak akan sesibuk sekarang...",
  ui_story_5045_50451401_89_dialog_content = "Jika kita begitu sibuk, kenapa kau mengajakku keluar untuk mengacau di pedesaan?",
  ui_story_5045_50451401_90_dialog_content = "Karena…",
  ui_story_5045_50451401_91_dialog_content = "Hah? Karena apa?",
  ui_story_5045_50451401_92_option_content = "Saya bisa melihat kemiripannya.",
  ui_story_5045_50451401_93_dialog_content = "Sungguh?",
  ui_story_5045_50451401_94_dialog_content = "Di mana!? Aku tidak melihatnya!",
  ui_story_5045_50451401_95_dialog_content = "Siapa mereka seharusnya?",
  ui_story_5045_50451401_96_dialog_content = "Tidak ada orang secara khusus.",
  ui_story_5045_50451401_97_dialog_content = "Kedua patung tanah liat ini adalah inkarnasi abstrak dari semua pecinta dunia!",
  ui_story_5045_50451401_98_dialog_content = "Saya hanya ingin semua orang mengalami cinta yang benar-benar indah.",
  ui_story_5045_50451401_99_dialog_content = "Saya berharap mereka bertahan lama, lama sekali.",
  ui_story_5045_50451401_100_dialog_content = "Tina, kamu sangat suka bekerja di Divisi Percintaan, kan...",
  ui_story_5045_50451401_101_dialog_content = "Sejujurnya, tidak masalah di mana saya bekerja.",
  ui_story_5045_50451401_102_dialog_content = "Namun, saya tidak dapat menyangkal bahwa kasus saya baru-baru ini di Divisi Percintaan benar-benar lebih menarik daripada yang pernah saya temui sebelumnya.",
  ui_story_5045_50451401_103_dialog_content = "Jika bukan karena bantuanmu...",
  ui_story_5045_50451401_104_dialog_content = "Saya mungkin tidak tahu bagaimana menangani kasus Divisi Percintaan.",
  ui_story_5045_50451401_105_dialog_content = "Mengapa kamu mengatakan itu? Anda adalah juri yang fenomenal.",
  ui_story_5045_50451401_106_dialog_content = "Tetapi pemahaman saya tentang cinta sangat kurang.",
  ui_story_5045_50451401_107_dialog_content = "Saya selalu menyukai orang tanpa alasan yang jelas, tetapi pada akhirnya, saya menyadari bahwa saya hanya menyukai kesan mereka yang telah saya bentuk dalam imajinasi saya.",
  ui_story_5045_50451401_108_dialog_content = "Sepertinya sentimen yang konyol sekarang.",
  ui_story_5045_50451401_109_dialog_content = "Cinta sejati...",
  ui_story_5045_50451401_110_dialog_content = "Ini membantu satu sama lain melalui kesulitan dan kesulitan, melawan keduniawian kehidupan.",
  ui_story_5045_50451401_111_dialog_content = "Ini adalah kebutuhan untuk menjaga satu sama lain, daripada membuat satu sama lain menyerah pada ketundukan.",
  ui_story_5045_50451401_112_dialog_content = "Benar. Kami harus berterima kasih kepada Fanny dan Bacon karena telah mengajari kami hal ini.",
  ui_story_5045_50451401_113_dialog_content = "Saya juga ingin mengucapkan terima kasih, PlayerName.",
  ui_story_5045_50451401_114_dialog_content = "Anda membantu saya melihatnya ...",
  ui_story_5045_50451401_115_dialog_content = "Hah? Melihat apa?",
  ui_story_5045_50451401_116_dialog_content = "Zzz...",
  ui_story_5045_50451401_117_dialog_content = "Dia sedang tidur?",
  ui_story_5045_50451401_118_dialog_content = "Apa itu Tina hendak katakan?",
  ui_story_5045_50451401_119_dialog_content = "Saya kira saya tidak akan mendapatkan jawaban hari ini... Selamat malam, kalau begitu.",
  ui_story_5045_50451401_120_dialog_content = "...",
  ui_story_5045_50451401_121_dialog_content = "Menurut saya Tina sedang bermimpi.",
  ui_story_5045_50451401_122_dialog_content = "PlayerName, ingatlah untuk membantu saya menyimpan mahakarya saya!",
  ui_story_5045_50451401_123_dialog_content = "B-baiklah!",
  ui_story_5045_50451401_124_dialog_content = "Hah? Apakah dia hanya berbicara dalam tidurnya?",
  ui_story_5045_50451401_125_dialog_content = "Tina benar-benar tidak bermalas-malasan ketika dia sedang bermimpi ...",
  ui_story_5045_50451501_1_dialog_content = "<color=#737378>Waktu: 15:00</color>",
  ui_story_5045_50451501_2_dialog_content = "<color=#737378>Lokasi: Lumo Hall of Justice, Kantor Divisi Percintaan</color>",
  ui_story_5045_50451501_3_dialog_content = "(Saya tidak pernah berpikir saya akan menyelesaikan kasus secepat ini.)",
  ui_story_5045_50451501_4_dialog_content = "(Kemampuan hukum saya tidak bisa lebih baik dari kemampuan psikis saya, bukan?)",
  ui_story_5045_50451501_5_dialog_content = "(Jika Irridon melihat persidangan kami, dia mungkin berpikir untuk membayar saya lebih banyak.)",
  ui_story_5045_50451501_6_dialog_content = "(Ketika saatnya tiba, heh, saya akan memberikan Vice dan yang lainnya kejutan!)",
  ui_story_5045_50451501_7_dialog_content = "(Tapi sekali lagi...)",
  ui_story_5045_50451501_8_dialog_content = "Mengapa begitu banyak orang yang mengajukan hari ini !?",
  ui_story_5045_50451501_9_dialog_content = "Hah? Kehilangan minat dalam pekerjaan percobaan begitu cepat?",
  ui_story_5045_50451501_10_dialog_content = "T-Tidak mungkin!",
  ui_story_5045_50451501_11_dialog_content = "Ah, apa yang membuat Bunda kita selalu sibuk Irridon Di Sini?",
  ui_story_5045_50451501_12_dialog_content = "Zzz...",
  ui_story_5045_50451501_13_dialog_content = "Tina, bangun!",
  ui_story_5045_50451501_14_dialog_content = "Oke…",
  ui_story_5045_50451501_15_dialog_content = "Angel, apa yang kamu tunggu? Pergi dan buatkan teh untuk ketua juri kita yang terhormat!",
  ui_story_5045_50451501_16_dialog_content = "... Oh.",
  ui_story_5045_50451501_17_dialog_content = "Tidak perlu.",
  ui_story_5045_50451501_18_dialog_content = "Saya mendengar bahwa Anda mengadili sebuah kasus pagi ini, jadi saya datang untuk menilai akibatnya.",
  ui_story_5045_50451501_19_dialog_content = "Kasus ini dilakukan oleh buku.",
  ui_story_5045_50451501_20_dialog_content = "Sebaliknya, ujian saya besok akan menginspirasi dunia dan menjadi preseden bagi generasi mendatang untuk dipelajari dan ditiru.",
  ui_story_5045_50451501_21_dialog_content = "Ketika saatnya tiba, silakan datang lagi dan saksikan sendiri.",
  ui_story_5045_50451501_22_dialog_content = "Kita lihat saja nanti. Mungkin, jika saya punya waktu.",
  ui_story_5045_50451501_23_dialog_content = "Saya baru dengar kasus tadi pagi cukup menggegerkan. Saya ingin tahu secara spesifik.",
  ui_story_5045_50451501_24_dialog_content = "Wanita Irridon, PlayerName dan saya mencoba kasus pagi ini.",
  ui_story_5045_50451501_25_dialog_content = "Detail dan proses trialnya saya catat di notebook ini. Mohon dilihat.",
  ui_story_5045_50451501_26_dialog_content = "Menakjubkan. Anda telah membentuk beberapa kebiasaan baik sejak tiba di sini, PlayerName.",
  ui_story_5045_50451501_27_dialog_content = "Apakah Anda baru saja mengatakan bahwa kasus ini menimbulkan kehebohan?",
  ui_story_5045_50451501_28_dialog_content = "Ya.",
  ui_story_5045_50451501_29_dialog_content = "Lantas, bagaimana opini publik saat ini terkait kasus ini?",
  ui_story_5045_50451501_30_dialog_content = "Bagaimana menurutmu?",
  ui_story_5045_50451501_31_dialog_content = "Yah... Saya menduga itu pasti cukup positif, bukan?",
  ui_story_5045_50451501_32_dialog_content = "PlayerName telah membuktikan dirinya layak dipilih secara pribadi oleh Anda, Hakim Ketua, untuk membantu kami di sini.",
  ui_story_5045_50451501_33_dialog_content = "Dengan bantuan PlayerName, itu wajar saja Tina harus membuat beberapa kemajuan juga.",
  ui_story_5045_50451501_34_dialog_content = "Mungkin tidak lama lagi dia akan menjadi juri terbaik kedua di Divisi Percintaan!",
  ui_story_5045_50451501_35_dialog_content = "Tina, adalah PlayerNamecatatan lengkap?",
  ui_story_5045_50451501_36_dialog_content = "Ya, saya membuat PlayerName tulis semuanya dengan detail.",
  ui_story_5045_50451501_37_dialog_content = "Investigasi hanya menggores permukaan, dan para pihak tidak diizinkan untuk sepenuhnya menjelaskan diri mereka sendiri di pengadilan ...",
  ui_story_5045_50451501_38_dialog_content = "Tina, apakah kamu pernah tidur di pengadilan?",
  ui_story_5045_50451501_39_dialog_content = "A-aku belum melakukan hal semacam itu... Menguap—",
  ui_story_5045_50451501_40_dialog_content = "Aku berjuang melawan kantuk pagi ini, jadi aku tidur sampai sekarang.",
  ui_story_5045_50451501_41_dialog_content = "Divisi Percintaan baru saja dibentuk, dan tidak ada kasus untuk kita pelajari.",
  ui_story_5045_50451501_42_dialog_content = "Saya mengerti tekanannya.",
  ui_story_5045_50451501_43_dialog_content = "Namun harap diingat bahwa kasus kecil sekalipun di mata kami dapat mempengaruhi kehidupan pihak-pihak yang berkepentingan.",
  ui_story_5045_50451501_44_dialog_content = "Cara Anda menangani setiap kasus akan memengaruhi sikap masyarakat Lumopolis terhadap hubungan romantis di masa depan.",
  ui_story_5045_50451501_45_dialog_content = "Tampaknya opini publik sebagai akibat dari mengangkat kasus ini pagi ini tidak terlalu baik...",
  ui_story_5045_50451501_46_dialog_content = "Mereka yang menganjurkan kebebasan dalam cinta dan pernikahan sangat tidak puas dengan persidangan pagi ini.",
  ui_story_5045_50451501_47_dialog_content = "Kami mungkin melihat banding pembalasan terhadap Hall of Justice dalam waktu dekat.",
  ui_story_5045_50451501_48_dialog_content = "Persiapkan dirimu.",
  ui_story_5045_50451501_49_dialog_content = "Banding pembalasan?",
  ui_story_5045_50451501_50_dialog_content = "Kita bahkan mungkin melihat orang sengaja menikah dan kemudian menuntut cerai.",
  ui_story_5045_50451501_51_dialog_content = "Karena Tina-lah yang mengaduk semua masalah ini, biarlah Tina menangani banding seperti itu sendiri.",
  ui_story_5045_50451501_52_dialog_content = "Zzz...",
  ui_story_5045_50451501_53_dialog_content = "Sepertinya Tina menyetujui.",
  ui_story_5045_50451501_54_dialog_content = "Hah? T-Tunggu...",
  ui_story_5045_50451501_55_dialog_content = "Jadi, pada dasarnya, saya harus menangani semua kasus perceraian yang masuk ke sini?",
  ui_story_5045_50451501_56_dialog_content = "Berapa banyak sesi yang diperlukan untuk menyelesaikan setiap percobaan?",
  ui_story_5045_50451601_1_dialog_content = "<color=#737378>Waktu: 15:00</color>",
  ui_story_5045_50451601_2_dialog_content = "<color=#737378>Lokasi: Balai Kehakiman Lumo, Ruang Sidang</color>",
  ui_story_5045_50451601_3_dialog_content = "<color=#737378>Bum!</color>",
  ui_story_5045_50451601_4_dialog_content = "<size=45>Pengadilan sedang berlangsung!</size>",
  ui_story_5045_50451601_5_dialog_content = "Pertama-tama, mari kita dengar apa yang dikatakan penggugat.",
  ui_story_5045_50451601_6_dialog_content = "Hmm? Dan siapa Anda?",
  ui_story_5045_50451601_7_dialog_content = "Dapatkah Anda benar-benar melakukan pekerjaan yang baik untuk mencoba kasus saya?",
  ui_story_5045_50451601_8_dialog_content = "Memesan!",
  ui_story_5045_50451601_9_dialog_content = "Tolong jangan ajukan pertanyaan yang tidak relevan dengan kasus ini.",
  ui_story_5045_50451601_10_dialog_content = "Kelalaian seperti itu!",
  ui_story_5045_50451601_11_dialog_content = "Apakah Anda tahu siapa saya? Di mana hakim kecil yang menyedihkan sepertimu berhak berbicara seperti itu padaku?",
  ui_story_5045_50451601_12_dialog_content = "Saya harus melaporkan Anda ke Irridon!",
  ui_story_5045_50451601_13_dialog_content = "Saya seorang hakim percobaan, ditunjuk secara pribadi oleh Ketua Hakim Irridon.",
  ui_story_5045_50451601_14_dialog_content = "Mohon kerjasamanya dalam menjaga ketertiban di Balai Kehakiman.",
  ui_story_5045_50451601_15_dialog_content = "Hmph! Tunggu saja!",
  ui_story_5045_50451601_16_dialog_content = "Hah? Penggugat, mau kemana?",
  ui_story_5045_50451601_17_dialog_content = "<color=#737378>Waktu: 16:00</color>",
  ui_story_5045_50451601_18_dialog_content = "<color=#737378>Lokasi: Balai Kehakiman Lumo</color>",
  ui_story_5045_50451601_19_dialog_content = "Wanita Irridon, Anda telah mencari saya?",
  ui_story_5045_50451601_20_dialog_content = "PlayerName, apakah Anda mengetahui bahwa seseorang telah mengajukan keluhan terhadap Anda?",
  ui_story_5045_50451601_21_dialog_content = "Hah? Apa pria itu benar-benar mengeluh tentangku barusan?",
  ui_story_5045_50451601_22_dialog_content = "Tapi saya tidak berpikir saya telah mengatakan sesuatu yang salah. Dia sama sekali tidak menghormati perintah Balai Kehakiman!",
  ui_story_5045_50451601_23_dialog_content = "Dia punya masalah. Secara alami, ini adalah sesuatu yang saya pahami dengan sangat baik.",
  ui_story_5045_50451601_24_dialog_content = "Tapi, kamu...",
  ui_story_5045_50451601_25_dialog_content = "Saya meminta Anda untuk pergi ke Divisi Percintaan untuk membantu, tetapi saya tidak memberi Anda izin untuk mendengar kasus sendiri.",
  ui_story_5045_50451601_26_dialog_content = "Saya rasa itu tidak sulit, jadi mungkin, mungkin saya bisa...",
  ui_story_5045_50451601_27_dialog_content = "Bahkan jika semudah itu untuk menjadi hakim sejati Angel akan lulus ujian sidang pura-pura.",
  ui_story_5045_50451601_28_dialog_content = "Saya akui bahwa Anda memiliki hadiah.",
  ui_story_5045_50451601_29_dialog_content = "Namun bukan berarti Anda bisa melewati tahap pembelajaran dan langsung menjadi juri.",
  ui_story_5045_50451601_30_dialog_content = "Bahkan seorang jenius yang lahir dalam keluarga hakim harus memulai sebagai asisten hakim.",
  ui_story_5045_50451601_31_dialog_content = "Maaf…",
  ui_story_5045_50451601_32_dialog_content = "aku mengerti. Saya akan kembali dan bekerja lebih keras sebagai asisten sekarang!",
  ui_story_5045_50451601_33_dialog_content = "...",
  ui_story_5045_50451601_34_dialog_content = "Tidak perlu untuk itu.",
  ui_story_5045_50451601_35_dialog_content = "Sungguh?",
  ui_story_5045_50451601_36_dialog_content = "Untuk mencegah masalah ini memfermentasi ke titik di mana publik salah memahami niat Balai Kehakiman ...",
  ui_story_5045_50451601_37_dialog_content = "Aku sangat menyesal, PlayerName, tetapi Anda tidak dapat lagi bekerja di Hall of Justice.",
  ui_story_5045_50451601_38_dialog_content = "Nah, lalu bagaimana dengan pembayaran saya...?",
  ui_story_5045_50451601_39_dialog_content = "Balai Kehakiman harus membayar sejumlah besar uang untuk menenangkan pengadu barusan.",
  ui_story_5045_50451601_40_dialog_content = "Pembayaran Anda jauh dari cukup bahkan untuk menutupi kompensasi ini.",
  ui_story_5045_50451601_41_dialog_content = "Tetapi karena saya memiliki tanggung jawab sendiri untuk menanggung masalah ini, saya tidak akan meminta Anda untuk membayar biaya tambahan apa pun untuk kompensasi tersebut.",
  ui_story_5045_50451601_42_dialog_content = "Jika Anda bersedia menghadiri salah satu persidangan di sini, pintu Aula Kehakiman masih terbuka untuk Anda.",
  ui_story_5045_50451601_43_dialog_content = "Hmm…",
  ui_story_5045_50451601_44_dialog_content = "M-Pembayaran saya...",
  ui_story_5045_50451601_45_dialog_content = "Jika saya tahu ini akan terjadi, saya akan menjadi asisten mereka dan tidak lebih!",
  ui_story_5045_50451601_46_dialog_content = "Dan untuk buku catatan ini... Saya khawatir Anda tidak dapat menyimpannya.",
  ui_story_5045_50451601_47_dialog_content = "Saya mengambil kebebasan untuk mengambilnya, karena saya sudah di sini.",
  ui_story_5045_50451601_48_dialog_content = "Wanita Irridon, j-jangan pergi...",
  ui_story_5045_50451601_49_dialog_content = "Kali ini...",
  ui_story_5045_50451601_50_dialog_content = "Aku benar-benar kacau kali ini...",
  ui_story_5045_50451701_1_dialog_content = "<color=#737378>Waktu: 08:00</color>",
  ui_story_5045_50451701_2_dialog_content = "<color=#737378>Lokasi: Lumo Hall of Justice, Kantor Divisi Percintaan</color>",
  ui_story_5045_50451701_3_dialog_content = "Pernikahan harus diatur oleh keluarga. Ini adalah tanggung jawab bangsawan!",
  ui_story_5045_50451701_4_dialog_content = "Jika keluarga Anda mengatur agar Anda menikah dengan istri jorok yang menolak untuk mandi, apakah Anda akan menerima nasib Anda?",
  ui_story_5045_50451701_5_dialog_content = "Saya percaya bahwa keluarga saya tidak akan pernah menemukan istri seperti itu untuk saya.",
  ui_story_5045_50451701_6_dialog_content = "Tapi Anda tidak bisa memastikannya.",
  ui_story_5045_50451701_7_dialog_content = "Pada akhirnya, Anda semua hanya ingin memaksimalkan kepentingan dan harta Anda dan tidak peduli dengan perasaan pihak yang bersangkutan!",
  ui_story_5045_50451701_8_dialog_content = "Saya hakim yang memimpin kasus ini! Setiap orang harus menghormati penilaian saya!",
  ui_story_5045_50451701_9_dialog_content = "Jika penilaian Anda salah, saya akan menjadi orang yang dimarahi seperti Anda ...",
  ui_story_5045_50451701_10_dialog_content = "Ada apa dengan Matthieu Dan Angel?",
  ui_story_5045_50451701_11_dialog_content = "Jelas, mereka tidak dapat menyetujui kasus yang saat ini sedang disidangkan.",
  ui_story_5045_50451701_12_dialog_content = "Mengapa mereka masih berkelahi? Beberapa orang mencoba untuk tidur di sini—Menguap—",
  ui_story_5045_50451701_13_dialog_content = "Kecuali seseorang melakukan sesuatu tentang ini, mereka akan terus berjuang sampai matahari terbenam...",
  ui_story_5045_50451701_14_dialog_content = "Bagaimana kalau kita bertanya apa yang terjadi? Mungkin kami bisa membantu.",
  ui_story_5045_50451701_15_dialog_content = "Jika Anda mengatakan demikian, PlayerName...",
  ui_story_5045_50451701_16_dialog_content = "Yah, kita tidak bisa hanya duduk dan tidak melakukan apa-apa.",
  ui_story_5045_50451701_17_dialog_content = "Jadi... Matthieu, Angel, apa masalahnya?",
  ui_story_5045_50451701_18_dialog_content = "Anda tepat waktu. Tolong dengarkan saya dan beri tahu saya jika penilaian saya masuk akal.",
  ui_story_5045_50451701_19_dialog_content = "Satu-satunya putri seorang bangsawan agung menggugat orang tuanya, mengklaim bahwa mereka telah mengganggu kebebasannya untuk mencintai.",
  ui_story_5045_50451701_20_dialog_content = "Saya merasa kasusnya tidak sesederhana kelihatannya, jadi saya bawa Angel untuk mengunjungi mereka dan mengumpulkan bukti.",
  ui_story_5045_50451701_21_dialog_content = "Ternyata anak perempuan satu-satunya telah jatuh cinta dengan seorang anak laki-laki miskin yang bahkan tidak memiliki pekerjaan yang layak.",
  ui_story_5045_50451701_22_dialog_content = "Tidak, orang tua bangsawan itulah yang dengan sengaja membuatnya kehilangan pekerjaannya! Dulu dia jago masak.",
  ui_story_5045_50451701_23_dialog_content = "Bukankah kami mengkonfirmasi ini melalui penyelidikan kami?",
  ui_story_5045_50451701_24_dialog_content = "Tapi dia orang biasa. Tidak mungkin dia mendekati seorang gadis bangsawan tanpa niat lain!",
  ui_story_5045_50451701_25_dialog_content = "Saya tidak setuju!",
  ui_story_5045_50451701_26_dialog_content = "Gadis bangsawan ini rela menyerahkan semua kekayaannya untuknya...",
  ui_story_5045_50451701_27_dialog_content = "Dia juga ingin berhenti mengejarnya agar tidak membahayakan masa depan gadis bangsawan itu.",
  ui_story_5045_50451701_28_dialog_content = "Ini adalah cinta yang murni.",
  ui_story_5045_50451701_29_dialog_content = "Seperti yang Anda katakan, bocah malang itu akhirnya menyadari jarak antara keadaan mereka dan bersedia melepaskan hubungan ini.",
  ui_story_5045_50451701_30_dialog_content = "Jadi saya menilai bahwa orang tua yang mulia itu benar. Apakah ada masalah dengan ini?",
  ui_story_5045_50451701_31_dialog_content = "Kedengarannya sangat rumit ...",
  ui_story_5045_50451701_32_dialog_content = "Hah? Apa ini di tanah?",
  ui_story_5045_50451701_33_dialog_content = "Saya pikir saya pernah melihat ini di suatu tempat sebelumnya?",
  ui_story_5045_50451701_34_dialog_content = "Ah, kurasa tidak. Tapi aku ingat...",
  ui_story_5045_50451701_35_dialog_content = "Saya ingat setelah penyelidikan, saya pasti mengembalikan ini ke Sophie...",
  ui_story_5045_50451701_36_dialog_content = "Seharusnya aku tidak menyadarinya sebelumnya, tapi ini <color=#1875ad>kartu kehadiran</color> identik dengan Bacon!",
  ui_story_5045_50451701_37_dialog_content = "Saya pasti mengembalikan ini ke Bacon setelah penyelidikan...",
  ui_story_5045_50451701_38_dialog_content = "Seharusnya aku tidak menyadarinya sebelumnya, tapi ini <color=#1875ad>kartu kehadiran</color> identik dengan Sophie!",
  ui_story_5045_50451701_39_dialog_content = "Namun…",
  ui_story_5045_50451701_40_dialog_content = "Maaf, ini bukti yang baru saya temukan! Saya tidak memperhatikan salah satu dari mereka sebelumnya ...",
  ui_story_5045_50451701_41_dialog_content = "Terima kasih, PlayerName. Jika seseorang kebetulan mengambilnya, akan sulit untuk dijelaskan.",
  ui_story_5045_50451701_42_dialog_content = "Angel, Anda sebaiknya menyelesaikan pekerjaan Anda dan kemudian kita akan membahas bagaimana menilai kasus ini.",
  ui_story_5045_50451701_43_dialog_content = "...",
  ui_story_5045_50451701_44_dialog_content = "Angel, ini kartu absen siapa?",
  ui_story_5045_50451701_45_dialog_content = "Eh? Kamu baik! Hanya sekali melihat dan Anda tahu itu adalah kartu absensi?",
  ui_story_5045_50451701_46_dialog_content = "Inilah yang kami temukan di <color=#1875ad>karl</color>rumah. Menurutnya, dia belajar hukum dalam kursus swadaya ini...",
  ui_story_5045_50451701_47_dialog_content = "Sepertinya dia ingin mengubah situasinya saat ini dan berusaha menjadi hakim.",
  ui_story_5045_50451701_48_dialog_content = "Tidak, ada sesuatu yang tidak beres di sini...",
  ui_story_5045_50451701_49_dialog_content = "Ini sebuah kartu... Sepertinya semacam kartu kehadiran.",
  ui_story_5045_50451701_50_dialog_content = "Oh ya. Saya mulai mengambil beberapa pelajaran tata graha baru-baru ini.",
  ui_story_5045_50451701_51_dialog_content = "Hah? Apa kartu ini di atas meja ini?",
  ui_story_5045_50451701_52_dialog_content = "... Itu dari <color=#1875ad>kursus swadaya</color>. Itu adalah kartu kehadiran.",
  ui_story_5045_50451701_53_dialog_content = "Mereka membantu orang mengembangkan kemauan mereka sehingga mereka tidak lagi takut menghadapi kesulitan hidup.",
  ui_story_5045_50451701_54_dialog_content = "Saya mendengar bahwa banyak siswa yang mengikuti kursus ini telah menjadi jutawan terbaru Lumopolis.",
  ui_story_5045_50451701_55_dialog_content = "Mengapa kursus yang dibicarakan semua orang berbeda?",
  ui_story_5045_50451701_56_dialog_content = "Jangan-jangan...?",
  ui_story_5045_50451701_57_dialog_content = "<size=45>!!!</size>",
  ui_story_5045_50451701_58_dialog_content = "Matthieu, nama anak laki-laki malang yang dicintai gadis bangsawan dalam kasusmu...",
  ui_story_5045_50451701_59_dialog_content = "Dia dipanggil Karl. Oh sungguh, kenapa aku harus disuruh menyebut nama orang biasa?",
  ui_story_5045_50451701_60_dialog_content = "Saya pikir saya pernah bertemu <color=#1875ad>karl</color> di suatu tempat sebelumnya...",
  ui_story_5045_50451701_61_dialog_content = "Bukan itu! Aku ingat...",
  ui_story_5045_50451701_62_dialog_content = "Saya ingat tetangga Sophie bernama Karl!",
  ui_story_5045_50451701_63_dialog_content = "Dan teman Bacon dan Fanny juga dipanggil Karl...",
  ui_story_5045_50451701_64_dialog_content = "Aku ingat! Karl adalah nama teman Bacon dan Fanny!",
  ui_story_5045_50451701_65_dialog_content = "Dan saya pikir tetangga Sophie juga bernama Karl...",
  ui_story_5045_50451701_66_dialog_content = "Bisakah itu hanya kebetulan?",
  ui_story_5045_50451701_67_dialog_content = "PlayerName, apa yang baru saja kamu gumamkan pada dirimu sendiri?",
  ui_story_5045_50451701_68_dialog_content = "Kami benar-benar tidak dapat membantu dengan kasus Matthieu.",
  ui_story_5045_50451701_69_dialog_content = "Mari kita coba menangani kasus yang menjadi tanggung jawab kita saat ini.",
  ui_story_5045_50451701_70_dialog_content = "PlayerName, siapa yang akan kamu bantu kali ini?",
  ui_story_5045_50451701_71_dialog_content = "Mengapa kita tidak membiarkan PlayerName bergiliran membantu kami, seperti kemarin?",
  ui_story_5045_50451701_72_dialog_content = "Itu akan adil, bukan?",
  ui_story_5045_50451701_73_dialog_content = "Maaf, saya ingin keluar sebentar untuk menyelidiki sesuatu...",
  ui_story_5045_50451701_74_dialog_content = "Hah? Jika Anda tidak menyelidiki kasusnya, apa sebenarnya yang Anda selidiki?",
  ui_story_5045_50451701_75_dialog_content = "Ini tentang kursus swadaya ... Mungkin bukan apa-apa, mudah-mudahan saya hanya terlalu banyak berpikir.",
  ui_story_5045_50451701_76_dialog_content = "<color=#737378>Waktu: 09:00</color>",
  ui_story_5045_50451701_77_dialog_content = "<color=#737378>Lokasi: Lumopolis, Lumopolis Bawah</color>",
  ui_story_5045_50451701_78_dialog_content = "Karl!",
  ui_story_5045_50451701_79_dialog_content = "Hah? Anda...",
  ui_story_5045_50451701_80_dialog_content = "Apakah kamu tidak ingat saya? Saya asisten juri, PlayerName.",
  ui_story_5045_50451701_81_dialog_content = "Kami pernah bertemu dua kali sebelumnya.",
  ui_story_5045_50451701_82_dialog_content = "Oh, Yang Mulia! Apa yang bisa saya lakukan untuk Anda?",
  ui_story_5045_50451701_83_dialog_content = "Ya, sebenarnya—apakah Anda tahu di mana saya dapat menemukan kursus swadaya itu?",
  ui_story_5045_50451701_84_dialog_content = "Mana aku tahu?",
  ui_story_5045_50451701_85_dialog_content = "Karena Fanny bilang kau mengenalkannya, jadi kupikir kau mungkin tahu sesuatu tentang itu.",
  ui_story_5045_50451701_86_dialog_content = "Jadi, begitulah—seseorang baru saja menyebutkannya kepada saya.",
  ui_story_5045_50451701_87_dialog_content = "Saya pikir itu mungkin hanya tempat yang menjual ketenangan pikiran kepada orang-orang yang putus asa.",
  ui_story_5045_50451701_88_dialog_content = "Tetapi bagi orang-orang yang merasa putus asa tentang hidup mereka, ketenangan pikiran adalah kekurangan mereka.",
  ui_story_5045_50451701_89_dialog_content = "... Jadi begitu. Apakah ada hal lain yang bisa Anda ceritakan kepada saya?",
  ui_story_5045_50451701_90_dialog_content = "Maaf, hanya itu yang saya tahu.",
  ui_story_5045_50451701_91_dialog_content = "Baiklah, terima kasih atas waktunya.",
  ui_story_5045_50451701_92_dialog_content = "Aku akan pergi kalau begitu. Semua yang terbaik.",
  ui_story_5045_50451701_93_dialog_content = "(Pasti ada sesuatu yang aneh tentang Karl ini.)",
  ui_story_5045_50451701_94_dialog_content = "(Sebaiknya aku mengikutinya dan melihat ke mana dia pergi. Mungkin aku akan menemukan beberapa petunjuk lagi.)",
  ui_story_5045_50451701_95_dialog_content = "(Tapi…)",
  ui_story_5045_50451701_96_dialog_content = "Kemana dia pergi? Dia menghilang begitu saja dalam sekejap mata seperti itu!",
  ui_story_5045_50451701_97_dialog_content = "<color=#737378>Suatu saat, Di suatu tempat</color>",
  ui_story_5045_50451701_98_dialog_content = "Untuk apa kau berdiri seperti obat bius? Pergi temukan targetmu.",
  ui_story_5045_50451701_99_dialog_content = "T-Tapi aku...",
  ui_story_5045_50451701_100_dialog_content = "Saya tidak ingin melakukan ini!",
  ui_story_5045_50451701_101_dialog_content = "Maaf, Guru Swadaya, maafkan saya!",
  ui_story_5045_50451701_102_dialog_content = "Tidak apa-apa, aku tidak memaksamu.",
  ui_story_5045_50451701_103_dialog_content = "Jadi... bisakah aku pulang?",
  ui_story_5045_50451701_104_dialog_content = "Tunggu. Tidak terlalu cepat.",
  ui_story_5045_50451701_105_dialog_content = "Meskipun Anda baru berada di sini setengah hari, pasti Anda dapat melakukan satu hal lagi untuk saya?",
  ui_story_5045_50451701_106_dialog_content = "Kalau tidak, istri Anda mungkin akan marah.",
  ui_story_5045_50451801_1_dialog_content = "<color=#737378>Waktu: 16:00</color>",
  ui_story_5045_50451801_2_dialog_content = "<color=#737378>Lokasi: Lumo Hall of Justice, Kantor Divisi Percintaan</color>",
  ui_story_5045_50451801_3_dialog_content = "Sudah kembali, PlayerName?",
  ui_story_5045_50451801_4_dialog_content = "Bagaimana penyelidikan Anda?",
  ui_story_5045_50451801_5_dialog_content = "Petunjuknya adalah jalan buntu, tapi aku masih tidak bisa menghilangkan perasaan tidak nyaman ini.",
  ui_story_5045_50451801_6_dialog_content = "Ngomong-ngomong, di mana Matthieu Dan Angel?",
  ui_story_5045_50451801_7_dialog_content = "Kelihatannya Matthieu ingin meletakkan kasus ini di belakang kompor.",
  ui_story_5045_50451801_8_dialog_content = "Angel pergi bersama Matthieu untuk menyelidiki kasus lain. Jangan khawatir tentang mereka — Anda sebaiknya memikirkan ...",
  ui_story_5045_50451801_9_dialog_content = "Siapa yang Anda rencanakan untuk membantu hari ini?",
  ui_story_5045_50451801_10_dialog_content = "Aku…",
  ui_story_5045_50451801_11_dialog_content = "Permisi, adalah PlayerName Di Sini?",
  ui_story_5045_50451801_12_dialog_content = "Amy? Apakah ada yang bisa saya bantu?",
  ui_story_5045_50451801_13_dialog_content = "Aku... aku di sini untuk <color=#1875ad>menangkap</color> Anda!",
  ui_story_5045_50451801_14_dialog_content = "Tangkap saya!? Untuk apa?",
  ui_story_5045_50451801_15_dialog_content = "Seseorang melaporkan Anda ke Mahkamah Agung, mengatakan bahwa Anda membuat organisasi ilegal di Lumopolis yang berspesialisasi dalam melakukan penipuan.",
  ui_story_5045_50451801_16_dialog_content = "Karena ruang lingkup dugaan penipuan sangat luas dan sifatnya sangat parah...",
  ui_story_5045_50451801_17_dialog_content = "Hall of Justice telah memutuskan untuk menangkap Anda dan memulai persidangan besok!",
  ui_story_5045_50451801_18_dialog_content = "Ini pasti sebuah kesalahan, bukan?",
  ui_story_5045_50451801_19_dialog_content = "PlayerName telah membantu kami dengan pekerjaan kami tanpa henti akhir-akhir ini.",
  ui_story_5045_50451801_20_dialog_content = "Tidak ada kesalahan. Penggugat mengatakan bahwa tergugat adalah seorang Caelestite yang bekerja di Hall of Justice.",
  ui_story_5045_50451801_21_dialog_content = "Kecuali aku salah, kau satu-satunya Caelestite di sekitar sini.",
  ui_story_5045_50451801_22_dialog_content = "Um…",
  ui_story_5045_50451801_23_dialog_content = "<color=#737378>Waktu: 09:00, Hari Berikutnya</color>",
  ui_story_5045_50451801_24_dialog_content = "<color=#737378>Tempat: Balai Kehakiman Lumo, Ruang Sidang Utama</color>",
  ui_story_5045_50451801_25_dialog_content = "(Galeri Hall of Justice penuh dengan penonton yang berbisik-bisik.)",
  ui_story_5045_50451801_26_dialog_content = "(Gelombang mata jijik terlihat seperti akan mencabik-cabikku.)",
  ui_story_5045_50451801_27_dialog_content = "(Beberapa hari yang lalu, saya masih menjadi juri trainee yang duduk di bangku, tapi hari ini...)",
  ui_story_5045_50451801_28_dialog_content = "(Leyn, Tina... Mereka tidak datang?)",
  ui_story_5045_50451801_29_dialog_content = "<color=#737378>Bum!</color>",
  ui_story_5045_50451801_30_dialog_content = "<size=45>Malam Putih di atas. Pengadilan sekarang dalam sesi!</size>",
  ui_story_5045_50451801_31_dialog_content = "Demi White Night.",
  ui_story_5045_50451801_32_option_content = "Demi White Night…",
  ui_story_5045_50451801_33_dialog_content = "Aku tidak percaya dia benar-benar mengatakannya! Beraninya dia!",
  ui_story_5045_50451801_34_option_content = "Aku sudah diatur!",
  ui_story_5045_50451801_35_dialog_content = "<color=#737378>Bum!</color>",
  ui_story_5045_50451801_36_dialog_content = "Terdakwa diminta untuk mentaati peraturan dan tata tertib pengadilan.",
  ui_story_5045_50451801_37_dialog_content = "Harap perhatikan bahwa Anda akan kehilangan kesempatan untuk membela diri setelah menerima tiga peringatan.",
  ui_story_5045_50451801_38_dialog_content = "(Aku tahu aturannya... Kenapa aku tiba-tiba lupa diri barusan!?)",
  ui_story_5045_50451801_39_option_content = "Keberatan!",
  ui_story_5045_50451801_40_dialog_content = "PlayerName, Anda telah bekerja di Hall of Justice selama beberapa waktu sekarang.",
  ui_story_5045_50451801_41_dialog_content = "Apakah Anda masih membutuhkan saya untuk mengajari Anda tentang proses dan tindakan disipliner yang dipraktikkan di Balai Kehakiman ini?",
  ui_story_5045_50451801_42_dialog_content = "(Aku ingat tindakan disipliner, tapi tiba-tiba menjadi terdakwa... Siapa yang tidak akan bingung...?)",
  ui_story_5045_50451801_43_dialog_content = "Sekarang, mari kita undang penggugat <color=#1875ad>Daging babi asap</color> berbicara.",
  ui_story_5045_50451801_44_dialog_content = "Yang Mulia, saya Bacon.",
  ui_story_5045_50451801_45_dialog_content = "(Ini Bacon?!? Apakah dia tidak senang dengan keputusan itu Tina dan saya mencapai terakhir kali?)",
  ui_story_5045_50451801_46_dialog_content = "(Tapi setelah persidangan, kami pergi ke pedesaan bersama. Semuanya baik-baik saja.)",
  ui_story_5045_50451801_47_dialog_content = "Hari ini, saya... ingin menuntut PlayerName atas nama ribuan korban di Lumopolis.",
  ui_story_5045_50451801_48_dialog_content = "Alasan untuk ini adalah...",
  ui_story_5045_50451801_49_dialog_content = "Miliknya <color=#1875ad>kursus swadaya</color> seharusnya merupakan program pelatihan yang mengajarkan keterampilan kepada orang-orang yang membutuhkan.",
  ui_story_5045_50451801_50_dialog_content = "Sebenarnya, semua yang dia ajarkan kepada murid-muridnya...",
  ui_story_5045_50451801_51_dialog_content = "... adalah bagaimana memanipulasi emosi orang untuk memeras orang kaya!",
  ui_story_5045_50451801_52_dialog_content = "<size=45>Apa!?</size>",
  ui_story_5045_50451801_53_dialog_content = "Saya tidak percaya ada kotoran seperti itu di Lumopolis!",
  ui_story_5045_50451801_54_dialog_content = "Bajingan ini entah bagaimana menyelinap ke Lumopolis!",
  ui_story_5045_50451801_55_dialog_content = "PlayerName, apakah Anda mengakui dakwaan penggugat terhadap Anda?",
  ui_story_5045_50451801_56_dialog_content = "Saya tidak melakukan hal seperti itu, dan saya bahkan tidak tahu di mana kursus swadaya ini!",
  ui_story_5045_50451801_57_dialog_content = "Bacon, apakah seseorang menyuruhmu datang ke sini dan melakukan ini?",
  ui_story_5045_50451801_58_dialog_content = "Eh, aku...",
  ui_story_5045_50451801_59_dialog_content = "Tidak!",
  ui_story_5045_50451801_60_dialog_content = "<color=#737378>Bum!</color>",
  ui_story_5045_50451801_61_dialog_content = "Tergugat diminta untuk tidak menyesatkan penggugat.",
  ui_story_5045_50451801_62_dialog_content = "(Tapi Bacon jelas terlihat khawatir tentang sesuatu.)",
  ui_story_5045_50451801_63_dialog_content = "(Saya ditangkap setelah mencari Karl kemarin... Ini tidak mungkin kebetulan!)",
  ui_story_5045_50451801_64_dialog_content = "Penggugat, Anda mengatakan bahwa Anda memiliki dua saksi yang dapat membuktikan semua yang Anda klaim sejauh ini.",
  ui_story_5045_50451801_65_dialog_content = "Betul, Yang Mulia.",
  ui_story_5045_50451801_66_dialog_content = "Saya minta itu dulu <color=#1875ad>saksi</color> menjadi saksi!",
  ui_story_5045_50451801_67_dialog_content = "Demi White Night.",
  ui_story_5045_50451801_68_dialog_content = "(Sophie!?)",
  ui_story_5045_50451801_69_dialog_content = "(Yah, wah... Seperti yang kupikirkan.)",
  ui_story_5045_50451801_70_option_content = "Keberatan!",
  ui_story_5045_50451801_71_dialog_content = "<color=#737378>Bum!</color>",
  ui_story_5045_50451801_72_dialog_content = "Sekarang saatnya bagi Sophie untuk berbicara. Terdakwa diminta untuk mentaati peraturan dan tata tertib pengadilan.",
  ui_story_5045_50451801_73_dialog_content = "Bukankah saya baru saja memberi tahu Anda bahwa Anda akan kehilangan kesempatan untuk membela diri setelah menerima tiga peringatan?",
  ui_story_5045_50451801_74_dialog_content = "(Oh ... aku tidak bisa membiarkan sarafku menjadi lebih baik dariku!)",
  ui_story_5045_50451801_75_dialog_content = "(Satu peringatan lagi dan saya selesai!)",
  ui_story_5045_50451801_76_option_content = "(Tetap diam)",
  ui_story_5045_50451801_77_dialog_content = "(Saya ingin mendengar apa yang akan dia katakan.)",
  ui_story_5045_50451801_78_dialog_content = "Yang Mulia, nama saya Sophie. Saya dapat membuktikan bahwa apa yang Bacon katakan itu benar.",
  ui_story_5045_50451801_79_dialog_content = "Saya salah satu siswa paling awal dari kursus swadaya ini.",
  ui_story_5045_50451801_80_dialog_content = "PlayerName memberitahuku bahwa dia adalah Caelestite terakhir dan tahu bagaimana memanipulasi pikiran orang.",
  ui_story_5045_50451801_81_dialog_content = "Kami para siswa memujanya sebagai Guru Swadaya.",
  ui_story_5045_50451801_82_dialog_content = "Tapi dia menggunakan intimidasi, paksaan, dan cara lain untuk membuat kami keluar, memanipulasi emosi orang, dan merampok uang mereka.",
  ui_story_5045_50451801_83_dialog_content = "Kami tidak diizinkan menyimpan uang yang kami tipu dari orang-orang, dan kami harus menyerahkan semuanya kepadanya.",
  ui_story_5045_50451801_84_dialog_content = "Dengan kata lain, Anda mengakui bahwa Anda juga terlibat dalam pemerasan kekayaan secara ilegal?",
  ui_story_5045_50451801_85_dialog_content = "Ya.",
  ui_story_5045_50451801_86_dialog_content = "Ini berarti Anda akan diadili sesuai dengan itu. Apakah kamu mengerti?",
  ui_story_5045_50451801_87_dialog_content = "Saya mengerti, tetapi hati nurani saya tidak tahan lagi. Saya tidak ingin lebih banyak orang menderita.",
  ui_story_5045_50451801_88_dialog_content = "Daripada terus mengacaukan sisa hidup saya, saya berharap untuk membela sesuatu yang berharga, sekali ini saja.",
  ui_story_5045_50451801_89_dialog_content = "(Sophie terdengar sangat tulus... Jika dia tidak menuduhku, aku akan percaya!)",
  ui_story_5045_50451801_90_dialog_content = "PlayerName, apakah Anda memiliki sesuatu untuk dikatakan?",
  ui_story_5045_50451801_91_dialog_content = "(Apakah ada bukti untuk membuktikan itu <color=#1875ad>apa yang dikatakan Sophie salah</color>...)",
  ui_story_5045_50451801_92_dialog_content = "Apa yang Anda maksud dengan ini?",
  ui_story_5045_50451801_93_dialog_content = "(Oh, tidak! Bukan?)",
  ui_story_5045_50451801_94_dialog_content = "Wanita Irridon! Ini buku catatan hakim yang kau berikan padaku?",
  ui_story_5045_50451801_95_dialog_content = "Hmm? Meskipun Anda masih memiliki buku catatan hakim, Anda sekarang menjadi terdakwa di Balai Kehakiman.",
  ui_story_5045_50451801_96_dialog_content = "Notebook ini tidak akan membantu Anda.",
  ui_story_5045_50451801_97_dialog_content = "Saya dapat bersumpah di buku catatan hakim ini bahwa saya bukan Guru Swadaya yang dia buat untuk saya!",
  ui_story_5045_50451801_98_dialog_content = "Maaf, PlayerName.",
  ui_story_5045_50451801_99_dialog_content = "Jika sumpah seperti itu ada gunanya, tidak perlu ada Balai Kehakiman.",
  ui_story_5045_50451801_100_dialog_content = "(Itu juga tidak akan berhasil?)",
  ui_story_5045_50451801_101_dialog_content = "Yang Mulia, Sophie pernah memalsukan bukti selama persidangan!",
  ui_story_5045_50451801_102_dialog_content = "Benar-benar? Apakah ini benar?",
  ui_story_5045_50451801_103_dialog_content = "T-Tapi saat itu, aku harus melakukannya.",
  ui_story_5045_50451801_104_dialog_content = "Saat itu, saya takut Farrell akan mengetahui tentang kursus swadaya kami...",
  ui_story_5045_50451801_105_dialog_content = "Jika itu terjadi, Guru Swadaya akan menghukum saya.",
  ui_story_5045_50451801_106_dialog_content = "Sekarang setelah Anda menangkapnya, saya tidak perlu takut!",
  ui_story_5045_50451801_107_dialog_content = "Yah, itu memang bisa dimaafkan.",
  ui_story_5045_50451801_108_dialog_content = "Kalau begitu mari kita panggil saksi kedua.",
  ui_story_5045_50451801_109_dialog_content = "Yang Mulia, nama saya Karl.",
  ui_story_5045_50451801_110_dialog_content = "Saya punya janji untuk pergi makan malam dengan Bacon kemarin, tapi dia tidak pernah muncul.",
  ui_story_5045_50451801_111_dialog_content = "Untungnya, Bacon memberi tahu saya ke mana dia pergi. Butuh waktu lama bagiku untuk menemukannya.",
  ui_story_5045_50451801_112_dialog_content = "Akhirnya, saya menemukan kursus swadaya yang legendaris.",
  ui_story_5045_50451801_113_dialog_content = "Ketika saya sampai di sana, saya mendengar Bacon mengatakan dia tidak ingin menerima tugas yang diberikan kepadanya oleh Guru Swadaya, dan dia bersikeras untuk pergi bersama saya.",
  ui_story_5045_50451801_114_dialog_content = "Saya merasakan ada sesuatu yang sangat salah, jadi saya menyalakan api di tengah kekacauan dan melarikan diri dengan Bacon.",
  ui_story_5045_50451801_115_dialog_content = "Untuk melarikan diri, Guru Swadaya yang legendaris melepas jubah hitamnya dan mengungkapkan wajah aslinya.",
  ui_story_5045_50451801_116_dialog_content = "Dengan kata lain, Anda melihat seperti apa Guru Swadaya itu?",
  ui_story_5045_50451801_117_dialog_content = "Ya.",
  ui_story_5045_50451801_118_dialog_content = "Dan apakah Anda melihat Guru Swadaya ini di pengadilan hari ini?",
  ui_story_5045_50451801_119_dialog_content = "Ya. Guru Swadaya adalah pria yang duduk di dermaga.",
  ui_story_5045_50451801_120_dialog_content = "(Bagaimana ini bisa terjadi? Apa yang orang Karl ini pikir sedang dia lakukan...?)",
  ui_story_5045_50451801_121_dialog_content = "(Oh ya, saya tahu sesuatu yang mungkin berhasil di sini!)",
  ui_story_5045_50451801_122_option_content = "Tautkan pikiran!",
  ui_story_5045_50451801_123_dialog_content = "(Itu adalah langkah cerdas yang mengaku sebagai Caelestite saat membuat kursus swadaya itu.)",
  ui_story_5045_50451801_124_dialog_content = "(Sekarang semua orang tahu bahwa Guru Swadaya adalah Caelestite, dan tidak ada yang tahu tentang identitas saya yang sebenarnya.)",
  ui_story_5045_50451801_125_dialog_content = "(Sayang sekali kursus swadaya harus berakhir di sini... Untungnya, saya menghasilkan lebih dari cukup.)",
  ui_story_5045_50451801_126_dialog_content = "Sial, Guru Swadaya yang sebenarnya sebenarnya adalah Karl!",
  ui_story_5045_50451801_127_dialog_content = "(Sayangku PlayerName, Saya tahu ada kemungkinan Anda sedang mendengarkan suara hati saya sekarang.)",
  ui_story_5045_50451801_128_dialog_content = "Apa? Bagaimana dia tahu?",
  ui_story_5045_50451801_129_dialog_content = "(Kamu mungkin bisa mendengar pikiran orang berkat bakat spesialmu...)",
  ui_story_5045_50451801_130_dialog_content = "(Tapi saya bisa menyimpulkan pikiran Anda melalui setiap gerakan Anda.)",
  ui_story_5045_50451801_131_dialog_content = "(Jadi, siapa di antara kita yang lebih kuat?)",
  ui_story_5045_50451801_132_dialog_content = "Yang mulia!",
  ui_story_5045_50451801_133_dialog_content = "Saya telah menemukan melalui kemampuan psikis saya bahwa Karl adalah Guru Swadaya!",
  ui_story_5045_50451801_134_dialog_content = "Terdakwa ini benar-benar tahu bagaimana memanipulasi orang!",
  ui_story_5045_50451801_135_dialog_content = "Bagaimana kita bisa percaya apa pun yang dia katakan !?",
  ui_story_5045_50451801_136_dialog_content = "Sepertinya metode ini tidak akan berhasil di sini ...",
  ui_story_5045_50451801_137_dialog_content = "Tapi pasti ada kontradiksi yang tersembunyi di suatu tempat <color=#1875ad>Kesaksian Karl</color>.",
  ui_story_5045_50451801_138_dialog_content = "Apa maksudmu?",
  ui_story_5045_50451801_139_dialog_content = "Emm, aku hanya ingin mengatakan...",
  ui_story_5045_50451801_140_dialog_content = "Karl mengatakan kepada saya kemarin bahwa dia belum pernah mengikuti kursus swadaya dan bahkan tidak tahu di mana diadakannya!",
  ui_story_5045_50451801_141_dialog_content = "Tapi tadi, dia mengatakan bahwa Bacon memberitahunya alamatnya!",
  ui_story_5045_50451801_142_dialog_content = "Itu karena, saat aku melihatmu, aku belum mengatur untuk makan dengan Bacon.",
  ui_story_5045_50451801_143_dialog_content = "Ah, benarkah? Bacon, jam berapa kamu membuat janji dengan Karl?",
  ui_story_5045_50451801_144_dialog_content = "Pukul sepuluh pagi, kami berdua sepakat untuk—",
  ui_story_5045_50451801_145_dialog_content = "Aku bertanya padamu, Bacon. Kapan kamu seharusnya bertemu Karl?",
  ui_story_5045_50451801_146_dialog_content = "Kami membuat janji jam 10 pagi untuk makan malam jam 6 sore...",
  ui_story_5045_50451801_147_dialog_content = "Itu aneh. Saya ditangkap pada pukul empat kemarin sore.",
  ui_story_5045_50451801_148_dialog_content = "Bagaimana saya bisa berada di sana di kursus swadaya dengan kalian berdua?",
  ui_story_5045_50451801_149_dialog_content = "Bacon ketakutan setengah mati kemarin! Dia tidak bisa mengingat dengan jelas untuk sesaat!",
  ui_story_5045_50451801_150_dialog_content = "Kami punya janji makan siang jam dua belas, kan?",
  ui_story_5045_50451801_151_dialog_content = "Benar, itu dia... Aku salah ingat tadi karena aku sangat takut kemarin...",
  ui_story_5045_50451801_152_dialog_content = "Setelah ditakuti demikian, korban memang bisa mengalami gangguan ingatan.",
  ui_story_5045_50451801_153_dialog_content = "Tapi yang lebih penting, PlayerName...",
  ui_story_5045_50451801_154_dialog_content = "Justice Knights menemukan banyak kartu kehadiran yang tidak terpakai di tempat tinggal sementara Anda.",
  ui_story_5045_50451801_155_dialog_content = "Apa pembelaanmu?",
  ui_story_5045_50451801_156_option_content = "Seseorang menanamnya!",
  ui_story_5045_50451801_157_dialog_content = "Semua bukti mengarah padamu. Anda sebaiknya menjelaskan diri Anda sejelas mungkin.",
  ui_story_5045_50451801_158_dialog_content = "Tapi saya benar-benar tidak tahu dari mana datangnya kartu absen ini.",
  ui_story_5045_50451801_159_dialog_content = "Apa aku tidur sambil berjalan atau semacamnya!?",
  ui_story_5045_50451801_160_option_content = "Keberatan!",
  ui_story_5045_50451801_161_dialog_content = "Apa yang memberi Anda hak untuk menggeledah tempat tinggal saya sesuka hati?",
  ui_story_5045_50451801_162_dialog_content = "Anda adalah tersangka nomor satu dalam kasus ini. Dengan kemungkinan penyebab seperti itu, menggeledah tempat tinggal Anda sah dan masuk akal.",
  ui_story_5045_50451801_163_dialog_content = "Hmm…",
  ui_story_5045_50451801_164_option_content = "Dimanakah Tina Dan Leyn?",
  ui_story_5045_50451801_165_dialog_content = "Saya ingin mereka bersaksi untuk saya!",
  ui_story_5045_50451801_166_dialog_content = "Mereka sibuk menyelidiki kasus mereka masing-masing, dan saya tidak dapat menemukan mereka.",
  ui_story_5045_50451801_167_dialog_content = "Apa yang harus kulakukan?",
  ui_story_5045_50451801_168_dialog_content = "Hanya itu yang ingin Anda katakan?",
  ui_story_5045_50451801_169_dialog_content = "Eh, aku...",
  ui_story_5045_50451801_170_dialog_content = "<color=#737378>Bum!</color>",
  ui_story_5045_50451801_171_dialog_content = "Malam Putih di atas. Sudah waktunya untuk...",
  ui_story_5045_50451801_172_dialog_content = "Tunggu!",
  ui_story_5045_50451801_173_dialog_content = "Sungguh?",
  ui_story_5045_50451801_174_dialog_content = "Yang Mulia, kami masih memiliki saksi yang belum hadir di pengadilan!",
  ui_story_5045_50451801_175_dialog_content = "Maaf, PlayerName... Kita belum terlambat, bukan?",
  ui_story_5045_50451801_176_dialog_content = "Leyn, Tina...",
  ui_story_5045_50451801_177_dialog_content = "Sidang belum berakhir. Saya meminta saksi yang tersisa sekarang maju dan bersaksi!",
  ui_story_5045_50451801_178_dialog_content = "Yang Mulia, nama saya Fanny...",
  ui_story_5045_50451801_179_dialog_content = "F-Fanny? Apakah kamu baik-baik saja!?",
  ui_story_5045_50451801_180_dialog_content = "...!?",
  ui_story_5045_50451801_181_dialog_content = "Aku baik-baik saja, Bacon. Jangan khawatirkan aku. Kita bisa memberitahu ketua hakim yang sebenarnya.",
  ui_story_5045_50451801_182_dialog_content = "Jangan takut. Hall of Justice akan memastikan keamanan Anda.",
  ui_story_5045_50451801_183_dialog_content = "Kemarin saya <color=#1875ad>diculik</color>.",
  ui_story_5045_50451801_184_dialog_content = "Para penculik menyandera saya dan menggunakan saya untuk mengancam Bacon, memaksanya untuk bersaksi melawan orang yang tidak bersalah.",
  ui_story_5045_50451801_185_dialog_content = "Ya! Itu benar! Semua yang saya katakan barusan adalah apa yang dikatakan Guru Swadaya untuk saya katakan!",
  ui_story_5045_50451801_186_dialog_content = "Aku takut setengah mati bahwa mereka akan menyakiti Fanny...",
  ui_story_5045_50451801_187_dialog_content = "Untungnya, hakim Leyn Dan Tina menemukanku dan menyelamatkanku.",
  ui_story_5045_50451801_188_dialog_content = "Sekarang, saya bisa bersaksi di pengadilan.",
  ui_story_5045_50451801_189_dialog_content = "Apa kamu yakin PlayerName tidak bersalah?",
  ui_story_5045_50451801_190_dialog_content = "Dia, Yang Mulia.",
  ui_story_5045_50451801_191_dialog_content = "Adapun Guru Swadaya yang asli, meskipun dia memakai topeng, saya ingat suaranya ...",
  ui_story_5045_50451801_192_dialog_content = "Karl, kami memperlakukanmu sebagai teman. Mengapa Anda melakukan ini kepada kami?",
  ui_story_5045_50451801_193_dialog_content = "...",
  ui_story_5045_50451801_194_dialog_content = "Yang Mulia, ini pasti semacam kesalahpahaman! Semacam kesalahpahaman besar!",
  ui_story_5045_50451801_195_dialog_content = "Wanita Irridon, kami menemukan pintu masuk ke ruang bawah tanah rahasia di rumahnya.",
  ui_story_5045_50451801_196_dialog_content = "Jika kita masuk dan mencari, kita mungkin menemukan lebih banyak bukti.",
  ui_story_5045_50451801_197_dialog_content = "Tepat sekali, dan kami meminta para Ksatria Lumo untuk mengepung seluruh area.",
  ui_story_5045_50451801_198_dialog_content = "Kami hanya menunggu konfirmasi Anda, Lady Irridon.",
  ui_story_5045_50451801_199_dialog_content = "...",
  ui_story_5045_50451801_200_dialog_content = "Karl mencoba melarikan diri! Hati-Hati!",
  ui_story_5045_50451801_201_dialog_content = "Berhenti sekarang juga!",
  ui_story_5045_50451801_202_dialog_content = "Anda tidak bisa melarikan diri!",
  ui_story_5045_50451801_203_dialog_content = "Argh…",
  ui_story_5045_50451901_1_dialog_content = "<color=#737378>Waktu: 12:00 siang</color>",
  ui_story_5045_50451901_2_dialog_content = "<color=#737378>Lokasi: Lumo Hall of Justice, Kantor Divisi Percintaan</color>",
  ui_story_5045_50451901_3_dialog_content = "Wanita Irridon, itu benar-benar cobaan yang berat barusan!",
  ui_story_5045_50451901_4_dialog_content = "Wanita Irridon sedang berbicara dengan PlayerName. Simpan nafasmu.",
  ui_story_5045_50451901_5_dialog_content = "... Saya akan memaafkan Anda kali ini, tetapi hanya karena Anda benar-benar mengangkat poin yang bagus.",
  ui_story_5045_50451901_6_dialog_content = "PlayerName, Saya melakukan ketidakadilan yang besar hari ini.",
  ui_story_5045_50451901_7_dialog_content = "Wanita Irridon... Kamu tidak tahu aku dijebak selama ini, kan?",
  ui_story_5045_50451901_8_dialog_content = "Apakah itu yang saya katakan?",
  ui_story_5045_50451901_9_dialog_content = "Pikiranku adalah, jika kamu benar-benar mendapatkan uang sebanyak itu...",
  ui_story_5045_50451901_10_dialog_content = "Anda tidak akan mau datang ke Hall of Justice untuk membantu kami dengan gaji sebesar itu.",
  ui_story_5045_50451901_11_dialog_content = "Erm... Aku benar-benar tidak tahu apakah aku harus senang atau sedih.",
  ui_story_5045_50451901_12_dialog_content = "Tina, Leyn, kinerja Anda hari ini benar-benar mengejutkan saya.",
  ui_story_5045_50451901_13_dialog_content = "Bagaimana Anda tahu bahwa Fanny telah diculik?",
  ui_story_5045_50451901_14_dialog_content = "Kami menemukan klienku, Farrell. Dia tidak mau mengatakan apa-apa pada awalnya, tapi terima kasih Tina...",
  ui_story_5045_50451901_15_dialog_content = "Saya tahu Anda tidak ingin bersaksi melawan wanita yang Anda cintai, tetapi ini adalah satu-satunya cara Anda dapat menyelamatkannya!",
  ui_story_5045_50451901_16_dialog_content = "Jika tidak, dia akan selamanya dimanipulasi oleh Guru Swadaya itu dan hidup dalam penderitaan dan penghinaan!",
  ui_story_5045_50451901_17_dialog_content = "Apakah ini... satu-satunya cara untuk menyelamatkannya?",
  ui_story_5045_50451901_18_dialog_content = "Farrell memberi tahu kami bahwa dia memperhatikan hal-hal aneh tertentu yang dilakukan Sophie.",
  ui_story_5045_50451901_19_dialog_content = "Alasan dia sangat ingin Sophie menikah dengannya adalah agar dia bisa menyelamatkannya dari cengkeraman Guru Swadaya.",
  ui_story_5045_50451901_20_dialog_content = "Dia juga memberi tahu kami beberapa tempat yang biasa dikunjungi Sophie.",
  ui_story_5045_50451901_21_dialog_content = "Tempat ini sangat besar. Di mana kita harus mulai...?",
  ui_story_5045_50451901_21X1_dialog_content = "Hah? Dimana Leyn?",
  ui_story_5045_50451901_22_dialog_content = "Ladies, apakah Anda melihat sekelompok orang yang mencurigakan di sekitar sini?",
  ui_story_5045_50451901_23_dialog_content = "Ya! Kami pasti punya! Biarkan saya memberi tahu Anda semua tentang mereka, tampan!",
  ui_story_5045_50451901_24_dialog_content = "Di sana, kami tidak hanya menemukan Fanny, tetapi juga seorang gadis kecil.",
  ui_story_5045_50451901_25_dialog_content = "Gadis kecil itu adalah saudara perempuan Sophie...",
  ui_story_5045_50451901_26_dialog_content = "Dia menggunakan banyak sandera untuk membengkokkan orang-orang baik ini sesuai keinginannya. Karl sama sekali tidak bisa diperbaiki!",
  ui_story_5045_50451901_27_dialog_content = "Namun, Sophie memiliki kesempatan untuk menyelamatkan dirinya sendiri, dan sekarang dia tidak bisa lepas dari penilaian Balai Kehakiman.",
  ui_story_5045_50451901_28_dialog_content = "Sepertinya Anda telah berkembang pesat selama waktu Anda dengan Divisi Percintaan.",
  ui_story_5045_50451901_29_dialog_content = "Te-Terima kasih sudah mengatakannya, Nona Irridon!",
  ui_story_5045_50451901_30_dialog_content = "Sebenarnya, kami berutang kesuksesan kami hari ini kepada PlayerNameintuisi.",
  ui_story_5045_50451901_31_dialog_content = "Hah? Masa?",
  ui_story_5045_50451901_32_dialog_content = "PlayerName memberi tahu kami sebelum dia ditangkap bahwa mungkin petunjuknya tersembunyi dalam dua kasus yang dia coba sebelumnya.",
  ui_story_5045_50451901_33_dialog_content = "Itu pada dasarnya hanya saya yang berbicara pada diri saya sendiri. Saya tidak yakin apa-apa pada saat itu ...",
  ui_story_5045_50451901_34_dialog_content = "Bagaimanapun, kami memecahkan kasus besar kali ini!",
  ui_story_5045_50451901_35_dialog_content = "Wanita Irridon, apakah Anda mempertimbangkan untuk memberi kami hadiah?",
  ui_story_5045_50451901_36_dialog_content = "Tina...",
  ui_story_5045_50451901_37_dialog_content = "Bagaimana Anda bisa meminta hal seperti itu dengan begitu berani?",
  ui_story_5045_50451901_38_dialog_content = "Sehubungan dengan hadiah, saya sudah menyiapkan sesuatu untuk Anda.",
  ui_story_5045_50451901_39_dialog_content = "Tunggu... Lakukan Angel dan saya mendapatkan sesuatu juga?",
  ui_story_5045_50451901_40_dialog_content = "PlayerName, terima kasih telah datang untuk membantu kami ketika Hall of Justice menghadapi kekurangan personel yang parah.",
  ui_story_5045_50451901_41_dialog_content = "Selama periode ini, Anda tidak hanya membantu para hakim Divisi Percintaan berhasil mengadili dua kasus...",
  ui_story_5045_50451901_42_dialog_content = "Anda mengambilnya sendiri untuk membasmi kejahatan ...",
  ui_story_5045_50451901_43_dialog_content = "Dan membantu kami membawa Guru Swadaya yang meneror orang-orang Lumopolis ke pengadilan.",
  ui_story_5045_50451901_44_dialog_content = "Para anggota Balai Kehakiman telah menyepakati bahwa suatu <color=#1875ad>Hakim Kehormatan</color> piala akan diberikan kepada Anda.",
  ui_story_5045_50451901_45_dialog_content = "Wow, itu patung! Ini terlihat sangat istimewa!",
  ui_story_5045_50451901_46_dialog_content = "PlayerName, trofi ini memiliki bobot yang luar biasa.",
  ui_story_5045_50451901_47_dialog_content = "Hah? Akankah saya dapat membawanya?",
  ui_story_5045_50451901_48_dialog_content = "Maksud saya, kehormatan menerima trofi ini tidak boleh dianggap enteng.",
  ui_story_5045_50451901_49_dialog_content = "Heehee! Jika Anda tidak bisa menanganinya, PlayerName, Saya dapat menggunakan Tangan Ilahi saya untuk membawanya untuk Anda!",
  ui_story_5045_50451901_50_dialog_content = "Anda memberi saya piala ...?",
  ui_story_5045_50451901_51_dialog_content = "Apa? Anda tidak menginginkannya?",
  ui_story_5045_50451901_52_dialog_content = "Saya hanya ingin tahu apakah Anda tidak membutuhkan bantuan saya lagi?",
  ui_story_5045_50451901_53_dialog_content = "Ya, Anda bisa melihatnya seperti itu.",
  ui_story_5045_50451901_54_dialog_content = "Baru-baru ini, banyak kasus di Lumopolis sebenarnya terkait dengan Guru Swadaya.",
  ui_story_5045_50451901_55_dialog_content = "Sekarang Guru Swadaya telah ditangkap, kasus Divisi Percintaan secara bertahap akan berkurang.",
  ui_story_5045_50451901_56_dialog_content = "Juga, ada banyak anak muda dari Dawn Akademi siap datang ke sini untuk magang. Segera, kita tidak akan lagi kekurangan staf.",
  ui_story_5045_50451901_57_dialog_content = "Tentu saja, tetapi jika Anda masih ingin tinggal ...",
  ui_story_5045_50451901_58_dialog_content = "Anda dapat berlatih bersama dengan anak-anak muda, dan tetap bertahan setelah melewati peninjauan di akhir masa percobaan.",
  ui_story_5045_50451901_59_dialog_content = "Proses ini dapat berlangsung dari setengah tahun hingga satu tahun.",
  ui_story_5045_50451901_60_dialog_content = "Tapi aku harus kembali dan mengurus Cloud Gardens, dan teman-temanku selalu membutuhkanku untuk bertualang bersama mereka...",
  ui_story_5045_50451901_61_dialog_content = "Mungkin sebaiknya waktuku di Hall of Justice berakhir di sini.",
  ui_story_5045_50451901_62_dialog_content = "Seperti yang saya katakan — hidup di Hall of Justice bukan untuk semua orang.",
  ui_story_5045_50451901_63_dialog_content = "Jadi, PlayerName, apakah kamu pergi sekarang?",
  ui_story_5045_50451901_64_dialog_content = "PlayerName…",
  ui_story_5045_50451901_65_dialog_content = "(Saya merasa seperti saya harus mengatakan sesuatu sekarang.)",
  ui_story_5045_50451901_66_dialog_content = "(Tapi apa yang harus saya katakan?)",
  ui_story_5045_50451901_67_dialog_content = "(Oh! Saya mengerti!)",
  ui_story_5045_50451901_68_dialog_content = "Ya, ya—tidak perlu melihat ini lagi.",
  ui_story_5045_50451901_69_dialog_content = "(Apakah itu? Aku merasa seperti melupakan sesuatu...)",
  ui_story_5045_50451901_70_dialog_content = "Saya masih punya ini <color=#1875ad>layang-layang</color>.",
  ui_story_5045_50451901_71_dialog_content = "PlayerName, apa yang harus dilakukan dengan layang-layang ini sekarang?",
  ui_story_5045_50451901_72_dialog_content = "Kita harus memberikannya pada Farrell, ksatria yang menunggu Sophie keluar dari penjara.",
  ui_story_5045_50451901_73_dialog_content = "Saya pikir setelah Sophie dibebaskan dari penjara, mungkin mereka akan memiliki kesempatan untuk menerbangkan layang-layang ini bersama.",
  ui_story_5045_50451901_74_dialog_content = "Baiklah, aku akan memastikan dia mendapatkannya.",
  ui_story_5045_50451901_75_dialog_content = "Lain kali kau kembali ke Lumopolis, mungkin kita juga punya kesempatan untuk menerbangkan layang-layang bersama...",
  ui_story_5045_50451901_76_dialog_content = "Tentu saja! Bukannya kita tidak akan pernah bertemu lagi!",
  ui_story_5045_50451901_77_dialog_content = "Bagus. Lalu kita akan membuat layang-layang kita sendiri saat kau kembali!",
  ui_story_5045_50451901_78_dialog_content = "Aku akan menahanmu untuk itu!",
  ui_story_5045_50451901_79_dialog_content = "milik Tina <color=#1875ad>patung tanah liat</color> masih di sini.",
  ui_story_5045_50451901_80_dialog_content = "PlayerName, Saya ingin Anda memiliki ini!",
  ui_story_5045_50451901_81_dialog_content = "Sungguh?",
  ui_story_5045_50451901_82_dialog_content = "Tapi jangan salah paham, saya hanya ingin berterima kasih karena telah membuat pekerjaan saya jauh lebih mudah dan lebih menyenangkan saat Anda berada di sini.",
  ui_story_5045_50451901_83_dialog_content = "Karena kita bekerja di Divisi Percintaan, tentu saja, aku berharap yang terbaik untukmu di masa depan...",
  ui_story_5045_50451901_84_dialog_content = "Ketika Anda bertemu seseorang yang Anda sukai, dan orang itu juga menyukai Anda, saya tahu Anda akan memiliki cinta manis yang bertahan selamanya!",
  ui_story_5045_50451901_85_dialog_content = "Seperti dua patung tanah liat kecil ini...",
  ui_story_5045_50451901_86_dialog_content = "Citra cinta, yang diekstraksi dari bumi dan ditempa oleh api, akhirnya menjadi ikatan abadi!",
  ui_story_5045_50451901_87_dialog_content = "Terima kasih banyak, Tina!",
  ui_story_5045_50451901_88_dialog_content = "Meskipun, saya pikir mungkin masih terlalu dini dalam hidup saya untuk menerima berkat semacam itu...",
  ui_story_5045_50451901_89_dialog_content = "Ini tidak terlalu dini sama sekali!",
  ui_story_5045_50451901_90_dialog_content = "Maksud saya... jika Anda tidak dapat menemukan seseorang yang Anda sukai, kembali saja ke Lumopolis, atau mungkin Hall of Justice.",
  ui_story_5045_50451901_91_dialog_content = "Tentu saja, saya berjanji akan kembali.",
  ui_story_5045_50451901_92_dialog_content = "B-benarkah?",
  ui_story_5045_50451901_93_dialog_content = "Kemudian kita bisa pergi ke pedesaan dan membuat banyak patung tanah liat kecil dan kemudian memberikannya kepada semua pecinta di luar sana!",
  ui_story_5045_50451901_94_dialog_content = "Anda bertaruh!",
  ui_story_5045_50451901_95_dialog_content = "Tanpa Divisi Percintaan, saya tidak akan pernah mendapatkan trofi berharga ini.",
  ui_story_5045_50451901_96_dialog_content = "Saya ingin meninggalkan trofi ini dengan Divisi Percintaan.",
  ui_story_5045_50451901_97_dialog_content = "Ini adalah ide bagus!",
  ui_story_5045_50451901_98_dialog_content = "Tapi di mana Anda ingin meletakkannya, PlayerName?",
  ui_story_5045_50451901_99_dialog_content = "Apakah Anda benar-benar perlu bertanya? Taruh saja di mejaku!",
  ui_story_5045_50451901_100_dialog_content = "Coba lihat-lihat—aku satu-satunya yang mejanya cukup bersih untuk benda itu!",
  ui_story_5045_50451901_101_dialog_content = "Kupikir...",
  ui_story_5045_50451901_102_dialog_content = "Setiap orang harus bergiliran meletakkannya di meja mereka.",
  ui_story_5045_50451901_103_dialog_content = "Ya, itu adil!",
  ui_story_5045_50451901_104_dialog_content = "Jadi, sudah diputuskan!",
  ui_story_5045_50451901_105_dialog_content = "Setiap orang?",
  ui_story_5045_50451901_106_dialog_content = "Itu termasuk saya, kan? Hai...",
  ui_story_5045_50451901_107_dialog_content = "Di buku catatan ini...",
  ui_story_5045_50451901_108_dialog_content = "Saya mencatat semuanya dan semua orang yang saya temui setelah datang ke Divisi Percintaan.",
  ui_story_5045_50451901_109_dialog_content = "Ketidakberdayaan dan sakit hati kami ketika kami menghadapi kesulitan besar bersama ...",
  ui_story_5045_50451901_110_dialog_content = "Dan kebahagiaan serta rasa pencapaian setelah membuat keputusan yang sukses bersama!",
  ui_story_5045_50451901_111_dialog_content = "Selama saya memiliki ini, saya tidak akan pernah melupakan hari-hari indah yang saya habiskan di Divisi Percintaan!",
  ui_story_5045_50451901_112_dialog_content = "Sementara saya pergi, semuanya — tolong tuliskan perasaan Anda di buku catatan Anda untuk saya.",
  ui_story_5045_50451901_113_dialog_content = "Di masa depan, ketika saya kembali ...",
  ui_story_5045_50451901_114_dialog_content = "Saya akan dapat mendengar semua tentang kasus aneh yang saya lewatkan!",
  ui_story_5045_50451901_115_dialog_content = "Benar...",
  ui_story_5045_50451901_116_dialog_content = "PlayerName, kamu jahat sekali...",
  ui_story_5045_50451901_117_dialog_content = "Berhentilah mencoba membuat kami semua menangis!",
  ui_story_5045_50451901_118_dialog_content = "Terima kasih atas sarannya, PlayerName...",
  ui_story_5045_50451901_119_dialog_content = "Saya akan merekam semua kasus yang paling menarik untuk Anda!",
  ui_story_5045_50451901_120_dialog_content = "Apakah Anda melihat ini, Angel? Mulailah membuat catatan!",
  ui_story_5045_50451901_121_dialog_content = "... Oke!",
  ui_story_5045_50451901_122_dialog_content = "Selamat tinggal semuanya.",
  ui_story_5045_50451901_123_dialog_content = "Selamat tinggal, Divisi Percintaan.",
  ui_story_5045_50451901_124_dialog_content = "Aku tahu bahwa suatu hari...",
  ui_story_5045_50451901_125_option_content = "Sampai jumpa lagi!"
}
